window.HB_TR["genesis"]["ur"]=["1. ابتدا میں خدا نے آسمان اور زمین کو پیدا کیا۔\n2۔ اور زمین بے شکل اور خالی تھی؛ اور گہرائی کے چہرے پر اندھیرا {تھا}۔ اور خدا کی روح پانی کے چہرے پر حرکت کرنے لگی۔\n3۔ اور خدا نے کہا، روشنی ہو: اور روشنی آ گئی۔\n4۔ اور خدا نے روشنی دیکھی، کہ وہ اچھی ہے: اور خدا نے روشنی کو تاریکی سے جدا کیا۔ {روشنی سے...: عبرانی روشنی اور تاریکی کے درمیان}\n5۔ اور خدا نے روشنی کو دن کہا، اور تاریکی کو رات۔ اور شام اور صبح پہلا دن تھا۔ {اور شام...: عبرانی۔ اور شام تھی، اور صبح وغیرہ۔\n6۔ اور خدا نے کہا، پانیوں کے درمیان ایک آسمان ہو، اور وہ پانیوں کو پانیوں سے جدا کرے۔ {آسمان: عبرانی۔ توسیع}\n7۔ اور خدا نے فلک بنایا، اور فلک کے نیچے موجود پانیوں کو ان پانیوں سے جدا کیا جو آسمان کے اوپر تھے: اور ایسا ہی ہوا۔\n8۔ اور خدا نے آسمان کو آسمان کہا۔ اور شام اور صبح دوسرا دن تھے۔ {اور شام...: عبرانی۔ اور شام تھی، اور صبح وغیرہ۔\n9۔ اور خدا نے کہا، آسمان کے نیچے پانی ایک جگہ جمع ہو جائیں، اور خشک زمین ظاہر ہو: اور ایسا ہی ہوا۔\n10۔ اور خدا نے خشک {زمین} کو زمین کہا؛ اور پانیوں کے جمع ہونے کو سمندر کہا گیا: اور خدا نے دیکھا کہ یہ اچھا تھا۔\n11۔ اور خدا نے فرمایا، زمین گھاس اگائے، وہ جڑی بوٹی جو بیج دیتی ہے، اور پھل دار درخت اپنی نسل کے مطابق پھل دے گا، جس کا بیج خود زمین پر ہے: اور ایسا ہی ہوا۔ {گھاس: عبرانی۔ نرم گھاس}\n12۔ اور زمین نے گھاس پیدا کی، {اور} اپنی نسل کے مطابق بیج دینے والی جڑی بوٹی، اور وہ درخت جو پھل دیتا تھا، جس کا بیج خود اس کی نسل کے مطابق تھا، اور خدا نے دیکھا کہ یہ اچھا تھا۔\n13۔ اور شام اور صبح تیسرے دن تھے۔ {اور شام...: عبرانی۔ اور شام تھی، اور صبح وغیرہ۔\n14۔ اور خدا نے کہا، آسمان کے آسمان میں روشنی ہو جو دن اور رات کو جدا کرے؛ اور انہیں نشانات، موسموں، دنوں اور سالوں کے لیے ہو: {دن...: عبرانی۔ دن اور رات کے درمیان}\n15۔ اور انہیں آسمان کے آسمان میں روشنی کے لیے بنایا جائے تاکہ زمین پر روشنی آئیں: اور ایسا ہی ہوا۔\n16۔ اور خدا نے دو عظیم روشنیاں بنائیں؛ دن پر بڑی روشنی حکمرانی کرتی ہے، اور کم روشنی رات پر حکمرانی کرتی: {اس نے ستارے بھی بنائے}۔ {دن پر حکمرانی کرنے کے لیے...: عبرانی۔ دن کے اصول کے لیے، وغیرہ۔}\n17۔ اور خدا نے انہیں آسمان کے آسمان میں رکھا تاکہ زمین پر روشنی ڈال سکیں،\n18۔ اور دن اور رات پر حکمرانی کرنا، اور روشنی کو تاریکی سے جدا کرنا: اور خدا نے دیکھا کہ یہ اچھا ہے۔\n19۔ اور شام اور صبح چوتھے دن تھے۔ {اور شام...: عبرانی۔ اور شام تھی، اور صبح وغیرہ۔\n20۔ اور خدا نے کہا، پانی اس حرکت کرنے والی مخلوق کو وافر مقدار میں لے آئے جس میں زندگی ہے، اور پرندے {جو} آسمان کے کھلے آسمان میں زمین کے اوپر اڑ سکیں۔ {حرکت کرتے ہوئے: یا، رینگتے ہوئے} {زندگی: عبرانی۔ روح} {مرغی...: عبرانی۔ پرندوں کو اڑنے دو} {کھولو...: عبرانی۔ آسمان کے آسمان کا چہرہ}\n21۔ اور خدا نے عظیم وہیلز پیدا کیے، اور ہر زندہ مخلوق جو حرکت کرتی ہے، جو پانی نے ان کی نسل کے مطابق وافر مقدار میں پیدا کی، اور ہر پروں والا پرندہ اپنی نسل کے مطابق: اور خدا نے دیکھا کہ یہ اچھا ہے۔\n22۔ اور خدا نے انہیں برکت دی، کہا، پھل دار بنو، بڑھو، اور سمندروں میں پانی بھر دو، اور زمین میں مرغی کو بڑھاؤ۔\n23۔ اور شام اور صبح پانچواں دن تھے۔ {اور شام...: عبرانی۔ اور شام تھی، اور صبح وغیرہ۔\n24۔ اور خدا نے فرمایا، زمین جاندار کو اس کی نسل کے بعد پیدا کرے، مویشی اور رینگنے والی مخلوق، اور زمین کا جانور اس کی نسل کے بعد پیدا کرے: اور ایسا ہی ہوا۔\n25۔ اور خدا نے زمین کے جانور کو اپنی نوع کے مطابق بنایا، اور مویشیوں کو ان کی نسل کے مطابق بنایا، اور زمین پر رینگنے والی ہر چیز کو اپنی نوع کے بعد بنایا: اور خدا نے دیکھا کہ یہ اچھا ہے۔\n26۔ اور خدا نے فرمایا، آؤ ہم انسان کو اپنی صورت پر بنائیں، اپنی شکل کے مطابق: اور انہیں سمندر کی مچھلیوں، ہوا کے پرندوں، مویشیوں پر، زمین پر، اور زمین پر رینگنے والی ہر چیز پر حکمرانی حاصل ہو۔\n27. یوں خدا نے انسان کو اپنی {اپنی} صورت میں پیدا کیا، خدا کی صورت میں اسے پیدا کیا؛ مرد اور عورت نے انہیں پیدا کیا۔\n28۔ اور خدا نے انہیں برکت دی، اور خدا نے ان سے کہا، پھل بڑھو، بڑھو، زمین کو بھر دو، اور اسے قابو میں رکھو: اور سمندر کی مچھلیوں، ہوا کے پرندوں، اور زمین پر چلنے والی ہر جاندار چیز پر حکمرانی کرو۔ {مووتھ: عبوری۔ کریپتھ}\n29۔ اور خدا نے کہا، دیکھو، میں نے تمہیں ہر وہ جڑی بوٹی دی ہے جس میں بیج ہے، جو زمین کے چہرے پر ہے، اور ہر درخت جس میں بیج دینے والے درخت کا پھل ہے؛ تمہارے لیے یہ گوشت کے لیے ہوگا۔ {سمت میں...: عبرانی۔ بیج بونا} {نتیجہ دے رہا ہے...: عبرانی۔ بیج بونا}\n30۔ اور زمین کے ہر جانور کو، اور ہوا کے ہر پرندے کو، اور زمین پر رینگنے والی ہر چیز کو، جس میں زندگی ہے، {میں نے ہر سبز جڑی بوٹی کو گوشت کے طور پر دیا ہے} اور ایسا ہی ہوا۔ {زندگی: عبرانی۔ ایک زندہ روح}\n31۔ اور خدا نے ہر چیز دیکھی جو اس نے بنائی تھی، اور دیکھو، وہ بہت اچھا تھا۔ اور شام اور صبح چھٹے دن تھے۔ {اور شام...: عبرانی۔ اور شام تھی، اور صبح وغیرہ۔","1۔ یوں آسمان اور زمین ختم ہو گئے، اور ان کی تمام فوج۔\n2۔ اور ساتویں دن خدا نے اپنا کام ختم کیا جو اس نے بنایا تھا؛ اور ساتویں دن اس نے اپنی تمام محنت سے آرام کیا۔\n3۔ اور خدا نے ساتویں دن کو برکت دی اور اسے مقدس بنایا: کیونکہ اس میں اس نے اپنے تمام کاموں سے آرام کیا جو خدا نے پیدا کیا اور بنایا۔ {تخلیق...: عبرانی۔ بنانے کے لیے بنایا گیا}\n4۔ یہ وہ نسلیں ہیں جو آسمانوں اور زمین کی نسلیں ہیں جب انہیں پیدا کیا گیا، اس دن جب خداوند خدا نے زمین اور آسمان بنائے،\n5۔ اور اس سے پہلے کھیت کا ہر پودا زمین میں تھا، اور اس سے پہلے کھیت کی ہر جڑی بوٹی اگ رہی تھی: کیونکہ خداوند خدا نے زمین پر بارش نہیں برسائی تھی، اور نہ ہی کوئی انسان تھا جو زمین کو جوتے۔\n6۔ لیکن زمین سے ایک دھند اٹھ گئی، جس نے پورے زمین کو پانی دیا۔ {وہاں...: یا، ایک دھند جو اوپر اٹھتی ہے، وغیرہ}\n7۔ اور خداوند خدا نے انسان کو زمین کی خاک سے پیدا کیا، اور اس کی ناک میں زندگی کی سانس پھونکی؛ اور انسان ایک زندہ روح بن گیا۔ {گرد و غبار کا...: عبرانی زمین کی گرد}\n8۔ اور خداوند خدا نے عدن میں مشرق کی طرف باغ لگایا؛ اور وہاں اس نے وہ آدمی رکھا جسے اس نے بنایا تھا۔\n9۔ اور زمین سے خداوند خدا کو ہر وہ درخت اگایا جو دیکھنے میں خوشگوار اور کھانے کے لیے اچھا ہو؛ باغ کے بیچ میں زندگی کا درخت بھی، اور نیکی اور برائی کے علم کا درخت۔\n10۔ اور ایک دریا عدن سے نکل کر باغ کو پانی دینے آیا؛ اور وہاں سے یہ الگ ہو گیا، اور چار سروں میں تقسیم ہو گیا۔\n11۔ پہلے {is} Pison کا نام: یعنی {ہے} جو پورے حویلہ کی زمین کو گھیرے ہوئے ہے، جہاں {سونا} ہے؛\n12۔ اور اس زمین کا سونا {ہے} اچھا ہے: وہاں {ہے} بیڈیلیئم اور اونکس اسٹون۔\n13۔ اور دوسرے دریا کا نام {ہے} گیہون: وہی {ہے} جو پورے ایتھوپیا کی زمین کو گھیرے ہوئے ہے۔ {ایتھوپیا: عبری۔ کش}\n14۔ اور تیسرے دریا کا نام {ہے} ہدیقل: وہ {ہے} جو آشور کے مشرق کی طرف جاتا ہے۔ اور چوتھا دریا فرات ہے۔ {طرف...: یا، مشرق کی طرف آشور}\n15۔ اور خداوند خدا نے اس آدمی کو لے کر جنت کے باغ میں رکھا تاکہ اسے تیار کرے اور سنبھالے۔ {آدمی: یا، ایڈم}\n16۔ اور خداوند خدا نے اس آدمی کو حکم دیا، کہا، باغ کے ہر درخت میں سے جو تم آزادانہ طور پر کھا سکتے ہو: {تم...: عبرانی۔ کھاؤ گے تو کھاؤ گے}\n17۔ لیکن اچھائی اور برائی کے علم کے درخت سے تم اسے نہیں کھاؤ گے، کیونکہ جس دن تم اس سے نکلنا چاہتے ہو تم یقینی طور پر مر جاؤ گے۔ {تم یقینا...: عبرانی۔ مرتے ہوئے تم مر جاؤ گے}\n18۔ اور خداوند خدا نے فرمایا، {یہ اچھا نہیں} کہ انسان اکیلا ہو؛ میں اس کے لیے ایک ہیلپ میٹ بناؤں گا۔ {منائیں...: عبرانی۔ جیسا کہ اس سے پہلے تھا}\n19۔ اور زمین سے خداوند خدا نے میدان کے ہر جانور اور ہوا کے ہر پرندے کو جنم دیا؛ اور انہیں آدم کے پاس لے آیا تاکہ وہ انہیں کیا کہے: اور جو بھی آدم ہر جاندار کو کہتا ہے، وہی اس کا نام تھا۔ {ایڈم: یا، وہ آدمی}\n20۔ اور آدم نے تمام مویشیوں کو نام دیے، ہوا کے پرندوں کو، اور میدان کے ہر جانور کو؛ لیکن ایڈم کے لیے کوئی مددگار ملاقات نہیں ملی۔ {دیا گیا: عبوری۔ بلایا گیا}\n21۔ اور خداوند خدا نے آدم پر گہری نیند آ گئی، اور وہ سو گیا، اور اس نے اس کی ایک پسلیوں میں سے ایک لے کر اس کے گوشت کو بند کر دیا؛\n22۔ اور وہ پسلی، جو خداوند خدا نے انسان سے چھین لی تھی، اس نے عورت بنائی، اور اسے مرد کے پاس لے آیا۔ {بنایا: عبرانی۔ تعمیر شدہ}\n23۔ اور آدم نے کہا، یہ اب میری ہڈیوں کی ہڈی ہے، اور میرے گوشت کا گوشت: اسے عورت کہا جائے گا، کیونکہ اسے انسان سے نکالا گیا۔ عورت: عبرانی۔ عیشہ} {آدمی: عبرانی۔ کچھ حد تک}\n24۔ اسی لیے آدمی اپنے باپ اور ماں کو چھوڑ کر اپنی بیوی سے چمٹ جائے گا: اور وہ ایک جسم ہوں گے۔\n25۔ اور وہ دونوں ننگے تھے، مرد اور اس کی بیوی، اور شرمندہ نہیں تھے۔","1۔ اب سانپ اس میدان کے کسی بھی جانور سے زیادہ باریک تھا جو خداوند خدا نے بنایا تھا۔ اور اس نے عورت سے کہا، ہاں، کیا خدا نے کہا، تم باغ کے ہر درخت کو نہیں کھاؤ گے؟ {ہاں...: عبرانی۔ ہاں، کیونکہ، وغیرہ۔}\n2۔ اور عورت نے سانپ سے کہا، ہم باغ کے درختوں کے پھل سے کھائیں گے:\n3۔ بلکہ اس درخت کے پھل کے بارے میں جو باغ کے بیچ میں ہے، خدا نے فرمایا ہے، تم اسے نہ کھاؤ گے، نہ چھوؤ گے، ورنہ مر جاؤ گے۔\n4۔ اور سانپ نے عورت سے کہا، تم ضرور نہیں مرو گی:\n5۔ کیونکہ خدا جانتا ہے کہ جس دن تم اس میں سے کھاؤ گے، تمہاری آنکھیں کھل جائیں گی، اور تم خدا کی طرح بنو گے، نیکی اور برائی کو جانتے ہوئے۔\n6۔ اور جب عورت نے دیکھا کہ درخت کھانے کے لیے اچھا ہے، اور آنکھوں کے لیے خوشگوار ہے، اور ایک ایسا درخت ہے جسے {انسان} عقلمند بنانا چاہیے، تو اس نے اس کے پھل سے لے کر کھایا، اور اپنے شوہر کو بھی اپنے ساتھ دے دیا؛ اور اس نے کھانا بھی کھایا۔ {pleasant: عبوری۔ ایک خواہش}\n7۔ اور دونوں کی آنکھیں کھل گئیں، اور وہ جان گئے کہ وہ برہنہ ہیں؛ اور انہوں نے انجیر کے پتے آپس میں سی دیے، اور اپنے لیے اپرون بنایا۔ {ایپرون: یا، تیار ہونے والی چیزیں}\n8۔ اور انہوں نے خداوند خدا کی آواز سنی جو دن کی ٹھنڈک میں باغ میں چل رہا تھا: اور آدم اور اس کی بیوی نے باغ کے درختوں میں خداوند خدا کی موجودگی سے چھپ کر خود کو چھپا لیا۔ {کول: عبوری۔ ہوا}\n9۔ اور خداوند خدا نے آدم کو پکارا اور کہا، تم کہاں ہو؟\n10۔ اور اس نے کہا، میں نے باغ میں تمہاری آواز سنی، اور میں ڈر گیا، کیونکہ میں ننگا تھا؛ اور میں نے خود کو چھپا لیا۔\n11۔ اور اس نے کہا، کس نے تمہیں بتایا کہ تم ننگے ہو؟ کیا تم نے وہ درخت کھا لیا ہے جسے میں نے تمہیں منع کیا تھا کہ تم نہ کھاؤ؟\n12۔ اور آدمی نے کہا، وہ عورت جسے تم نے میرے ساتھ دیا، اس نے مجھے درخت دیا، اور میں نے کھایا۔\n13۔ اور خداوند خدا نے عورت سے کہا، یہ کیا ہے جو تم نے کیا ہے؟ اور عورت نے کہا، سانپ نے مجھے بہکایا، اور میں نے کھایا۔\n14۔ اور خداوند خدا نے سانپ سے کہا، چونکہ تم نے یہ کیا ہے، تم تمام مویشیوں اور ہر کھیت کے جانور پر لعنت زدہ ہو؛ تم اپنے پیٹ پر جاؤ گے، اور اپنی زندگی کے سارے دن خاک کھاؤ گے:\n15۔ اور میں تمہارے اور عورت کے درمیان، اور تیری نسل اور اس کی نسل کے درمیان دشمنی پیدا کروں گا؛ یہ تمہارے سر پر چوٹ لگے گا، اور تم اس کی ایڑی پر چوٹ لگاؤ گے۔\n16۔ اس عورت سے اس نے کہا، میں تمہارا غم اور تمہاری اولاد کو بہت بڑھا دوں گا؛ غم میں تم بچے پیدا کرو گے؛ اور تمہاری خواہش تمہارے شوہر کے لیے ہوگی، اور وہ تم پر حکمرانی کرے گا۔ {تمہارے...: یا، اپنے شوہر کے تابع ہو}\n17۔ اور آدم سے کہا، کیونکہ تم نے اپنی بیوی کی آواز سنی ہے، اور اس درخت کو کھا لیا ہے جس کا میں نے تمہیں حکم دیا تھا، کہہ رہا ہوں، تم اسے مت کھاؤ گے: تمہارے لیے زمین پر لعنت ہے؛ تم اپنی زندگی کے سارے دن غم میں اسے کھاؤ گے؛\n18۔ کانٹے اور کانٹے بھی تمہارے لیے لائے گا؛ اور تم کھیت کی جڑی بوٹی کھاؤ گے؛ {لاؤ...: عبرانی کپ ٹو بڈ}\n19۔ اپنے چہرے کے پسینے میں روٹی کھاؤ گے، جب تک کہ تم زمین پر واپس نہ آ جاؤ؛ کیونکہ تم اس سے نکالے گئے تھے: کیونکہ تم خاک ہو، اور تم مٹی میں واپس جاؤ گے۔\n20۔ اور آدم نے اپنی بیوی کا نام حوا پکارا؛ کیونکہ وہ سب جانداروں کی ماں تھی۔ {ایو: عبرانی۔ چاواہ: یہی ہے زندہ}\n21۔ آدم اور اس کی بیوی کے لیے بھی خداوند خدا نے چمڑوں کے کوٹ بنائے اور انہیں کپڑے پہنائے۔\n22۔ اور خداوند خدا نے فرمایا، دیکھو، انسان ہم میں سے ایک بن گیا ہے، تاکہ اچھائی اور برائی کو جانے: اور اب، کہیں وہ اپنا ہاتھ نہ بڑھائے اور زندگی کے درخت کو بھی نہ لے لے، کھائے اور ہمیشہ زندہ رہے:\n23۔ لہٰذا خداوند خدا نے اسے عدن کے باغ سے بھیجا تاکہ وہ اس زمین کو جوئے جہاں سے اسے لیا گیا تھا۔\n24۔ تو اس نے اس آدمی کو نکال دیا؛ اور اس نے جنت کے باغ کے مشرق میں ایک شعلہ دار تلوار رکھی جو ہر طرف گھومتی تھی، تاکہ درخت زندگی کے راستے کو برقرار رکھ سکے۔","1۔ اور آدم اپنی بیوی حوا کو جانتا تھا؛ اور اس نے حاملہ ہوا، اور قابیل کو جنم دیا، اور کہا، میں نے خداوند سے ایک مرد پایا ہے۔ {کین: یعنی، حاصل کیا گیا، یا، حاصل کیا گیا}\n2۔ اور اس نے پھر اس کے بھائی ہابیل کو جنم دیا۔ اور ہابیل بھیڑوں کا پالنے والا تھا، لیکن قابیل زمین کا کاشتکار تھا۔ {ایبل: عبرانی۔ ہیبل} {ایک کیپر: عبرانی۔ ایک فیڈر}\n3۔ اور وقت کے ساتھ ایسا ہوا کہ قابیل نے زمین کے پھل سے خداوند کے لیے نذرانہ پیش کیا۔ {عمل میں...: عبرانی دنوں کے آخر میں}\n4۔ اور ہابیل، اس نے اپنے ریوڑ کے نخستہ بچوں اور ان کے چربی سے بھی لایا تھا۔ اور خداوند نے ہابیل اور اس کی قربانی کا احترام کیا: {ریوڑ: عبرانی۔ بھیڑیں، یا بکریا}\n5۔ لیکن قابیل اور اس کی نذرانہ کی اس نے کوئی عزت نہیں کی۔ اور قابیل بہت غصے میں تھا، اور اس کا چہرہ اتر گیا۔\n6۔ اور خداوند نے قابیل سے کہا، تم کیوں غصے میں ہو؟ اور تمہارا چہرہ کیوں جھکا ہوا ہے؟\n7۔ اگر تم اچھا کرو گے تو کیا تمہیں قبول نہیں کیا جائے گا؟ اور اگر تم ٹھیک نہیں ہو تو گناہ دروازے پر پڑا ہے۔ اور اس کی خواہش تمہارے لیے ہوگی، اور تم اس پر حکومت کرو گے۔ {قبول کیا جائے: یا، آپ کی عظمت حاصل کریں} {اور...: یا، تیری اطاعت میں}\n8۔ اور قابیل نے اپنے بھائی ہابیل سے بات کی: اور جب وہ میدان میں تھے تو قابیل نے ہابیل کے بھائی کے خلاف بغاوت کی اور اسے قتل کر دیا۔\n9۔ اور خداوند نے قابیل سے کہا، ہابیل تمہارا بھائی کہاں ہے؟ اور اس نے کہا، میں نہیں جانتا: کیا میں اپنے بھائی کا محافظ ہوں؟\n10۔ اور اس نے کہا، تم نے کیا کیا؟ تمہارے بھائی کے خون کی آواز زمین سے مجھ سے پکارتی ہے۔ {خون: عبرانی۔ bloods}\n11. اور اب تم اس زمین سے لعنت زدہ ہو گئی ہو، جس نے تمہارے بھائی کا خون تمہارے ہاتھ سے لینے کے لیے منہ کھولا ہے؛\n12۔ جب تم زمین کو کاشت کرو گے، تو وہ اب سے تمہیں اپنی طاقت نہیں دے گی؛ تم زمین پر ایک فراری اور آوارہ ہو گے۔\n13۔ اور قابیل نے خداوند سے کہا، میری سزا میرے برداشت سے زیادہ ہے۔ {میری...: یا، میری غلطی اس سے زیادہ ہے کہ اسے معاف کیا جا سکے}\n14۔ دیکھو، آج تو نے مجھے زمین سے نکال دیا ہے؛ اور میں تیرے چہرے سے چھپ جاؤں گا؛ اور میں زمین پر ایک فراری اور آوارہ بنوں گا؛ اور یہ ہو جائے گا، {کہ} جو بھی مجھے پائے گا وہ مجھے مار ڈالے گا۔\n15۔ اور خداوند نے اس سے کہا، لہٰذا جو بھی قابیل کو مارے گا، اس سے سات گنا بدلہ لیا جائے گا۔ اور خداوند نے قابیل پر نشان لگایا، کہیں کوئی اسے نہ ڈھونڈ لے اور اسے مار نہ دے۔\n16۔ اور قابیل خداوند کی موجودگی سے باہر نکلا اور عدن کے مشرق میں نود کی سرزمین میں بسنے لگا۔\n17۔ اور قابیل اپنی بیوی کو جانتا تھا؛ اور وہ حاملہ ہوئی، اور حنوخ کو جنم دیا: اور اس نے ایک شہر تعمیر کیا، اور شہر کا نام اپنے بیٹے حنوخ کے نام پر رکھا۔ {اینوک: عبرانی۔ چنوخ}\n18۔ اور حنوخ سے ایراد پیدا ہوا، اور ایراد نے مہوجائل کو جنم دیا؛ اور میہوجیل نے میتھوسائیل کو جنم دیا؛ اور میتھوسیل نے لمیک کو جنم دیا۔ {Lamech: عبرانی۔ لیمیک}\n19۔ اور لمیخ نے دو بیویاں حاصل کیں: ایک کا نام {تھا} آداہ، اور دوسری کا نام زیلہ کا۔\n20۔ اور عدہ نے جبل کو جنم دیا: وہ خیموں میں رہنے والوں اور مویشی رکھنے والوں کا باپ تھا۔\n21۔ اور اس کے بھائی کا نام {تھا} جوبل: وہ ہارپ اور آرگن سنبھالنے والوں کا والد تھا۔\n22۔ اور زیلا، اس نے طبلکین کو جنم دیا، جو ہر کاریگر کا استاد تھا اور طبلکین {تھا} نعمہ کی بہن۔ {انسٹرکٹر: عبوری۔ ویٹر}\n23۔ اور لمیخ نے اپنی بیویوں عدہ اور زیلہ سے کہا، میری آواز سنو؛ اے لامیک کی بیویاں، میری بات سنو: کیونکہ میں نے ایک آدمی کو اپنے زخموں میں مارا ہے، اور ایک نوجوان کو اپنی تکلیف میں۔ {میرے پاس ہے...: یا، میں اپنے زخم میں کسی کو مار ڈالوں گا، وغیرہ} {میرے دکھ کے لیے: یا، میرے درد میں}\n24۔ اگر قابیل کا بدلہ سات گنا ہوگا، تو واقعی لمیک ستر اور سات گنا۔\n25۔ اور آدم نے اپنی بیوی کو دوبارہ جانا؛ اور اس نے ایک بیٹا پیدا کیا، اور اس کا نام سیٹھ رکھا: کیونکہ خدا نے مجھے ہابیل کی جگہ ایک اور نسل دی ہے، جسے قابیل نے مارا۔ {سیٹھ: عبرانی۔ شیٹھ: یعنی مقرر کیا گیا، یا، پوٹ}\n26۔ اور سیٹھ کو بھی ایک بیٹا پیدا ہوا؛ اور اس نے اپنا نام اینوس پکارا: پھر لوگوں نے خداوند کا نام پکارنا شروع کیا۔ {اینوس: عبرانی۔ انوش} {پکارنا...: یا، خود کو خداوند کے نام سے پکارنا}","1. یہ {ہے} آدم کی نسلوں کی کتاب۔ جس دن خدا نے انسان کو پیدا کیا، خدا کی طرح اس نے خود بنایا؛\n2۔ مرد اور عورت نے انہیں بنایا؛ اور انہیں برکت دی، اور ان کا نام آدم رکھا، اس دن جب وہ پیدا ہوئے۔\n3۔ اور آدم ایک سو تیس سال زندہ رہا، اور اس کی صورت میں {بیٹا} پیدا ہوا؛ اور اس کا نام سیٹھ رکھا:\n4۔ اور آدم کے دن جب اس نے سیٹھ کو جنم دیا تھا، وہ آٹھ سو سال تھے: اور اس نے بیٹے اور بیٹیاں پیدا کیں:\n5۔ اور آدم کے تمام دن نو سو تیس سال تھے: اور وہ فوت ہو گیا۔\n6۔ اور سیٹھ ایک سو پانچ سال زندہ رہا، اور اس نے اینوس کو جنم دیا: {اینوس: عبرانی۔ انوش}\n7۔ اور سیٹھ نے اینوس کو آٹھ سو سات سال جنم دیا اور بیٹے اور بیٹیاں پیدا کیں:\n8۔ اور سیٹھ کے تمام دن نو سو بارہ سال تھے: اور وہ فوت ہو گیا۔\n9۔ اور اینوس نوے سال زندہ رہا، اور قائنان کو جنم دیا: {قینان: عبرانی۔ کینان}\n10۔ اور اینوس نے قینان کو جنم دینے کے بعد آٹھ سو پندرہ سال زندہ رہے، اور بیٹے اور بیٹیاں پیدا کیں:\n11۔ اور اینوس کے تمام دن نو سو پانچ سال تھے: اور وہ فوت ہو گیا۔\n12۔ اور کینان ستر سال زندہ رہا، اور مہلالیل کو جنم دیا: {مہلالیل: Gr. Maleleel}\n13۔ اور قائنان نے مہللیل کو جنم دینے کے بعد آٹھ سو چالیس سال زندہ رہے، اور بیٹے اور بیٹیاں پیدا کیں:\n14۔ اور قائینان کے تمام دن نو سو دس سال تھے: اور وہ فوت ہو گیا۔\n15. اور مہللیل ساٹھ اور پینچویں سال زندہ رہا، اور جیرڈ کو جنم دیا: {یریڈ: عبرانی۔ جیرڈ}\n16۔ اور مہللیل جیرید کے آٹھ سو تیس سال پیدا ہونے کے بعد زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں:\n17۔ اور مہللیل کے تمام دن آٹھ سو نوے پانچ سال تھے: اور وہ فوت ہو گیا۔\n18۔ اور جیرڈ ایک سو ساٹھ سال زندہ رہا، اور اس نے حنوخ کو جنم دیا:\n19۔ اور جیرڈ نے حنوخ کو آٹھ سو سال پیدا کرنے کے بعد زندہ رہنا اور بیٹے اور بیٹیاں پیدا کیں:\n20۔ اور جیرڈ کے تمام دن نو سو ساٹھ اور دو سال تھے: اور وہ فوت ہو گیا۔\n21۔ اور حنوخ پینسٹھ سال زندہ رہا، اور میتوشلہ کو جنم دیا: {میتوشالح: گری. متھوسالا}\n22۔ اور حنوخ نے متوشلہ کو جنم دینے کے بعد تین سو سال خدا کے ساتھ چلنا شروع کیا اور بیٹے اور بیٹیاں پیدا کیں:\n23۔ اور حنوخ کے تمام دن تین سو سٹھ پانچ سال تھے:\n24۔ اور اینوک خدا کے ساتھ چلتا رہا: اور وہ نہیں تھا؛ کیونکہ خدا نے اسے لے لیا۔\n25۔ اور میتوشلحہ ایک سو اسی سات سال زندہ رہا، اور لامیک کو جنم دیا:\n26۔ اور میتھیسیلہ نے لمیک کو سات سو بیاسی سال جنم دیا اور بیٹے اور بیٹیاں پیدا کیں: {لامیک: عبرانی۔ لیمیک}\n27۔ اور متوشلحہ کے تمام دن نو سو ساٹھ نو سال تھے: اور وہ فوت ہو گیا۔\n28۔ اور لامک ایک سو اسی سال زندہ رہا، اور اس کا ایک بیٹا ہوا:\n29۔ اور اس نے اپنا نام نوح پکارا، کہا، یہ {وہی} ہمیں ہمارے کام اور ہاتھوں کی محنت پر تسلی دے گا، اس زمین کی وجہ سے جسے خداوند نے لعنت دی ہے۔ {نوح: گری۔ نوئے: یہ ہے آرام، یا سکون}\n30۔ اور لمیخ نوح کو پانچ سو نوے پانچ سال پیدا کرنے کے بعد زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں:\n31. اور لامیک کے تمام دن سات سو ستر سات سال تھے: اور وہ فوت ہو گیا۔\n32۔ اور نوح پانچ سو سال کا تھا: اور نوح نے سام، حام اور یافث کو جنم دیا۔","1۔ اور یہ اس وقت ہوا جب انسان زمین پر بڑھنے لگے، اور ان سے بیٹیاں پیدا ہوئیں،\n2۔ کہ خدا کے بیٹے انسانوں کی بیٹیوں کو خوبصورت دیکھتے ہیں؛ اور انہوں نے اپنی مرضی کی ہر چیز کی بیویاں لے لیں۔\n3۔ اور خداوند نے فرمایا، میری روح ہمیشہ انسان کے ساتھ نہیں لڑے گی، کیونکہ وہ بھی جسم میں ہے، لیکن اس کے دن ایک سو بیس سال ہوں گے۔\n4۔ ان دنوں زمین پر دیو موجود تھے؛ اور اس کے بعد، جب خدا کے بیٹے انسانوں کی بیٹیوں کے پاس آئے اور ان کے ہاں {بچے} پیدا ہوئے، تو وہی {طاقتور} مرد بن گئے جو {پرانا} تھے، مشہور لوگ۔\n5۔ اور خدا نے دیکھا کہ انسان کی برائی زمین پر بہت بڑی ہے، اور اس کے دل کے خیالات کا ہر تصور مسلسل صرف برائی ہے۔ {ہر...: یا، پوری تخیل: عبرانی لفظ صرف تخیل ہی نہیں بلکہ مقاصد اور خواہشات کی بھی نمائندگی کرتا ہے} {مسلسل: عبرانی۔ ہر روز}\n6۔ اور اس نے خداوند سے توبہ کی کہ اس نے زمین پر انسان بنایا، اور اس کے دل سے اس کا دکھ ہوا۔\n7۔ اور خداوند نے فرمایا، میں اس انسان کو تباہ کر دوں گا جسے میں نے زمین کے چہرے سے پیدا کیا ہے؛ انسان، جانور، رینگتی ہوئی چیز، اور ہوا کے پرندے؛ کیونکہ یہ مجھے توبہ کرتا ہے کہ میں نے انہیں بنایا۔ {دونوں...: عبرانی۔ انسان سے درندے تک}\n8۔ لیکن نوح نے خداوند کی آنکھوں میں فضل پایا۔\n9۔ یہ نوح کی نسلیں ہیں: نوح ایک عادل انسان تھا اور اپنی نسلوں میں کامل تھا، اور نوح خدا کے ساتھ چلتا رہا۔ {کامل: یا، سیدھا}\n10۔ اور نوح نے تین بیٹے پیدا کیے: سام، حام، اور یافتھ۔\n11. زمین بھی خدا کے سامنے بدعنوان تھی، اور زمین تشدد سے بھری ہوئی تھی۔\n12۔ اور خدا نے زمین کو دیکھا، اور دیکھو، وہ بگڑ گئی؛ کیونکہ ہر جسم نے زمین پر اپنا راستہ بگاڑ دیا تھا۔\n13۔ اور خدا نے نوح سے کہا، تمام جسموں کا انجام میرے سامنے آ گیا ہے؛ کیونکہ زمین ان کے ذریعے تشدد سے بھری ہوئی ہے؛ اور دیکھو، میں انہیں زمین سے تباہ کر دوں گا۔ {زمین کے ساتھ: یا، زمین سے}\n14. گوفر لکڑی کا تابوت بناؤ؛ تم صندوق میں کمرے بناؤ گے، اور اسے اندر اور باہر پچ کے ساتھ پھینکو گے۔ {کمرے: عبرانی۔ گھونسلے}\n15۔ اور یہ {وہ طریقہ} ہے جس سے تم اسے {سے} بناؤ گے: صندوق کی لمبائی {تین سو کیوبٹ} ہوگی، اس کی چوڑائی پچاس کیوبٹ، اور اس کی اونچائی تیس کیوبٹ ہوگی۔\n16۔ تم صندوق کی کھڑکی بناؤ گے، اور ایک کیوبٹ میں اسے اوپر مکمل کرو گے؛ اور صندوق کا دروازہ اس کے کنارے میں رکھنا ہے؛ {نیچے، دوسرے اور تیسرے {کہانیوں کے ساتھ} تم کامیاب ہو جاؤ گے۔\n17۔ اور دیکھو، میں، خود میں بھی، زمین پر پانیوں کا سیلاب لاتا ہوں، تاکہ آسمان کے نیچے سے زندگی کی سانس کے تمام جسم کو تباہ کر دے؛ {اور} زمین کی ہر چیز مر جائے گی۔\n18۔ لیکن میں تمہارے ساتھ اپنا عہد قائم کروں گا؛ اور تم کشتی میں آؤ گے، تم، تمہارے بیٹے، تمہاری بیوی، اور تمہارے بیٹوں کی بیویاں تمہارے ساتھ ہوں گی۔\n19۔ اور ہر جاندار میں سے، ہر قسم کے دو کو تابوت میں لے آؤ، تاکہ وہ اپنے ساتھ زندہ رہیں؛ وہ مرد اور عورت ہوں گے۔\n20۔ اپنی نسل کے پرندوں سے، اور اپنی نسل کے مویشیوں سے، زمین کے ہر رینگنے والے جانور سے، ہر قسم کے دو دو آپ کے پاس آئیں گے، تاکہ انہیں زندہ رکھیں۔\n21۔ اور جو بھی کھایا جاتا ہے اس میں سے اپنے پاس لے لو، اور اسے اپنے لیے جمع کرو؛ اور یہ تمہارے لیے اور ان کے لیے خوراک کے لیے ہوگا۔\n22۔ نوح نے بھی ایسا ہی کیا؛ خدا نے جو کچھ حکم دیا، اس کے مطابق اس نے بھی ایسا ہی کیا۔","1۔ اور خداوند نے نوح سے کہا، تو اور اپنے سارے گھر کشتی میں آؤ؛ کیونکہ میں نے اس نسل میں اپنے سامنے نیک دیکھا ہے۔\n2۔ ہر پاک جانور جو تم اپنے پاس ساتوں میں لے جاؤ گے، مرد اور اس کی مادہ؛ اور وہ جانور جو دو سے پاک نہیں ہیں، نر اور اس کی مادہ۔ {سات کے ذریعے: عبرانی۔ سیون سیون}\n3۔ ہوا میں بھی سات پرندوں کی تعداد میں، نر اور مادہ؛ تاکہ زمین کے چہرے پر بیج زندہ رہے۔ {سات کے ذریعے: عبرانی۔ سیون سیون}\n4۔ ابھی سات دن تک، اور میں زمین پر چالیس دن اور چالیس راتیں برساؤں گا؛ اور جو بھی جاندار چیز میں نے بنائی ہے، اسے میں زمین کے چہرے سے مٹا دوں گا۔ {تباہ کریں: عبرانی۔ مٹ آؤٹ}\n5۔ اور نوح نے خداوند کے حکم کے مطابق سب کچھ کیا۔\n6۔ اور نوح چھ سو سال کا تھا جب پانی کا سیلاب زمین پر آیا۔\n7۔ اور نوح اپنے بیٹوں، بیوی، اور اپنے بیٹوں کی بیویوں کے ساتھ، سیلاب کے پانی کی وجہ سے کشتی میں داخل ہوا۔\n8۔ پاک جانوروں کی، اور ان جانوروں کی جو پاک نہیں ہیں، اور پرندوں کی، اور زمین پر رینگنے والی ہر چیز کی،\n9۔ دو اور دو میں نوح کے پاس کشتی میں گئے، مرد اور عورت، جیسا کہ خدا نے نوح کو حکم دیا تھا۔\n10۔ اور سات دن بعد ہوا کہ سیلاب کا پانی زمین پر تھا۔ {بعد...: یا، ساتویں دن}\n11۔ نوح کی زندگی کے چھ سوویں سال میں، دوسرے مہینے، مہینے کے سترہویں دن، اسی دن عظیم گہرے چشمے توڑ دیے گئے، اور آسمان کی کھڑکیاں کھل گئیں۔ {کھڑکیاں: یا، سیلاب کے دروازے}\n12۔ اور بارش زمین پر چالیس دن اور چالیس راتیں برستی رہی۔\n13۔ اسی دن نوح، سام، حام، یافث، نوح کے بیٹے، اور نوح کی بیوی، اور اس کے بیٹوں کی تین بیویاں ان کے ساتھ کشتی میں داخل ہوئیں؛\n14۔ وہ، اور ہر جانور اپنی نسل کے بعد، اور تمام مویشی اپنی نسل کے بعد، اور ہر رینگنے والا جانور جو زمین پر اس کی نسل کے پیچھے رینگتا ہے، اور ہر پرندہ اس کی نسل کے پیچھے ہے، ہر قسم کا پرندہ۔ {ترتیب دینا: عبوری۔ ونگ}\n15۔ اور وہ نوح کے پاس کشتی میں گئے، دو اور دو تمام گوشت سے، جہاں زندگی کی سانس ہے۔\n16۔ اور جو اندر گئے، وہ ہر جسم کے مرد اور عورت کے اندر آئے، جیسا کہ خدا نے اسے حکم دیا تھا: اور خداوند نے اسے بند کر دیا۔\n17۔ اور سیلاب زمین پر چالیس دن آیا؛ اور پانی بڑھ گیا، اور کشتی کو بے نقاب کر دیا، اور وہ زمین سے بلند ہو گئی۔\n18۔ اور پانی غالب آئے، اور زمین پر بہت بڑھ گئے؛ اور کشتی پانیوں کے چہرے پر آ گئی۔\n19۔ اور پانی زمین پر بے حد غالب آ گیا؛ اور تمام اونچی پہاڑیاں، جو پورے آسمان کے نیچے تھیں، ڈھانپ دی گئیں۔\n20۔ پندرہ کیوبٹ اوپر پانی غالب آ گیا؛ اور پہاڑ ڈھک گئے۔\n21۔ اور زمین پر چلنے والے تمام جسم مرے گئے، پرندوں، مویشیوں، جانوروں سے، اور زمین پر رینگنے والے ہر جانور سے، اور ہر انسان سے:\n22. جن کی ناک میں زندگی کی سانس تھی، جو کچھ بھی خشک {زمین} میں تھا، مر گیا۔ {سانس...: عبرانی۔ زندگی کی روح کی سانس}\n23۔ اور زمین کی سطح پر موجود ہر جاندار تباہ ہو گیا، انسان، مویشی، رینگنے والے جانور اور آسمان کے پرندے؛ اور وہ زمین سے تباہ ہو گئے: اور نوح صرف {زندہ} رہا، اور وہ لوگ جو اس کے ساتھ کشتی میں تھے۔\n24۔ اور پانی زمین پر ایک سو پچاس دن تک چھا گیا۔","1۔ اور خدا نے نوح کو یاد کیا، اور ہر جاندار کو بھی، اور تمام مویشی جو اس کے ساتھ کشتی میں تھے: اور خدا نے زمین پر ہوا کو بہایا، اور پانی کو گونجاندا؛\n2۔ گہرائی کے چشمے اور آسمان کی کھڑکیاں بھی بند کر دی گئیں، اور آسمان سے آنے والی بارش کو روکا گیا؛\n3۔ اور پانی زمین سے مسلسل واپس آتا رہا: اور سو پچاس دن کے بعد پانی کم ہو گیا۔ {مسلسل: عبرانی۔ جانے اور واپس آنے میں}\n4۔ اور تابوت ساتویں مہینے میں، مہینے کے سترہویں دن، ارارات کے پہاڑوں پر آرام کر گئی۔\n5۔ اور پانی مسلسل کم ہوتا گیا یہاں تک کہ دسویں مہینے تک: دسویں مہینے میں، مہینے کے پہلے دن، پہاڑوں کی چوٹیاں نظر آئیں۔ {کم کیا گیا...: ہیب۔ میں جا رہے تھے اور کم ہو رہے تھے}\n6۔ اور چالیس دن کے بعد نوح نے اس کشتی کی کھڑکی کھولی جو اس نے بنائی تھی:\n7۔ اور اس نے ایک کوا بھیجا، جو ادھر ادھر جاتا رہا، یہاں تک کہ پانی زمین سے خشک ہو گیا۔ {تو...: عبرانی آگے بڑھنے اور واپس آنے میں}\n8۔ اس نے اپنی طرف سے ایک کبوتر بھیجا، تاکہ دیکھے کہ کیا پانی زمین کی سطح سے کم ہو گیا ہے؛\n9۔ لیکن کبوتر نے اپنے پاؤں کے تلوے کو آرام نہ دیا، اور وہ اس کے پاس کشتی میں واپس چلی گئی، کیونکہ پانی پوری زمین پر تھا، پھر اس نے اپنا ہاتھ بڑھایا، اسے پکڑ کر کشتی میں کھینچ لیا۔ {کھینچا...: عبوری۔ اسے فارغ کرنے پر مجبور کیا}\n10۔ اور وہ سات دن مزید رکا؛ اور پھر اس نے کبوتر کو کشتی سے باہر بھیجا؛\n11۔ اور کبوتر شام کو اس کے پاس آیا؛ اور، دیکھو، اس کے منہ میں زیتون کا پتہ نکلا ہوا تھا: تو نوح جان گیا کہ زمین سے پانی ختم ہو چکا ہے۔\n12۔ اور وہ مزید سات دن رکا؛ اور کبوتر بھیجا؛ جو اب اس کے پاس واپس نہیں آیا۔\n13۔ اور یہ واقعہ چھ سوویں اور پہلے سال میں ہوا، پہلے مہینے میں، مہینے کے پہلے دن، زمین سے پانی خشک ہو گیا: اور نوح نے کشتی کا ڈھکن ہٹا کر دیکھا، اور دیکھا، زمین کا چہرہ خشک ہو گیا۔\n14۔ اور دوسرے مہینے میں، مہینے کے ساتویں اور بیس دن، زمین خشک ہوئی۔\n15۔ اور خدا نے نوح سے کہا،\n16۔ تم اور تمہاری بیوی، اور تمہارے بیٹے، اور تمہارے بیٹوں کی بیویاں اپنے ساتھ کشتی سے باہر آؤ۔\n17۔ اپنے ساتھ ہر جاندار چیز کو لے آؤ جو اپنے ساتھ ہے، تمام جسم سے، مرغی، مویشیوں کی، اور زمین پر رینگنے والی ہر چیز کی؛ تاکہ وہ زمین میں فراوانی سے افزائش کریں، پھلدار ہوں اور زمین پر افزائش کریں۔\n18۔ اور نوح نکلا، اس کے بیٹے، اس کی بیوی اور اس کے بیٹوں کی بیویاں اس کے ساتھ آئیں:\n19۔ ہر جانور، ہر رینگنے والی چیز، اور ہر پرندہ، {اور} جو بھی زمین پر رینگتا ہے، اپنی نسل کے بعد، کشتی سے باہر نکلا۔ {اقسام: عبدی۔ خاندان}\n20۔ اور نوح نے خداوند کے لیے ایک قربان گاہ بنائی؛ اور ہر صاف جانور اور ہر صاف مرغی کو چھین لیا اور قربان گاہ پر جلانے کی قربانیاں پیش کیں۔\n21۔ اور خداوند نے ایک میٹھا ذائقہ سونگھا؛ اور خداوند نے اپنے دل میں فرمایا، میں اب انسان کی خاطر زمین کو مزید لعنت نہیں دوں گا؛ کیونکہ انسان کے دل کی تخیل اس کی جوانی سے ہی برائی ہے؛ اور نہ ہی میں اب ہر جاندار چیز کو تباہ کروں گا، جیسا کہ میں نے کیا ہے۔ {ایک میٹھا...: عبرانی۔ آرام یا، تسکین کا ذائقہ} {تخیل کے لیے: یا، تخیل کے ذریعے}\n22۔ جب تک زمین باقی ہے، بیج بونے کا وقت، فصل، سردی اور گرمی، گرمی، سردی، دن اور رات ختم نہیں ہوں گے۔ {جبکہ...: عبرانی ابھی تک زمین کے تمام دن گزر چکے ہیں}","1۔ اور خدا نے نوح اور اس کے بیٹوں کو برکت دی اور ان سے کہا، \"پھل بڑھو، بڑھو، اور زمین کو تازہ کرو۔\n2۔ اور تم سے خوف اور تمہارا خوف زمین کے ہر جانور پر، ہوا کے ہر پرندے پر، زمین پر حرکت کرنے والے ہر شخص پر، اور سمندر کی تمام مچھلیوں پر ہوگا؛ وہ آپ کے ہاتھ میں پہنچائے جاتے ہیں۔\n3۔ ہر زندہ چیز تمہارے لیے گوشت بنے گی؛ جیسے سبز جڑی بوٹی، میں نے تمہیں سب کچھ دیا ہے۔\n4۔ لیکن گوشت اور اس کی جان، جو اس کا خون ہے، تم نہیں کھاؤ گے۔\n5۔ اور یقینا تمہاری جانوں کا خون مجھے درکار ہوگا؛ ہر جانور کے ہاتھوں میں اس کی ضرورت ہوگی، اور انسان کے ہاتھ پر؛ ہر انسان کے بھائی کے ہاتھوں مجھے انسان کی جان چاہیے ہوگی۔\n6۔ جو انسان کا خون بہائے، اس کا خون انسان کے ذریعے بہایا جائے گا: کیونکہ خدا کی صورت میں اس نے انسان بنایا۔\n7۔ اور تم، پھل دار بنو اور بڑھو؛ زمین میں فراوانی سے اگاؤ اور وہاں بڑھاؤ۔\n8۔ اور خدا نے نوح سے اور اس کے بیٹوں سے کہا،\n9۔ اور میں، دیکھو، میں تم سے اور تمہارے بعد کی نسل کے ساتھ اپنا عہد قائم کرتا ہوں؛\n10۔ اور ہر اس جاندار کے ساتھ جو تمہارے ساتھ ہے، پرندوں، مویشیوں کی، اور زمین کے ہر جانور کے ساتھ جو تمہارے ساتھ ہے؛ تابوت سے نکلنے والے سب سے لے کر زمین کے ہر جانور تک۔\n11۔ اور میں تم سے اپنا عہد قائم کروں گا؛ نہ ہی اب ہر جسم سیلاب کے پانی سے کاٹ دیا جائے گا؛ اور نہ ہی اب کوئی سیلاب آئے گا جو زمین کو تباہ کر دے۔\n12۔ اور خدا نے فرمایا، یہ اس عہد کی نشانی ہے جو میں اپنے اور تمہارے درمیان اور ہر جاندار کے درمیان جو تمہارے ساتھ ہے، ہمیشہ کی نسلوں کے لیے کیا گیا ہے:\n13۔ میں اپنا کمان بادل میں رکھتا ہوں، اور یہ میرے اور زمین کے درمیان عہد کی نشانی ہوگی۔\n14. اور جب میں زمین پر بادل لاؤں گا، تو کمان بادلوں میں نظر آئے گا:\n15۔ اور میں اپنا عہد یاد رکھوں گا، جو میرے اور تمہارے اور ہر جاندار کے درمیان ہے؛ اور پانی اب سیلاب نہیں بنے گا جو تمام گوشت کو تباہ کر دے۔\n16۔ اور کمان بادل میں ہوگا؛ اور میں اسے دیکھوں گا، تاکہ خدا اور زمین پر موجود ہر جاندار کے درمیان ابدی عہد کو یاد رکھ سکوں۔\n17۔ اور خدا نے نوح سے کہا، یہ عہد کی نشانی ہے، جو میں نے اپنے اور زمین پر موجود تمام انسانوں کے درمیان قائم کیا ہے۔\n18۔ اور نوح کے بیٹے جو کشتی سے نکلے، وہ شم، حام اور یافث تھے: اور حام کنعان کا باپ ہے۔ {کنعان: عبرانی۔ چنان}\n19۔ یہ نوح کے تین بیٹے ہیں: اور ان میں سے پوری زمین پھیلی ہوئی تھی۔\n20۔ اور نوح نے {زمیندار} بننے کا آغاز کیا، اور اس نے انگور کا باغ لگایا:\n21۔ اور اس نے شراب پی اور نشے میں تھا؛ اور وہ اپنے خیمے میں بے نقاب ہو گیا۔\n22۔ اور حام، کنعان کے والد، نے اپنے والد کی برہنگی دیکھی اور اپنے دو بھائیوں کو باہر بتایا۔\n23۔ اور سام اور یافتھ نے ایک لباس اٹھا کر دونوں کے کندھوں پر ڈال دیا، پیچھے ہٹ کر اپنے باپ کی ننگی کو ڈھانپ دیا؛ اور ان کے چہرے پیچھے تھے، اور انہوں نے اپنے باپ کی برہنگی نہیں دیکھی۔\n24۔ اور نوح اپنی شراب سے جاگا، اور جان گیا کہ اس کے چھوٹے بیٹے نے اس کے ساتھ کیا کیا ہے۔\n25۔ اور اس نے کہا، لعنت زدہ {ہو} کنعان؛ وہ اپنے بھائیوں کا خادم ہوگا۔\n26۔ اور اس نے کہا، مبارک ہو خداوند سام کے خدا؛ اور کنعان اس کا خادم ہوگا۔ {اس کا خادم: یا، ان کا خادم}\n27۔ خدا یافتھ کو وسیع کرے گا، اور وہ سام کے خیموں میں رہے گا؛ اور کنعان اس کا خادم ہوگا۔ {بڑا کریں: یا، قائل کریں}\n28۔ اور نوح طوفان کے بعد تین سو پچاس سال زندہ رہا۔\n29۔ اور نوح کے تمام دن نو سو پچاس سال کے تھے: اور وہ فوت ہو گیا۔","1۔ اب یہ نوح، سام، حام اور یافتھ کے بیٹوں کی نسلیں ہیں: اور ان کے بیٹے طوفان کے بعد پیدا ہوئے۔\n2۔ یافتھ کے بیٹے؛ گومر، اور ماگوگ، اور مادائی، اور جاوان، اور ٹوبال، اور میشچ، اور تیراس۔\n3۔ اور گومر کے بیٹے؛ اشکناز، اور ریفاتھ، اور توگرمہ۔\n4۔ اور جاوان کے بیٹے؛ الیشاہ، اور ترشش، کٹم، اور ڈوڈنیم۔ {ڈوڈانیم: یا جیسا کہ کچھ لوگ پڑھتے ہیں، رودانیم}\n5۔ ان کے ذریعے غیر یہودی جزائر اپنی زمینوں میں تقسیم تھے؛ ہر کوئی اس کی زبان کے پیچھے، ان کے خاندانوں کے پیچھے، اپنی قوموں میں۔\n6۔ اور حام کے بیٹے؛ کش، اور مزرائیم، اور پھوت، اور کنعان۔\n7۔ اور کش کے بیٹے؛ سبا، حویلہ، سبتاح، رمعہ، سبتیخا: اور راماہ کے بیٹے؛ شیبا، اور ڈیڈن۔\n8۔ اور کش نے نمرود کو جنم دیا: وہ زمین پر طاقتور بن گیا۔\n9۔ وہ خداوند کے سامنے ایک طاقتور شکاری تھا: اسی لیے کہا جاتا ہے، جیسے نمرود عظیم شکاری خداوند کے سامنے تھا۔\n10۔ اور اس کی بادشاہت کی ابتدا بابل، اریخ، اکاد، اور کالنے تھی، جو شینار کی سرزمین میں تھیں۔ {بابل: گری. بابلون}\n11۔ اسی زمین سے آشور نکلا، اور نینوا بنایا، اور شہر رحوبوت اور کالہ کو تعمیر کیا، {گیا...: یا، وہ آشور میں چلا گیا} {شہر...: یا، شہر کی گلیاں}\n12. اور نینوا اور کالہ کے درمیان ریزن: یہی {ہے} ایک عظیم شہر۔\n13۔ اور مزرائیم نے لودیم، انامیم، لہابیم اور نفتوہیم کو جنم دیا،\n14۔ اور پتھرسیم، اور کاسلوہیم (جن سے فلسطینی نکلے)، اور کفتوریم۔\n15۔ اور کنعان نے صیدون کو اپنا پہلا بیٹا اور ہیث کو جنم دیا، {صیدون: عبرانی۔ تزیدون}\n16۔ اور یبوسی، اور اموری، اور گرگسائٹ،\n17۔ اور حوی، اور آرکیت، اور سینائیٹ،\n18۔ اور اروادی، زماری، اور ہمتی: اور بعد میں کنعانیوں کے خاندان پھیل گئے۔\n19۔ اور کنعانیوں کی سرحد صیدا سے تھی، جب تم جرار آتے ہو، غزہ تک؛ جیسے تم جاتے ہو، سدوم، عمورا، آدمہ، زبوئیم، حتیٰ کہ لاشا کے لیے۔ {غزہ: عبرانی۔ عزا}\n20. یہ {ہیں} حام کے بیٹے، اپنے خاندانوں کے مطابق، ان کی زبانوں کے ساتھ، اپنے ملکوں میں، {اور} اپنی قوموں میں۔\n21۔ سام کے لیے، ایبر کے تمام بچوں کا باپ، یافتھ بزرگ کا بھائی، یہاں تک کہ اس کے لیے بھی {بچے} پیدا ہوئے۔\n22۔ سام کے بچے؛ ایلام، آشور، ارفکسد، لود، اور آرام۔ {ارفکساد: عبرانی۔ ارپاچشاد}\n23۔ اور آرام کے بچے؛ از، ہل، گیتھر، اور ماش۔\n24۔ اور ارفقساد نے صلاح کو جنم دیا؛ اور صلاح نے ایبر کو جنم دیا۔ {صلاح: عبرانی۔ شیلہ}\n25۔ اور ایبر کو دو بیٹے پیدا ہوئے: ایک کا نام {تھا} پیلیگ؛ کیونکہ اس کے زمانے میں زمین تقسیم تھی؛ اور اس کے بھائی کا نام {تھا} جوکتان۔ {پیلیگ: یہ ڈویژن ہے}\n26. اور یوقطن نے الموداد، شلیف، اور ہزارماوتھ، اور یراح کو جنم دیا،\n27۔ اور ہادورام، اوزال، اور دیکلاہ،\n28۔ اور اوبل، اور ابیمائیل، اور سبا،\n29۔ اور اوفیر، اور حویلہ، اور جوباب: یہ سب {تھے} جوکتان کے بیٹے۔\n30۔ اور ان کا گھر میشا سے تھا، جب تم سیفار جاتے ہو، جو مشرق کا پہاڑ ہے۔\n31. یہ سام کے بیٹے ہیں، اپنے خاندانوں کے مطابق، ان کی زبانوں کے مطابق، اپنی زمینوں میں، اپنی قوموں کے مطابق۔\n32۔ یہ نوح کے بیٹوں کے خاندان ہیں، اپنی نسلوں کے بعد، اپنی قوموں میں: اور انہی سے وہ قومیں تھیں جو طوفان کے بعد زمین میں تقسیم ہوئیں۔","1۔ اور پوری زمین ایک زبان اور ایک زبان کی تھی۔ {زبان: عبوری۔ لپ۔} {گفتگو: عبرانی۔ الفاظ}\n2۔ اور جب وہ مشرق سے سفر کر رہے تھے، تو انہوں نے شینار کی زمین میں ایک میدان پایا؛ اور وہ وہیں رہتے تھے۔ {سے...: یا، مشرق کی طرف}\n3۔ اور انہوں نے ایک دوسرے سے کہا، جاؤ، آؤ اینٹیں بنائیں اور انہیں اچھی طرح جلا دیں۔ اور ان کے پاس پتھر کے لیے اینٹ تھے، اور سلائم کے پاس مورٹر کے لیے۔ {انہوں نے کہا...: عبرانی۔ ایک آدمی نے اپنے پڑوسی سے کہا} {برن...: عبرانی انہیں جلا کر جلا دو}\n4۔ اور انہوں نے کہا، جاؤ، آؤ ہم اپنے لیے ایک شہر اور مینار بناؤ، جس کی چوٹی {آسمان} تک پہنچ سکے؛ اور ہم اپنا نام بنا لیں، ورنہ ہم پوری زمین پر بکھر جائیں گے۔\n5۔ اور خداوند نیچے آیا تاکہ وہ شہر اور مینار دیکھ سکے، جو انسانوں کے بچوں نے تعمیر کیا تھا۔\n6۔ اور خداوند نے فرمایا، دیکھو، لوگ ایک ہیں، اور ان سب کی ایک زبان ہے؛ اور وہ یہ کرنا شروع کرتے ہیں: اور اب ان سے کچھ بھی روکا نہیں جائے گا، جو انہوں نے تصور کیا تھا۔\n7. جاؤ، نیچے چلیں، اور وہاں ان کی زبان کو الجھا دو، تاکہ وہ ایک دوسرے کی بات نہ سمجھیں۔\n8۔ تو خداوند نے انہیں وہاں سے زمین کے چہرے پر بکھیر دیا، اور وہ شہر کی تعمیر کے لیے روانہ ہو گئے۔\n9۔ اسی لیے اس کا نام بابل ہے؛ کیونکہ خداوند نے وہاں زمین کی تمام زبان کو الجھا دیا: اور وہاں سے خداوند نے انہیں زمین کے چہرے پر پھیلا دیا۔ {بابل: یعنی، الجھن}\n10۔ یہ سام کی نسلیں ہیں: شیم سو سال کا تھا، اور سیلاب کے دو سال بعد ارفکسد کو جنم دیا:\n11۔ اور سام نے ارفقساد کو پانچ سو سال پیدا کرنے کے بعد زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں۔\n12۔ اور ارفاقد پانچ تیس سال زندہ رہے، اور صلاح کو جنم دیا:\n13۔ اور ارفخسعد نے صلاح کی پیدائش کے بعد چار سو تین سال زندہ رہے، اور بیٹے اور بیٹیاں پیدا کیں۔\n14۔ اور صلاح تیس سال زندہ رہا، اور ایبر کو جنم دیا:\n15۔ اور صلاح ایبر کے پیدا ہونے کے بعد چار سو تین سال زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں۔\n16۔ اور ایبر چار تیس سال زندہ رہا، اور پیلیگ کو جنم دیا: {پیلیگ: گری۔ فالک}\n17۔ اور ایبر نے پیلیگ کو چار سو تیس سال جنم دیا اور بیٹے اور بیٹیاں پیدا کیں۔\n18۔ اور پیلیگ تیس سال زندہ رہا، اور اس نے رئو کو جنم دیا:\nانیس۔ اور پیلیگ دو سو نو سال کے بعد زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں۔\n20۔ اور رئو دو تیس سال زندہ رہا، اور اس نے سیرگ کو جنم دیا: {سرگ: گری۔ ساروخ}\n21. اور رئو دو سو سات سال کے بعد سیرگ کو جنم دینے کے بعد زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں۔\n22۔ اور سیرگ تیس سال زندہ رہا، اور ناحور کو جنم دیا:\n23۔ اور سروگ ناحور کو دو سو سال پیدا کرنے کے بعد زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں۔\nچوبیس۔ اور ناہور نو بیس سال زندہ رہا، اور تیراہ کو جنم دیا: {تیرا: گری۔ تھارا}\n25۔ اور ناہور نے ایک سو انیس سال تک تیرہ پیدا کرنے کے بعد زندہ رہا، اور بیٹے اور بیٹیاں پیدا کیں۔\n26۔ اور تیراہ ستر سال زندہ رہی، اور اس نے ابرام، ناحور اور ہاران کو جنم دیا۔\n27۔ اب یہ {ہیں} تیراہ کی نسلیں: تیراہ نے ابرام، ناحور اور ہاران کو جنم دیا؛ اور ہاران نے لوط کو جنم دیا۔\n28۔ اور ہاران اپنے والد تیراہ کے سامنے اپنی پیدائش کی سرزمین پر، کلدیوں کے یور میں وفات پا گیا۔\n29۔ اور ابرام اور ناہور نے ان کی بیویاں لیں: ابرام کی بیوی کا نام سرائی تھا؛ اور ناحور کی بیوی ملکہ کا نام تھا، جو ہاران کی بیٹی، ملکہ کے والد اور اسحاق کے والد تھی۔\n30۔ لیکن سرائی بانجھ تھی؛ اس کا کوئی بچہ نہیں تھا۔\n31۔ اور تیراہ نے اپنے بیٹے ابرام کو لیا، اور ہاران کے بیٹے لوط کو اپنے بیٹے کے بیٹے کے بیٹے، اور سرائی اپنی بہو کو اپنے بیٹے ابرام کی بیوی لی؛ اور وہ ان کے ساتھ کلدیوں کے یور سے نکل کر کنعان کی سرزمین میں گئے؛ اور وہ ہاران آئے، اور وہاں بسے۔\n32۔ اور تیراہ کے دن دو سو پانچ سال تھے: اور تیراہ ہاران میں وفات پا گئی۔","1۔ اب خداوند نے ابرام سے کہا، اپنے ملک سے، اپنے رشتہ داروں سے، اور اپنے باپ کے گھر سے نکل جاؤ اس زمین کی طرف جو میں تمہیں دکھاؤں گا:\n2۔ اور میں تمہیں ایک عظیم قوم بناؤں گا، اور تمہیں برکت دوں گا، اور تمہارا نام عظیم بناؤں گا؛ اور تم ایک نعمت بنو گے:\n3۔ اور میں ان کو برکت دوں گا جو تمہیں برکت دیتے ہیں، اور جو تمہیں لعنت دیتا ہے اسے لعنت دوں گا: اور تم میں زمین کے تمام خاندان برکت یافتہ ہوں گے۔\n4۔ تو ابرام روانہ ہوا، جیسا کہ خداوند نے اس سے کہا تھا؛ اور لوط اس کے ساتھ گیا: اور ابرام جب ہاران سے روانہ ہوا تو اس کی عمر پچھتر سال تھی۔\n5۔ اور ابرام نے اپنی بیوی سرائی اور اپنے بھائی کے بیٹے لوط کو، اور ان کی ساری مالیت اور وہ روحیں جو انہوں نے ہاران میں حاصل کی تھیں، لے لی؛ اور وہ کنعان کی سرزمین کی طرف روانہ ہوئے؛ اور وہ کنعان کی سرزمین میں آئے۔\n6۔ اور ابرام زمین سے سیخیم کی جگہ، مورہ کے میدان تک پہنچا۔ اور کنعانی {تھا} اس وقت زمین میں۔ {سادہ: عبرانی۔ میدان}\n7۔ اور خداوند ابریم پر ظاہر ہوا اور کہا، میں یہ زمین تیری نسل کو دوں گا: اور وہاں اس نے خداوند کے لیے ایک قربان گاہ بنائی، جو اس کے سامنے ظاہر ہوا۔\n8۔ اور وہ وہاں سے بیت ھل کے مشرق میں ایک پہاڑ پر چلا گیا، اور اپنا خیمہ کھڑا کیا، مغرب میں بیت ایل اور مشرق میں ہائی، اور وہاں اس نے خداوند کے لیے ایک قربان گاہ بنائی، اور خداوند کا نام پکارا۔\n9۔ اور ابرام روانہ ہوا، اب بھی جنوب کی طرف بڑھتا ہوا۔ {جا رہا ہے...: عبرانی۔ ان گوئنگ اینڈ ٹریونگ}\n10۔ اور زمین میں قحط آ گیا، اور ابرام مصر میں اتر گیا تاکہ وہاں قیام کرے؛ کیونکہ قحط زمین میں شدید تھا۔\n11۔ اور جب وہ مصر میں داخل ہونے کے قریب پہنچا، تو اس نے اپنی بیوی سرائی سے کہا، دیکھو، میں جانتا ہوں کہ تم دیکھنے کے لیے ایک خوبصورت عورت ہو:\n12۔ لہٰذا جب مصری تمہیں دیکھیں گے تو وہ کہیں گے، یہ اس کی بیوی ہے: اور وہ مجھے مار ڈالیں گے، لیکن تمہیں زندہ بچائیں گے۔\n13۔ کہو، میں تم سے دعا کرتی ہوں، تم میری بہن ہو: تاکہ تمہارے لیے میرے لیے اچھا ہو؛ اور میری روح تمہاری وجہ سے زندہ رہے گی۔\n14۔ اور ایسا ہوا کہ جب ابرام مصر میں آیا، مصریوں نے اس عورت کو بہت خوبصورت دیکھا۔\n15۔ فرعون کے شہزادوں نے بھی اسے دیکھا اور فرعون کے سامنے اس کی تعریف کی: اور عورت کو فرعون کے گھر لے جایا گیا۔\n16۔ اور اس نے ابرام سے اس کے لیے بھلائی کی درخواست کی: اور اس کے پاس بھیڑیں، بیل، گدھے، نوکر، خادم، خادم، گدھے اور اونٹ تھے۔\n17۔ اور خداوند نے فرعون اور اس کے گھرانے کو سراعی ابرام کی بیوی کی وجہ سے بڑی آفتوں سے مصیبت دی۔\n18۔ اور فرعون نے ابرام کو بلایا اور کہا، یہ کیا ہے جو تم نے میرے ساتھ کیا ہے؟ تم نے مجھے کیوں نہیں بتایا کہ وہ تمہاری بیوی ہے؟\n19۔ تم نے کیوں کہا، وہ میری بہن ہے؟ تو میں اسے اپنی بیوی بنا لیتا: اب دیکھو اپنی بیوی، اسے لے لو، اور اپنی راہ پر چلو۔\n20۔ اور فرعون نے اپنے آدمیوں کو اس کے بارے میں حکم دیا، اور انہوں نے اسے، اس کی بیوی کو، اور جو کچھ بھی اس کے پاس تھا، بھیج دیا۔","1۔ اور ابرام مصر سے نکل آیا، وہ اور اس کی بیوی اور اس کے پاس جو کچھ بھی تھا، اور لوط اس کے ساتھ، جنوب کی طرف گیا۔\n2۔ اور ابرام مویشیوں، چاندی اور سونے میں بہت امیر تھا۔\n3۔ اور وہ جنوب سے بیٹھل تک سفر کرتا رہا، اس جگہ جہاں اس کا خیمہ شروع میں تھا، بیت تھل اور ہائی کے درمیان؛\n4۔ اس قربان گاہ کی جگہ پر، جو اس نے پہلی بار وہاں بنائی تھی: اور وہاں ابرام نے خداوند کا نام پکارا۔\n5۔ اور لوط بھی، جو ابرام کے ساتھ تھا، کے ریوڑ، ریوڑ اور خیمے تھے۔\n6۔ اور زمین انہیں برداشت نہ کر سکی، تاکہ وہ اکٹھے رہ سکیں: کیونکہ ان کا مال بہت بڑا تھا، اس لیے وہ اکٹھے نہیں رہ سکتے تھے۔\n7۔ اور ابرام کے مویشی پالنے والوں اور لوط کے مویشی پالنے والوں کے درمیان جھگڑا ہوا، اور کنعانی اور پرزی اس وقت اس زمین میں آباد تھے۔\n8۔ اور ابرام نے لوط سے کہا، میں تم سے درخواست کرتا ہوں کہ میرے اور تمہارے درمیان، اور میرے چرواہوں اور تمہارے چرواہوں کے درمیان کوئی جھگڑا نہ ہو؛ کیونکہ ہم بھائی ہیں۔ {بھائیو: عبرانی۔ مرد بھائی}\n9. {کیا} تمہارے سامنے پوری زمین نہیں ہے؟ اپنے آپ کو مجھ سے جدا کرو، میں دعا کرتا ہوں: اگر {تم چاہو} بایاں ہاتھ پکڑو، تو میں دائیں طرف جاؤں گا؛ یا اگر {تم دائیں طرف چلے جاؤ}، تو میں بائیں طرف جاؤں گا۔\n10۔ اور لوط نے اپنی آنکھیں اٹھائیں، اور پورے اردن کے میدان کو دیکھا، جو ہر جگہ اچھی طرح پانی دیا گیا تھا، اس سے پہلے کہ خداوند نے سدوم اور عمورہ کو تباہ کیا، {حتیٰ کہ} خداوند کے باغ کی طرح، جیسے مصر کی زمین، جیسا کہ تم زوار آتے ہو۔\n11۔ پھر لوط نے اسے پورے اردن کے میدان میں چنا؛ اور لوط مشرق کی طرف روانہ ہوا: اور وہ ایک دوسرے سے الگ ہو گئے۔\n12۔ ابرام کنعان کی سرزمین میں رہتا تھا، اور لوط میدان کے شہروں میں رہتا تھا، اور اس نے سدوم کی طرف اپنا خیمہ کھڑا کیا۔\n13۔ لیکن سدوم کے لوگ خداوند کے سامنے بہت برے اور گناہ گار تھے۔\n14۔ اور خداوند نے ابرام سے کہا، جب لوط اس سے جدا ہو گیا، اب اپنی آنکھیں اٹھاؤ، اور اس جگہ سے دیکھو جہاں تم شمال، جنوب، مشرق اور مغرب کی طرف ہو:\n15۔ جو بھی زمین تم دیکھتے ہو، میں تمہیں دوں گا، اور تمہاری نسل کو ہمیشہ کے لیے۔\n16۔ اور میں تمہاری نسل کو زمین کی مٹی کی طرح بناؤں گا: تاکہ اگر کوئی انسان زمین کی خاک کو گنے گا، تو تمہارا نسل بھی گنے گا۔\n17. اٹھو، زمین میں اس کی لمبائی اور چوڑائی میں چلو؛ کیونکہ میں تمہیں دے دوں گا۔\n18۔ پھر ابرام نے اپنا خیمہ ہٹایا، اور مامر کے میدان میں آ کر بسنے لگا، جو حبرون میں {ہے}، اور وہاں خداوند کے لیے ایک قربان گاہ تعمیر کی۔ {سادہ: عبرانی۔ میدان}","1۔ اور یہ واقعہ امرافیل بادشاہ شینار، اریوخ بادشاہ ایلاسار، کیدرلاومر بادشاہ ایلام، اور ٹائیڈل بادشاہ قوموں کے دنوں میں ہوا؛\n2. {کہ یہ لوگ} سدوم کے بادشاہ بیرا سے، اور عمورہ کے بادشاہ برشا، آدمہ کے بادشاہ شیناب، زیبوئیم کے بادشاہ شیمبر، اور بیلا کے بادشاہ زوار سے جنگ کرتے ہیں۔\n3۔ یہ سب سیدیم کی وادی میں آپس میں ملے، جو نمکین سمندر ہے۔\n4۔ انہوں نے بارہ سال کیڈورلاومر کی خدمت کی، اور تیرہویں سال انہوں نے بغاوت کی۔\n5۔ اور چودہویں سال میں چیدرلاؤمر آیا، اور وہ بادشاہ جو اس کے ساتھ تھے، اور انہوں نے آشتروت کارنائم میں ریفیم، ہام میں زوزیم، اور شاوے کریاتائیم میں ایمس کو شکست دی، {شاوے...: یا، کریاتائیم کا میدان}\n6۔ اور ہورائٹس اپنے پہاڑ سیئر میں، ایلپارن کی طرف، جو {ویراں} کے پاس ہے۔ {ایلپاران: یا، پاران کا میدان}\n7۔ اور وہ واپس آئے، اور اینمشپت پہنچے، جو {ہے} قادش، اور امالکیوں کے تمام ملک اور حزیزونتمار میں بسنے والے اموری کو بھی شکست دی۔\n8۔ اور وہاں سدوم کا بادشاہ، عمورہ کا بادشاہ، آدمہ کا بادشاہ، زبوییم کا بادشاہ، اور بیلا کا بادشاہ (وہی زوار ہے؛) نکلے اور وہ سیدیم کی وادی میں ان کے ساتھ جنگ میں شامل ہوئے؛\n9۔ ایلام کے بادشاہ چیدرلاومر کے ساتھ، قوموں کے بادشاہ جزر و مد کے ساتھ، شینار کے بادشاہ امرافیل کے ساتھ، اور ایلاسر کے بادشاہ آریوخ؛ چار بادشاہ پانچ کے ساتھ۔\n10۔ اور سیدیم کی وادی سلائمپٹس سے بھری ہوئی تھی؛ اور سدوم اور عمورہ کے بادشاہ بھاگ گئے اور وہاں گر گئے؛ اور جو بچے وہ پہاڑ کی طرف بھاگ گئے۔\n11۔ اور انہوں نے سدوم اور عمورہ کی تمام اشیاء اور اپنی تمام خوراک لے کر اپنی راہ پر چل دی۔\n12۔ اور انہوں نے لوط، ابرام کے بھائی کے بیٹے کو، جو سدوم میں رہتا تھا، اور اس کی مالیں لے کر روانہ ہو گئے۔\n13۔ اور ایک آیا جو فرار ہو گیا تھا، اور ابرام کو عبرانی بتایا؛ کیونکہ وہ مامرے دی اموری کے میدان میں رہتا تھا، جو اشکول کا بھائی اور انیر کا بھائی تھا: اور یہ سب ابرام کے ساتھ اتحاد میں تھے۔ {سادہ: عبرانی۔ میدان}\n14۔ اور جب ابرام نے سنا کہ اس کا بھائی قید ہو گیا ہے، تو اس نے اپنے تربیت یافتہ {خادم} کو مسلح کیا، جو اس کے اپنے گھر میں پیدا ہوئے، تین سو اٹھارہ سال کے، اور {ان} کا پیچھا کر کے دان تک گیا۔ {مسلح: یا، آگے لے جایا گیا} {تربیت یافتہ: یا، ہدایت دی گئی}\n15۔ اور اس نے رات کو ان کے خلاف خود کو تقسیم کر لیا، اور انہیں مارا اور ہوبہ تک پیچھا کیا، جو دمشق کے بائیں طرف واقع ہے۔\n16۔ اور اس نے سارا سامان واپس لایا، اور اپنے بھائی لوط، اس کا سامان، عورتیں بھی، اور عوام کو دوبارہ لایا۔\n17۔ اور سدوم کا بادشاہ چیدرلاومر کے قتل عام سے واپسی کے بعد اور ان بادشاہوں کے ساتھ جو اس کے ساتھ تھے، شاویہ کی وادی میں اس سے ملنے نکلا، جو بادشاہ کی وادی ہے۔\n18۔ اور سلیم کے بادشاہ ملک صادق نے روٹی اور شراب نکالی: اور وہ سب سے بلند خدا کا پادری تھا۔\n19۔ اور اس نے اسے برکت دی اور کہا، مبارک ہو ابرام جو سب سے بلند خدا کا ہے، جو آسمان و زمین کا مالک ہے:\n20۔ اور سب سے بلند خدا مبارک ہو، جس نے تیرے دشمنوں کو تیرے ہاتھ میں دے دیا ہے۔ اور اس نے اسے سب سے عشر دیا۔\n21۔ اور سدوم کے بادشاہ نے ابرام سے کہا، مجھے وہ لوگ دو، اور مال اپنے پاس لے لو۔ {افراد: عبرانی۔ روحیں}\n22۔ اور ابرام نے سدوم کے بادشاہ سے کہا، میں نے اپنا ہاتھ خداوند کی طرف اٹھا دیا ہے، جو سب سے بلند خدا، آسمان و زمین کا مالک ہے،\n23۔ کہ میں کسی دھاگے سے جوتے کی چٹ تک بھی نہیں لے جاؤں گا، اور نہ ہی کوئی چیز جو تمہاری ہے، ورنہ تم کہہ دو کہ میں نے ابرام کو امیر بنا دیا ہے:\n24۔ صرف وہی جو نوجوانوں نے کھایا ہے، اور ان لوگوں کا حصہ جو میرے ساتھ گئے، انر، اشکول، اور مامرے کے ساتھ؛ انہیں اپنا حصہ لینے دو۔","1۔ ان سب باتوں کے بعد خداوند کا کلام ابرام کو ایک خواب میں آیا، جس میں کہا، ابرام، خوف نہ کرو: میں تمہارا ڈھال ہوں، اور تمہارا بے پناہ بڑا اجر ہوں۔\n2۔ اور ابرام نے کہا، اے خدا، تو مجھے کیا دو گے جب میں بے اولاد رہوں اور میرے گھر کا منتظم یہ الیعزر آف دمشق ہے؟\n3۔ اور ابرام نے کہا، دیکھو، تم نے مجھے کوئی بیج نہیں دیا، اور دیکھو، میرے گھر میں پیدا ہونے والا میرا وارث ہے۔\n4۔ اور دیکھو، خداوند کا کلام اس کے پاس آیا، کہتا ہے، یہ تمہارا وارث نہیں ہوگا؛ لیکن جو تمہارے اندر سے نکلے گا وہ تمہارا وارث ہوگا۔\n5۔ اور اس نے اسے باہر لے جا کر کہا، اب آسمان کی طرف دیکھو، اور ستاروں کو بتاؤ، اگر تم انہیں گننے کے قابل ہو، اور اس نے کہا، تمہاری نسل بھی ایسی ہی ہوگی۔\n6۔ اور اس نے خداوند پر ایمان لایا؛ اور اس نے اسے راستبازی کے طور پر شمار کیا۔\n7۔ اور اس نے اس سے کہا، میں وہ خداوند ہوں جس نے تمہیں کلدیوں سے نکالا، تاکہ یہ زمین تمہیں اس کا وارث دوں۔\n8۔ اور اس نے کہا، اے خدا، میں کس طرح جانوں کہ میں اس کا وارث بنوں گا؟\n9۔ اور اس نے اس سے کہا، میرے لیے تین سال کی ایک بچھی، تین سال کی مادہ بکری، تین سال کی ایک مینڈھا، ایک کبوتر اور ایک نوجوان کبوتر لے آؤ۔\n10۔ اور اس نے یہ سب اپنے پاس لے لیے، انہیں درمیان میں بانٹ دیا، اور ہر ٹکڑا ایک دوسرے کے خلاف رکھا، لیکن پرندوں نے اسے تقسیم نہیں کیا۔\n11۔ اور جب مرغیاں لاشوں پر گریں، ابرام نے انہیں بھگا دیا۔\n12۔ اور جب سورج غروب ہو رہا تھا، ابراہم پر گہری نیند آ گئی؛ اور، دیکھو، اس پر شدید تاریکی کا خوف چھا گیا۔\n13۔ اور اس نے ابرام سے کہا، یقین کرو کہ تمہاری نسل کسی ایسی سرزمین میں اجنبی ہوگی {جو ان کی نہیں}، اور ان کی خدمت کرے گی؛ اور انہیں چار سو سال تک تکلیف دی جائے گی؛\n14۔ اور اس قوم کا بھی، جس کی وہ خدمت کریں گے، میں فیصلہ کروں گا: اور اس کے بعد وہ بڑی طاقت کے ساتھ باہر آئیں گے۔\n15۔ اور تم اپنے باپ اجداد کے پاس امن کے ساتھ جاؤ گے؛ تمہیں اچھے بوڑھے عمر میں دفن کیا جائے گا۔\n16۔ لیکن چوتھی نسل میں وہ دوبارہ یہاں آئیں گے: کیونکہ اموریوں کی بدکاری ابھی مکمل نہیں ہوئی۔\n17۔ اور ایسا ہوا کہ جب سورج غروب ہوا اور اندھیرا تھا، تو ایک دھواں دار بھٹی اور ایک جلتا ہوا چراغ ان ٹکڑوں کے درمیان سے گزرا۔ {ایک جلتا ہوا...: عبرانی۔ آگ کا چراغ}\n18۔ اسی دن خداوند نے ابرام سے عہد کیا اور کہا، میں نے یہ زمین تمہاری نسل کو دی ہے، جو مصر کے دریا سے لے کر دریائے فرات تک ہے:\n19۔ کنائٹس، کینیزیتس، اور کدمونائیٹس،\n20۔ اور حتی، اور پرزی، اور رفیم،\n21۔ اور اموری، کنعانی، گرگاشی، اور یبوسیت۔","1۔ اب سرائی ابرام کی بیوی نے اسے کوئی اولاد نہیں دی: اور اس کی ایک خادمہ تھی، ایک مصری، جس کا نام {تھا} ہاجر۔\n2۔ اور سرائی نے ابرام سے کہا، دیکھو، خداوند نے مجھے حمل سے روکا ہے: میں تم سے دعا کرتا ہوں، میری خادمہ کے پاس جاؤ؛ ممکن ہے کہ میں اس سے بچے حاصل کر سکوں۔ اور ابرام نے سرائی کی آواز سنی۔ {حاصل کریں...: عبرانی۔ اس کے ذریعے بنایا جائے گا}\n3۔ اور سرائی ابرام کی بیوی نے ہاجر، اپنی خادمہ جو مصری تھی، لے لی، جب ابرام نے کنعان کی زمین میں دس سال گزارے، اور اسے اپنے شوہر ابرام کو اپنی بیوی کے طور پر دے دیا۔\n4۔ اور وہ ہاجرہ کے پاس گیا، اور وہ حاملہ ہوئی، اور جب اس نے دیکھا کہ اس نے حاملہ ہو گئی ہے، تو اس کی مالکن کی نظر میں حقیر ہو گئی۔\n5۔ اور سرائی نے ابرام سے کہا، میری غلطی تم پر ہے: میں نے اپنی کنواری کو تمہاری گود میں دے دیا ہے؛ اور جب اس نے دیکھا کہ اس نے حاملہ ہو گئی ہے، تو اس کی نظر میں مجھے حقارت کا سامنا کرنا پڑا: خداوند میرے اور تیرے درمیان فیصلہ کرے۔\n6۔ لیکن ابرام نے سرائی سے کہا، دیکھو، تمہاری لڑکی تمہارے ہاتھ میں ہے؛ اس کے ساتھ جیسا چاہو کرو۔ اور جب سرائی نے اس سے زیادہ توجہ نہیں دی، تو وہ اس کے چہرے سے بھاگ گئی۔ {یعنی...: عبرانی جو تمہاری نظر میں اچھا ہے} {تقسیم شدہ...: عبرانی۔ اسے متاثر کیا}\n7۔ اور خداوند کے فرشتے نے اسے بیابان میں پانی کے چشمے کے پاس پایا، شور کے راستے میں چشمے کے پاس۔\n8۔ اور اس نے کہا، ہاجر، سرائی کی خادمی، کہاں سے آئی ہو؟ اور کہاں جاؤ گے؟ اور اس نے کہا، میں اپنی معشوقہ سرائی کے چہرے سے بھاگ رہی ہوں۔\n9۔ اور خداوند کے فرشتے نے اس سے کہا، اپنی مالکن کے پاس واپس جاؤ اور اس کے ہاتھوں کے نیچے سر تسلیم کرو۔\n10۔ اور خداوند کے فرشتے نے اس سے کہا، میں تمہاری نسل کو بہت زیادہ بڑھاؤں گا، کہ اسے کثرت کے حساب سے شمار نہ کیا جائے۔\n11۔ اور خداوند کے فرشتے نے اس سے کہا، دیکھو، تم حاملہ ہو، اور بیٹا پیدا کرو گی، اور اس کا نام اسماعیل رکھو گی؛ کیونکہ خداوند نے تمہاری تکلیف سن لی ہے۔ {اسماعیل: یعنی، خدا سنے گا}\n12۔ اور وہ ایک جنگلی آدمی ہوگا؛ اس کا ہاتھ ہر انسان کے خلاف ہوگا، اور ہر آدمی کا ہاتھ اس کے خلاف؛ اور وہ اپنے تمام بھائیوں کی موجودگی میں رہے گا۔\n13۔ اور اس نے اس خداوند کا نام پکارا جس نے اس سے کہا، تو خدا مجھے دیکھتا ہے: کیونکہ اس نے کہا، کیا میں نے بھی اس کی دیکھ بھال کی ہے جو مجھے دیکھتا ہے؟\n14۔ اسی لیے اس کنویں کو بیرلاہیری کہا جاتا تھا؛ دیکھو، {یہ ہے} قادیش اور بیرڈ کے درمیان۔ {بیرلاہیروئی: یعنی، اس کا کنواں جو مجھے زندہ اور سکھاتا ہے}\n15۔ اور ہاجرہ نے ابرام کو بیٹا پیدا کیا: اور ابرام نے اپنے بیٹے کا نام ہجرہ کا نام اسماعیل رکھا۔\n16۔ اور ابرام چالیس اور چھ سال کا تھا، جب ہاجر نے اسماعیل کو ابرام کے ہاں جنم دیا۔","1۔ اور جب ابرام نوے سال کا اور نو سال کا ہوا، خداوند ابریم پر ظاہر ہوا اور اسے کہا، میں قادر مطلق خدا ہوں؛ میرے سامنے چلو، اور کامل بنو۔ {کامل: یا، سیدھا، یا مخلص}\n2۔ اور میں اپنے اور تمہارے درمیان اپنا عہد کروں گا، اور تمہیں بہت زیادہ بڑھاؤں گا۔\n3۔ اور ابرام اپنے چہرے کے بل گر پڑا: اور خدا نے اس سے بات کی اور کہا،\n4۔ جہاں تک میرا تعلق ہے، دیکھو، میرا عہد {ہے} تم کے ساتھ، اور تم کئی قوموں کا باپ بنو گے۔ {بہت سے...: عبرانی۔ اقوام کی کثرت}\n5۔ نہ تو تمہارا نام اب ابرام کہا جائے گا، بلکہ تمہارا نام ابراہیم ہوگا؛ کیونکہ میں نے تمہیں کئی قوموں کا باپ بنایا ہے۔ {ابراہیم: یعنی، بڑی تعداد کا باپ}\n6۔ اور میں تمہیں بے حد پھلدار بناؤں گا، اور تم سے قومیں بناؤں گا، اور بادشاہ تم سے نکلیں گے۔\n7۔ اور میں اپنے اور تمہارے درمیان اور تیری نسل کے درمیان اپنی نسل در نسل ایک دائمی عہد قائم کروں گا، تاکہ وہ تمہارے لیے خدا بن سکوں، اور تمہاری نسل کے بعد بھی۔\n8۔ اور میں تمہیں اور تمہاری نسل کو وہ زمین دوں گا جس میں تم اجنبی ہو، کنعان کی ساری زمین، ہمیشہ کے لیے ایک دائمی ملکیت کے لیے؛ اور میں ان کا خدا بنوں گا۔ {جس میں...: عبرانی۔ تمہارے قیام کے بارے میں}\n9۔ اور خدا نے ابراہیم سے کہا، تو میرا عہد پورا کرو گے، تو اور تمہاری نسل در نسل اپنی نسلوں میں۔\n10. یہ میرا عہد ہے، جسے تم میرے اور تمہارے درمیان اور تمہاری نسل کے درمیان رکھو گے؛ تم میں سے ہر مرد بچہ ختنہ کیا جائے گا۔\n11۔ اور تم اپنی ختنہ کی جلد کا ختنہ کرو گے؛ اور یہ میرے اور تمہارے درمیان عہد کی نشانی ہوگی۔\n12۔ اور جو آٹھ دن کا ہے وہ تم میں سے ختنہ کیا جائے گا، تمہاری نسل کے ہر مرد بچہ، جو گھر میں پیدا ہوا ہو، یا کسی اجنبی کے پیسے سے خریدا گیا ہو، جو تمہاری نسل سے نہ ہو۔ {وہ جو آٹھ سال کا ہے...: عبرانی۔ آٹھ دن کا بیٹا}\n13۔ جو تمہارے گھر میں پیدا ہوا اور جو تمہارے پیسے سے خریدا جائے، اسے ختنہ کروانا ضروری ہے: اور میرا عہد تمہارے جسم میں ہمیشہ کے لیے ہوگا۔\n14۔ اور وہ غیر ختنہ شدہ بچہ جس کی پیشاب کی کھال کا گوشت ختنہ شدہ نہ ہو، وہ روح اس کی قوم سے کاٹ دی جائے گی؛ اس نے میرا عہد توڑ دیا ہے۔\n15۔ اور خدا نے ابراہیم سے کہا، جہاں تک تمہاری بیوی سرائی کا تعلق ہے، تو اس کا نام سرائی نہیں رکھنا، بلکہ سارہ کو اس کا نام {بنے} گا۔ {سارہ: یہ پرنسس ہے}\n16۔ اور میں اسے برکت دوں گا، اور تمہیں اس کا بیٹا بھی دوں گا: ہاں، میں اسے برکت دوں گا، اور وہ قوموں کی ماں بنے گی؛ لوگوں کے بادشاہ اس کے ہوں گے۔ {وہ...: عبرانی۔ وہ قومیں بن جائے گی}\n17۔ پھر ابراہیم اپنے چہرے کے بل گر پڑا، ہنسا، اور دل ہی دل میں کہا، کیا سو سالہ بچے کو پیدا کیا جائے گا؟ اور کیا سارہ، جو نوے سال کی ہے، برداشت کرے گی؟\n18۔ اور ابراہیم نے خدا سے کہا، اے اسماعیل تیرے سامنے زندہ رہے!\n19۔ اور خدا نے کہا، سارہ تیری بیوی تمہیں واقعی بیٹا دے گی؛ اور تم اس کا نام اسحاق رکھو گے: اور میں اس کے ساتھ ہمیشہ کے لیے عہد کروں گا، {اور} اس کے بعد اس کی نسل کے ساتھ۔\n20۔ اور جہاں تک اسماعیل کا تعلق ہے، میں نے تمہاری بات سن لی ہے: دیکھو، میں نے اسے برکت دی ہے، اور اسے پھلدار بناؤں گا، اور اسے بہت زیادہ بڑھاؤں گا؛ وہ بارہ شہزادے پیدا کرے گا، اور میں اسے ایک عظیم قوم بناؤں گا۔\n21. لیکن میں اپنا عہد اسحاق کے ساتھ قائم کروں گا، جو سارہ اگلے سال اس مقررہ وقت پر تمہیں دے گی۔\n22۔ اور اس نے اس سے بات کرنا چھوڑ دی، اور خدا ابراہیم سے اوپر آیا۔\n23۔ اور ابراہیم نے اپنے بیٹے اسماعیل کو، اور اپنے گھر میں پیدا ہونے والے سب اور جو اس کے پیسے سے خریدے گئے تھے، ابراہیم کے گھر کے ہر مرد کو لے لیا؛ اور اسی دن ان کی ختنہ کی جلد کا ختنہ کیا، جیسا کہ خدا نے اسے کہا تھا۔\n24۔ اور ابراہیم نوے سال کا تھا اور نو سال کا تھا، جب اسے اپنی پیشاب کی جلد کے گوشت میں ختنہ کیا گیا۔\n25۔ اور اس کا بیٹا اسماعیل تیرہ سال کا تھا، جب اسے اپنی ختنہ کی کھال کے گوشت میں ختنہ کیا گیا۔\n26۔ اسی دن ابراہیم کا ختنہ کیا گیا، اور اس کا بیٹا اسماعیل بنا۔\n27۔ اور اس کے گھر کے تمام مرد، جو اس گھر میں پیدا ہوئے اور اجنبی کے پیسے سے خریدے گئے، اس کے ساتھ ختنہ کیے گئے۔","1۔ اور خداوند نے اسے مامرے کے میدانوں میں ظاہر کیا: اور وہ دن کی گرمی میں خیمے کے دروازے پر بیٹھ گیا؛ {سادہ: عبرانی۔ میدان}\n2۔ اور اس نے اپنی آنکھیں اٹھائیں اور دیکھا، اور دیکھو، تین آدمی اس کے ساتھ کھڑے تھے: اور جب اس نے انہیں دیکھا، تو وہ خیمے کے دروازے سے دوڑ کر ان کا استقبال کرنے لگا، اور زمین کی طرف جھک گیا،\n3۔ اور کہا، میرے رب، اگر اب میں نے تیری نظر میں مہربانی پائی ہے، تو میں تم سے درخواست کرتا ہوں کہ اپنے بندے سے دور نہ ہو:\n4۔ تھوڑا سا پانی لے آؤ، میں تم سے دعا کرتا ہوں، اپنے پاؤں دھو لو، اور درخت کے نیچے آرام کرو:\n5۔ اور میں روٹی کا ایک ٹکڑا لاؤں گا، اور آپ کے دلوں کو تسلی دوں گا؛ اس کے بعد تم گزر جاؤ گے: کیونکہ تم اپنے خادم کے پاس آئے ہو۔ اور انہوں نے کہا، ویسا ہی کرو، جیسا تم نے کہا۔ {کمفرٹ: عبرانی۔ رہو} {ہیں...: عبرانی آپ پاس ہو چکے ہیں}\n6۔ اور ابراہیم جلدی سے خیمے میں سارہ کے پاس آیا اور کہا، تین عمدہ کھانے کے پیسے جلدی تیار کرو، اسے گوندھو، اور چولہے پر کیک بناؤ۔ {تیار ہو جاؤ...: عببری۔ جلدی کریں}\n7۔ اور ابراہیم ریوڑ کی طرف دوڑا، ایک نرم اور اچھا بچھڑا لایا اور اسے ایک نوجوان کو دے دیا؛ اور اس نے جلدی سے اسے تیار کیا۔\n8۔ اور اس نے مکھن، دودھ اور وہ بچھڑا لیا جو اس نے تیار کیا تھا، اور ان کے سامنے رکھ دیا؛ اور وہ ان کے ساتھ درخت کے نیچے کھڑا رہا، اور وہ واقعی کھاتے تھے۔\n9۔ اور انہوں نے اس سے کہا، سارہ تمہاری بیوی کہاں ہے؟ اور اس نے کہا، دیکھو، خیمے میں۔\n10۔ اور اس نے کہا، میں زندگی کے وقت کے مطابق ضرور تمہارے پاس واپس آؤں گا؛ اور، دیکھو، سارہ تمہاری بیوی کا ایک بیٹا ہوگا۔ اور سارہ نے خیمے کے دروازے میں سنا، جو اس کے پیچھے تھا۔\n11۔ اب ابراہیم اور سارہ بوڑھے {اور} بوڑھے ہو چکے تھے؛ {اور} سارہ کے ساتھ عورتوں کی طرح رہنا بند ہو گیا۔\n12۔ اس لیے سارہ نے دل ہی دل میں ہنستے ہوئے کہا، کیا میں بوڑھا ہو جاؤں گی، میرے رب بھی بوڑھے ہو جائیں گے؟\n13۔ اور خداوند نے ابراہیم سے کہا، سارہ نے ہنس کر کہا، کیا میں ایک بوڑھا بچہ پیدا کروں گا؟\n14. کیا کوئی چیز خدا کے لیے بہت مشکل ہے؟ مقررہ وقت پر میں زندگی کے وقت کے مطابق تمہارے پاس واپس آؤں گا، اور سارہ کا بیٹا ہوگا۔\n15۔ پھر سارہ نے انکار کیا اور کہا، میں نے ہنسی نہیں؛ کیونکہ وہ ڈری ہوئی تھی۔ اور اس نے کہا، نہیں؛ لیکن تم ہنس پڑے۔\n16۔ اور وہاں سے مرد اٹھے اور سدوم کی طرف دیکھنے لگے، اور ابراہیم ان کے ساتھ گیا تاکہ انہیں راستے پر لے جائے۔\n17۔ اور خداوند نے فرمایا، کیا میں ابراہیم سے وہ کام چھپاؤں جو میں کرتا ہوں؟\n18۔ یہ دیکھ کر کہ ابراہیم یقینا ایک عظیم اور طاقتور قوم بنے گا، اور زمین کی تمام اقوام اس میں برکت پائیں گی؟\n19۔ کیونکہ میں اسے جانتا ہوں، کہ وہ اپنے بچوں اور گھر والوں کو حکم دے گا، اور وہ خداوند کے راستے پر عمل کریں گے، انصاف اور انصاف کریں گے؛ تاکہ خداوند ابراہیم پر وہ سب کچھ لے آئے جو اس نے اس کے بارے میں کہا ہے۔\n20۔ اور خداوند نے فرمایا، کیونکہ سدوم اور عمورہ کی پکار بہت بڑی ہے، اور کیونکہ ان کا گناہ بہت سنگین ہے؛\n21۔ اب میں نیچے جا کر دیکھوں گا کہ کیا انہوں نے اس کے پکار کے مطابق کیا ہے، جو میرے پاس آئی ہے؛ اور اگر نہیں، تو مجھے معلوم ہو جائے گا۔\n22۔ اور لوگ وہاں سے منہ موڑ کر سدوم کی طرف بڑھے، لیکن ابراہیم ابھی بھی خداوند کے سامنے کھڑا تھا۔\n23۔ اور ابراہیم قریب آیا اور کہا، کیا تم نیک لوگوں کو بھی بدکاروں کے ساتھ تباہ کرو گے؟\n24۔ شاید شہر میں پچاس نیک ہوں: کیا تم بھی وہاں موجود پچاس نیک لوگوں کو تباہ کر دو گے اور جگہ نہیں چھوڑو گے؟\n25. جو تم سے دور ہے کہ اس طرح کے بعد نیک لوگوں کو بدکاروں کے ساتھ مارو: اور نیک بھی بدکاروں کی طرح ہوں جو تم سے دور ہیں: کیا زمین کے تمام منصف کا انصاف نہیں کرے گا؟\n26۔ اور خداوند نے فرمایا، اگر میں سدوم میں شہر کے اندر پچاس نیک پاؤں لوں، تو میں ان کی خاطر سب جگہ چھوڑ دوں گا۔\n27۔ اور ابراہیم نے جواب دیا اور کہا، دیکھو، میں نے خود پر ذمہ داری لے لی ہے کہ میں خداوند سے بات کروں، جو {میں} صرف خاک اور راکھ ہوں:\n28۔ شاید پچاس راستبازوں میں سے پانچ کی کمی ہو: کیا تم پانچ کی کمی کی وجہ سے پورا شہر تباہ کر دو گے؟ اور اس نے کہا، اگر میں وہاں پینتالیس اور پینتالیس پاؤں تو میں اسے تباہ نہیں کروں گا۔\n29۔ اور اس نے ایک بار پھر اس سے بات کی، اور کہا، شاید وہاں چالیس ملیں گے۔ اور اس نے کہا، میں چالیس کی خاطر یہ نہیں کروں گا۔\n30۔ اور اس نے {اس سے} کہا، اے خداوند غصہ نہ کرے، اور میں بولوں گا: شاید وہاں تیس لوگ پائے جائیں۔ اور اس نے کہا، میں یہ نہیں کروں گا اگر مجھے وہاں تیس لوگ مل جائیں۔\n31۔ اور اس نے کہا، دیکھو، اب میں نے خدا سے بات کرنے کی ذمہ داری لی ہے: شاید وہاں بیس پائے جائیں۔ اور اس نے کہا، میں بیس کی خاطر اسے تباہ نہیں کروں گا۔\n32۔ اور اس نے کہا، اے خداوند غصہ نہ کرے، اور میں صرف اس بار بولوں گا: شاید وہاں دس لوگ پائے جائیں گے۔ اور اس نے کہا، میں اسے دس کی خاطر تباہ نہیں کروں گا۔\n33۔ اور خداوند اپنے راستے پر چلا گیا، جیسے ہی وہ ابراہیم سے بات چیت کے لیے روانہ ہوا: اور ابراہیم اپنے مقام پر واپس آیا۔","1۔ اور دو فرشتے سدوم کے برابر آئے؛ اور لوط سدوم کے دروازے پر بیٹھا: اور لوط نے دیکھا کہ {ان} ان کا استقبال کرنے کے لیے اٹھ کھڑے ہوئے؛ اور اس نے اپنا چہرہ زمین کی طرف جھکا لیا؛\n2۔ اور اس نے کہا، دیکھو، میرے لارڈز، میں آپ سے درخواست کرتا ہوں کہ اپنے خادم کے گھر میں جاؤ، اور ساری رات ٹھہریں، اپنے پاؤں دھوئیں، اور آپ جلدی اٹھیں اور اپنی راہوں پر روانہ ہوں۔ اور انہوں نے کہا، نہیں؛ لیکن ہم ساری رات سڑک پر رہیں گے۔\n3۔ اور اس نے ان پر بہت دباؤ ڈالا؛ اور وہ اس کے پاس مڑے، اور اس کے گھر میں داخل ہوئے؛ اور اس نے ان کے لیے دعوت بنائی، اور بغیر خمیر کی روٹی بنائی، اور انہوں نے کھایا۔\n4۔ لیکن لیٹنے سے پہلے، شہر کے لوگ، {حتیٰ کہ} سدوم کے لوگ بھی، بوڑھے اور جوان دونوں جگہ کے ارد گرد گھوم گئے، ہر طرف کے لوگ:\n5۔ اور انہوں نے لوط کو پکارا اور کہا، وہ لوگ کہاں ہیں جو آج رات تمہارے پاس آئے تھے؟ انہیں ہمارے پاس لے آؤ، تاکہ ہم انہیں جان سکیں۔\n6۔ اور لوط دروازے پر ان کے پاس گیا، اور اس کے پیچھے دروازہ بند کر دیا،\n7۔ اور کہا، بھائیو، میں آپ سے دعا کرتا ہوں کہ اتنی بد کاری نہ کریں۔\n8۔ اب دیکھو، میرے دو بیٹیاں ہیں جو انسان کو نہیں جانتیں؛ میں، میں تم سے درخواست کرتا ہوں، انہیں تمہارے پاس لے آؤں، اور تم ان کے ساتھ ویسا ہی کرو جیسا تمہاری نظر میں اچھا ہے: صرف ان لوگوں کے لیے کچھ نہ کرنا؛ اسی لیے وہ میرے چھت کے سائے تلے آئے۔\n9۔ اور انہوں نے کہا، پیچھے ہٹو۔ اور انہوں نے کہا {دوبارہ}، یہ ایک {بندہ} ٹھہرنے آیا ہے، اور اسے ایک منصف کی ضرورت ہے: اب ہم تمہارے ساتھ ان سے بدتر سلوک کریں گے۔ اور وہ اس آدمی، حتیٰ کہ لوط پر بھی دباؤ ڈالے اور دروازہ توڑنے کے قریب پہنچے۔\n10۔ لیکن آدمیوں نے ہاتھ بڑھایا، اور لوط کو گھر میں کھینچ کر دروازہ بند کر دیا۔\n11۔ اور انہوں نے گھر کے دروازے پر کھڑے مردوں کو اندھے پن سے مارا، چاہے وہ چھوٹے ہوں یا بڑے، یہاں تک کہ وہ دروازہ تلاش کرنے کے لیے تھک گئے۔\n12۔ اور مردوں نے لوط سے کہا، کیا تمہارے پاس اس کے علاوہ کوئی چیز ہے؟ داماد، اور تمہارے بیٹے، اور تمہاری بیٹیاں، اور جو کچھ بھی تمہارے شہر میں ہے، انہیں یہاں سے لے آؤ:\n13۔ کیونکہ ہم اس جگہ کو تباہ کر دیں گے، کیونکہ ان کی پکار خداوند کے چہرے کے سامنے بہت بڑی ہو گئی ہے؛ اور خداوند نے ہمیں اسے تباہ کرنے کے لیے بھیجا ہے۔\n14۔ اور لوط باہر گیا، اور اپنے داماد سے بات کی، جس نے اس کی بیٹیوں کی شادی کی، اور کہا، اوپر، تمہیں یہاں سے نکالو؛ کیونکہ خداوند اس شہر کو تباہ کر دے گا۔ لیکن وہ اپنے دامادوں کا مذاق اڑانے والا لگتا تھا۔\n15۔ اور جب صبح ہوئی، تو فرشتوں نے لوط کو جلدی سے بلایا اور کہا، اٹھو، اپنی بیوی اور اپنی دو بیٹیوں کو لے لو، جو یہاں ہیں؛ کہیں تم شہر کی گناہوں میں نہ کھو جاؤ۔ {یہاں ہیں: عبرانی۔ ملتے ہیں} {بدکاری: یا، سزا}\n16۔ اور جب وہ ٹھہرا رہا، مردوں نے اس کا ہاتھ، اس کی بیوی کے ہاتھ اور اس کی دو بیٹیوں کے ہاتھ کو تھام لیا؛ خداوند نے اس پر رحم کیا: اور انہوں نے اسے باہر نکالا اور شہر سے باہر رکھا۔\n17۔ اور جب وہ انہیں باہر لے آئے تو اس نے کہا، اپنی جان کے لیے فرار ہو جاؤ؛ پیچھے مت دیکھو، نہ ہی پورے میدان میں رہو؛ پہاڑ کی طرف بھاگ جاؤ، ورنہ تمہیں نگل لیا جائے گا۔\n18۔ اور لوط نے ان سے کہا، اوہ، ایسا نہیں ہے، میرے رب:\n19۔ اب دیکھو، تمہارے خادم نے تمہاری نظر میں فضل پا لیا ہے، اور تم نے اپنی رحمت کو بڑھا دیا ہے، جو تم نے میری جان بچانے میں مجھ پر دکھائی؛ اور میں پہاڑ کی طرف نہیں بھاگ سکتا، ورنہ کوئی برائی مجھے لے لے گی، اور میں مر جاؤں:\n20. دیکھو، یہ شہر {بھاگنے کے قریب} ہے، اور یہ {چھوٹا} ہے: اوہ، مجھے وہاں بھاگنے دو، ({کیا} یہ چھوٹا نہیں؟) اور میری روح زندہ رہے گی۔\n21۔ اور اس نے اس سے کہا، دیکھو، میں نے اس معاملے میں بھی تمہیں قبول کر لیا ہے، کہ میں اس شہر کو نہیں گرا سکوں گا، جس کے لیے تم نے کہا ہے۔ {thee: Heb. تمہارا چہرہ}\n22۔ جلدی کرو، وہاں سے فرار ہو جاؤ؛ کیونکہ میں کچھ نہیں کر سکتا جب تک تم وہاں نہ آؤ۔ اسی لیے شہر کا نام زوار رکھا گیا۔ {زوار: یعنی، لٹل}\n23۔ جب لوط زوآر میں داخل ہوا تو سورج زمین پر طلوع ہوا۔ {اٹھنا: عبرانی۔ آگے بڑھا}\n24۔ پھر خداوند نے سدوم اور عمورہ پر گندھک اور آسمان سے خداوند کی آگ برسایا؛\n25۔ اور اس نے ان شہروں، تمام میدانوں، اور شہروں کے تمام باشندے، اور جو زمین پر اگ رہا تھا اسے گرا دیا۔\n26۔ لیکن اس کی بیوی نے پیچھے مڑ کر دیکھا، اور وہ نمک کا ستون بن گئی۔\n27۔ اور ابراہیم صبح سویرے اس جگہ پہنچا جہاں وہ خداوند کے سامنے کھڑا تھا:\n28۔ اور اس نے سدوم اور عمورہ کی طرف دیکھا، اور میدان کی پوری زمین کی طرف دیکھا، اور دیکھا، اور دیہات کا دھواں بھٹی کے دھوئیں کی طرح اٹھا۔\n29۔ اور ایسا ہوا جب خدا نے میدان کے شہروں کو تباہ کیا، تو خدا نے ابراہیم کو یاد کیا، اور لوط کو تختی کے بیچ سے نکال دیا، جب اس نے ان شہروں کو گرا دیا جہاں لوط رہتا تھا۔\n30۔ اور لوط زوار سے اوپر چلا گیا، اور پہاڑ میں رہا، اور اس کی دو بیٹیاں اس کے ساتھ تھیں؛ کیونکہ وہ زوار میں رہنے سے ڈرتا تھا: اور وہ ایک غار میں رہتا تھا، وہ اور اس کی دو بیٹیاں۔\n31۔ اور سب سے بڑے نے چھوٹے سے کہا، ہمارا باپ بوڑھا ہے، اور زمین پر کوئی انسان نہیں جو زمین کی طرح ہمارے پاس آئے:\n32۔ آؤ، آؤ اپنے باپ کو شراب پلائے، اور ہم اس کے ساتھ لیٹیں گے، تاکہ اپنے باپ کی اولاد کو محفوظ رکھ سکیں۔\n33۔ اور انہوں نے اس رات اپنے والد کو شراب پلائی: اور پہلا بیٹا اندر گیا، اور اپنے والد کے ساتھ سو گیا؛ اور اس نے محسوس نہیں کیا کہ وہ کب لیٹ گئی، نہ کب اٹھی۔\n34۔ اور کل ایسا ہوا کہ سب سے بڑے بچے نے چھوٹے سے کہا، دیکھو، میں نے کل رات اپنے والد کے ساتھ رات گزاری: آؤ آج رات اسے بھی شراب پلا دیں؛ اور تم اندر جاؤ، {اور} اس کے ساتھ سو جاؤ، تاکہ ہم اپنے باپ کی نسل کو محفوظ رکھ سکیں۔\n35۔ اور انہوں نے اسی رات اپنے والد کو بھی شراب پلائی: اور چھوٹا اٹھا اور اس کے ساتھ لیٹ گیا؛ اور اس نے محسوس نہیں کیا کہ وہ کب لیٹ گئی، نہ کب اٹھی۔\nیوں لوط کی دونوں بیٹیاں اپنے والد سے حاملہ ہوئیں۔\n37۔ اور سب سے بڑے بچے نے بیٹا پیدا کیا، اور اس کا نام موآب رکھا: وہی آج تک موآبیوں کا باپ ہے۔\n38۔ اور چھوٹی لڑکی نے بھی ایک بیٹا پیدا کیا، اور اس کا نام بنامی رکھا: وہی آج بھی آمون کے بچوں کا باپ ہے۔","1۔ اور ابراہیم وہاں سے جنوبی علاقے کی طرف روانہ ہوا، قادیش اور شور کے درمیان رہا، اور جرار میں قیام کیا۔\n2۔ اور ابراہیم نے اپنی بیوی سارہ کے بارے میں کہا، وہ میری بہن ہے: اور جرار کے ابیمیلک بادشاہ نے بھیجا اور سارہ کو لے لیا۔\n3۔ لیکن خدا رات کے خواب میں ابیمیلک کے پاس آیا، اور اس سے کہا، دیکھو، تم صرف ایک مردہ آدمی ہو، اس عورت کے لیے جسے تم نے لیا ہے؛ کیونکہ وہ ایک مرد کی بیوی ہے۔ {ایک آدمی...: عبرانی۔ شوہر سے شادی شدہ}\n4۔ لیکن ابیملک اس کے قریب نہیں آیا: اور اس نے کہا، اے خداوند، کیا تو ایک نیک قوم کو بھی قتل کرو گے؟\n5. اس نے مجھ سے نہیں کہا، وہ میری بہن ہے؟ اور اس نے خود کہا، وہ میرا بھائی ہے: میں نے اپنے دل کی دیانتداری اور ہاتھوں کی معصومیت میں یہ کیا ہے۔ {دیانتداری: یا، سادگی، یا، خلوص}\n6۔ اور خدا نے اسے خواب میں کہا، ہاں، میں جانتا ہوں کہ تم نے یہ اپنے دل کی سچائی میں کیا؛ کیونکہ میں نے تمہیں اپنے خلاف گناہ کرنے سے بھی روکا: اس لیے میں نے تمہیں اسے چھونے سے منع کیا۔\n7۔ اب اس مرد کی بیوی کو بحال کرو؛ کیونکہ وہ ایک نبی ہے، اور وہ تمہارے لیے دعا کرے گا، اور تم زندہ رہو گے: اور اگر تم اسے واپس نہ دو تو جان لو کہ تم ضرور مر جاؤ گے، تم، اور جو کچھ تمہارا ہے۔\n8۔ اسی لیے ابیمیلک صبح سویرے اٹھا، اپنے تمام خادموں کو بلایا، اور یہ سب باتیں ان کے کانوں میں سنائی: اور لوگ شدید خوفزدہ ہو گئے۔\n9۔ پھر ابیمیلک نے ابراہیم کو بلایا اور اس سے کہا، تم نے ہمارے ساتھ کیا کیا ہے؟ اور میں نے تمہیں کیا ناراض کیا ہے کہ تم نے میرے اور میری سلطنت پر بڑا گناہ لایا ہے؟ تم نے میرے ساتھ ایسے کام کیے ہیں جو نہیں ہونے چاہئیں۔\n10۔ اور ابیمیلک نے ابراہیم سے کہا، تم نے کیا کہا کہ تم نے یہ کام کیا ہے؟\n11۔ اور ابراہیم نے کہا، کیونکہ میں نے سوچا، یقینا خدا کا خوف اس جگہ پر نہیں ہے؛ اور وہ میری بیوی کے لیے مجھے مار ڈالیں گے۔\n12۔ اور پھر بھی وہ واقعی میری بہن ہے؛ وہ میرے والد کی بیٹی ہے، لیکن میری ماں کی بیٹی نہیں؛ اور وہ میری بیوی بن گئی۔\n13۔ اور جب خدا نے مجھے میرے والد کے گھر سے بھٹکایا، تو میں نے اس سے کہا، یہ تمہاری مہربانی ہے جو تم مجھے دکھاؤ گی؛ جہاں بھی ہم آئیں گے، میرے بارے میں کہو، وہ میرا بھائی ہے۔\n14۔ اور ابیمیلک نے بھیڑیں، بیل، نوکر اور عورتیں لے کر ابراہیم کو دے دیے، اور اسے اپنی بیوی سارہ واپس کر دیا۔\n15۔ اور ابیمیلک نے کہا، دیکھو، میری زمین تمہارے سامنے ہے: جہاں چاہو رہو۔ {کہاں...: عبرانی۔ جیسا کہ تمہاری آنکھوں میں اچھا ہے}\n16۔ اور سارہ سے کہا، دیکھو، میں نے تمہارے بھائی کو ایک ہزار چاندی کے ٹکڑے دیے ہیں، دیکھو، وہ تمہارے لیے آنکھوں کا پردہ ہے، سب کے لیے جو تمہارے ساتھ ہیں، اور سب کے لیے: یوں وہ ملامت کی گئی۔\n17۔ تو ابراہیم نے خدا سے دعا کی: اور خدا نے ابیملک، اس کی بیوی اور اس کی نوکرانیوں کو شفا دی؛ اور ان کے ہاں {بچے} ہوئے۔\n18۔ کیونکہ خداوند نے سارہ ابراہیم کی بیوی کی وجہ سے ابیملک کے گھر کے تمام رحم بند کر دیے تھے۔","1۔ اور خداوند نے سارہ سے ملاقات کی جیسا کہ اس نے کہا تھا، اور خداوند نے سارہ کے ساتھ ویسا ہی کیا جیسا اس نے کہا تھا۔\n2۔ کیونکہ سارہ نے ابراہیم کو اس وقت پیدا کیا اور اس کی بڑھاپے میں بیٹا پیدا ہوا، جس وقت خدا نے اس سے بات کی تھی۔\n3۔ اور ابراہیم نے اپنے بیٹے کا نام پکارا، جو اس سے پیدا ہوا تھا، جسے سارہ نے اس سے جنم دیا، اسحاق کہا۔\n4۔ اور ابراہیم نے اپنے بیٹے اسحاق کو آٹھ دن کی عمر میں ختنہ کر دیا، جیسا کہ خدا نے حکم دیا تھا۔\n5۔ اور ابراہیم سو سال کا تھا، جب اس کا بیٹا اسحاق پیدا ہوا۔\n6۔ اور سارہ نے کہا، خدا نے مجھے ہنسایا ہے، {تاکہ} جو بھی سنتا ہے وہ میرے ساتھ ہنسے۔\n7۔ اور اس نے کہا، کون نے ابراہیم سے کہا ہوگا کہ سارہ کو بچوں کو برا دینا چاہیے تھا؟ کیونکہ میں نے اس کی بڑھاپے میں ایک بیٹا پیدا کیا ہے۔\n8۔ اور بچہ بڑا ہوا اور دودھ چھڑایا گیا: اور ابراہیم نے اسی دن بڑی دعوت دی جب اسحاق دودھ چھڑایا گیا۔\n9۔ اور سارہ نے ہاجر، مصری کے بیٹے کو، جو اس نے ابراہیم سے پیدا کیا تھا، مذاق اڑاتے ہوئے دیکھا۔\n10۔ اسی لیے اس نے ابراہیم سے کہا، اس خادمہ اور اس کے بیٹے کو نکال دو، کیونکہ اس خادمہ کا بیٹا میرے بیٹے کا وارث نہیں ہوگا، {حتیٰ کہ} اسحاق سے۔\n11۔ اور یہ واقعہ ابراہیم کی نظر میں اس کے بیٹے کی وجہ سے بہت خوفناک تھا۔\n12۔ اور خدا نے ابراہیم سے کہا، یہ تمہارے سامنے اس لڑکے اور تمہاری خادمہ کی وجہ سے تکلیف دہ نہ ہو؛ سارہ نے جو کچھ تم سے کہا ہے، اس کی آواز سنو؛ کیونکہ تمہاری نسل اسحاق میں پکارا جائے گا۔\n13۔ اور خادمہ کے بیٹے کا بھی میں ایک قوم بناؤں گا، کیونکہ وہ تمہاری نسل ہے۔\n14۔ اور ابراہیم صبح سویرے اٹھا، روٹی اور پانی کی بوتل لی، اور ہاجرہ کو دی، اس کے کندھے اور بچے پر ڈال کر اسے بھیج دیا، اور وہ چلی گئی، اور بیر السبع کے بیابان میں بھٹک گئی۔\n15۔ اور پانی بوتل میں ڈال دیا گیا، اور اس نے بچے کو ایک جھاڑی کے نیچے پھینک دیا۔\n16۔ اور وہ گئی، اور اسے اس کے ساتھ کافی دور بٹھا دیا، جیسے تیر کمان ہو: کیونکہ اس نے کہا، مجھے بچے کی موت نہ دیکھنے دو۔ اور وہ {اس سے} کے ساتھ بیٹھ گئی، اپنی آواز بلند کی، اور رونے لگی۔\n17۔ اور خدا نے لڑکے کی آواز سنی؛ اور خدا کے فرشتے نے ہاجرہ کو آسمان سے بلایا اور کہا، ہاجر، تمہیں کیا ہو گیا ہے؟ ڈر نہیں؛ کیونکہ خدا نے اس لڑکے کی آواز سنی ہے جہاں وہ {ہے}۔\nاٹھو۔ اٹھو، لڑکے کو اٹھاؤ، اور اسے اپنے ہاتھ میں پکڑو؛ کیونکہ میں اسے ایک عظیم قوم بناؤں گا۔\n19۔ اور خدا نے اس کی آنکھیں کھولیں، اور اس نے پانی کا کنواں دیکھا؛ اور وہ گئی، بوتل پانی سے بھر دی، اور لڑکے کو پانی دیا۔\n20۔ اور خدا لڑکے کے ساتھ تھا؛ اور وہ بڑا ہوا، اور جنگل میں رہا، اور تیر انداز بن گیا۔\n21۔ اور وہ پران کے ویرانے میں رہا: اور اس کی ماں نے اسے مصر کی سرزمین سے ایک بیوی لے لی۔\n22۔ اور اسی وقت ہوا کہ ابیمیلک اور اس کے لشکر کے سردار فیشول نے ابراہیم سے بات کی، کہا کہ خدا تمہارے ساتھ ہے جو کچھ بھی تم کرتے ہو:\n23۔ اب خدا کی قسم کھاؤ کہ تم مجھ سے، میرے بیٹے کے ساتھ، اور میرے بیٹے کے بیٹے کے ساتھ جھوٹ نہیں سمجھے گے: {لیکن} جو مہربانی میں نے تمہارے ساتھ کی ہے، اس کے مطابق تم میرے ساتھ اور اس زمین کے ساتھ کرو گے جہاں تم ٹھہرے ہو۔ {کہ تم...: عبرانی۔ اگر تم مجھ سے جھوٹ بولو گے}\n24۔ اور ابراہیم نے کہا، میں قسم کھاتا ہوں۔\n25۔ اور ابراہیم نے ابیملک کو ایک پانی کے کنویں کی وجہ سے سرزنش کی، جسے ابیملک کے خادموں نے زبردستی لے لیا تھا۔\n26۔ اور ابیملک نے کہا، میں نہیں جانتا تھا کہ یہ کام کس نے کیا ہے: نہ تم نے مجھے بتایا، نہ میں نے ابھی تک سنا، سوائے آج کے۔\n27۔ اور ابراہیم نے بھیڑ اور بیل لے کر ابیملک کو دے دیے؛ اور دونوں نے ایک عہد کیا۔\n28۔ اور ابراہیم نے ریوڑ کے سات بھیڑوں کو اکیلا رکھا۔\n29۔ اور ابیمیلک نے ابراہیم سے کہا، یہ سات بھیڑیں جو تم نے خود رکھی ہیں، ان کا کیا مطلب ہے؟\n30۔ اور اس نے کہا، کیونکہ یہ سات بھیڑیں میرے ہاتھ سے لے لو تاکہ وہ میرے سامنے گواہ بن سکیں کہ میں نے یہ کنواں کھودا ہے۔\n31۔ اسی لیے اس نے اس جگہ کا نام بیئر شیبع رکھا؛ کیونکہ وہاں وہ دونوں کو قسم کھاتے ہیں۔ {بیر شیبع: یعنی، قسم کا کنوا}\n32۔ یوں انہوں نے بیر شبع میں ایک عہد کیا: پھر ابیملک اٹھا، اور فیخول نے اپنی فوج کا سردار سردار بنایا، اور وہ فلسطینیوں کی سرزمین میں واپس چلے گئے۔\n33۔ اور {ابراہیم} نے بیر سبع میں ایک جنگل لگایا، اور وہاں خداوند کے نام پر پکارا، جو ابدی خدا ہے۔ {گروو: یا، درخت}\n34۔ اور ابراہیم نے کئی دن فلسطینیوں کی سرزمین میں قیام کیا۔","1۔ اور ان واقعات کے بعد ہوا کہ خدا نے ابراہیم کو آزمایا اور اسے کہا، ابراہیم: اور اس نے کہا، دیکھو، {یہاں} میں {ہوں}۔ {دیکھو...: عبرانی۔ دیکھو مجھے}\n2۔ اور اس نے کہا، اب اپنے بیٹے کو، اپنا واحد بیٹا اسحاق لے جاؤ، جس سے تم محبت کرتے ہو، اور موریاہ کی سرزمین میں لے جاؤ؛ اور اسے وہاں ایک پہاڑ پر جلانے کی قربانی کے طور پر پیش کرو جس کے بارے میں میں تمہیں بتاؤں گا۔\n3۔ اور ابراہیم صبح سویرے اٹھ کھڑا ہوا، اپنی گدھے پر زین باندھ لیا، اور اپنے دو نوجوانوں اور اسحاق کو اپنے بیٹے کے ساتھ لے گیا، اور لکڑی کو جلانے کی قربانی کے لیے تیار کیا، اور اٹھا اور اس جگہ چلا گیا جس کے بارے میں خدا نے اسے بتایا تھا۔\n4۔ پھر تیسرے دن ابراہیم نے اپنی آنکھیں اٹھائیں اور دور کی جگہ دیکھی۔\n5۔ اور ابراہیم نے اپنے نوجوانوں سے کہا، تم یہاں گدھے کے ساتھ رہو؛ اور میں اور لڑکا وہاں جائیں گے، عبادت کریں گے، اور پھر تمہارے پاس آئیں گے۔\n6۔ اور ابراہیم نے سلائی ہوئی قربانی کی لکڑی لی اور اسے اپنے بیٹے اسحاق پر رکھا؛ اور اس نے آگ اپنے ہاتھ میں لی، اور ایک چھری؛ اور وہ دونوں ایک ساتھ گئے۔\n7۔ اور اسحاق نے اپنے والد ابراہیم سے بات کی اور کہا، میرے والد، اور اس نے کہا، میں یہاں ہوں، میرا بیٹا۔ اور اس نے کہا، دیکھو آگ اور لکڑی: لیکن وہ برہ کہاں ہے جو جلنے کی قربانی کے لیے ہے؟ {لیمب: یا، بچے}\n8۔ اور ابراہیم نے کہا، میرے بیٹے، خدا اپنے لیے ایک بکرا بکری سلانے کی قربانی دے گا: تو وہ دونوں ساتھ چلے گئے۔\n9۔ اور وہ اس جگہ پہنچے جس کے بارے میں خدا نے اسے بتایا تھا؛ اور ابراہیم نے وہاں ایک قربان گاہ بنائی، لکڑی کو ترتیب دیا، اور اپنے بیٹے اسحاق کو باندھ کر لکڑی پر قربان گاہ پر لٹایا۔\n10۔ اور ابراہیم نے اپنا ہاتھ بڑھایا، اور چاقو لے کر اپنے بیٹے کو قتل کرنے لگا۔\n11۔ اور خداوند کے فرشتے نے اسے آسمان سے پکارا اور کہا، ابراہیم، ابراہیم، اور کہا، میں یہاں ہوں۔\n12۔ اور اس نے کہا، اپنا ہاتھ لڑکے پر نہ رکھو، نہ ہی اس کے ساتھ کچھ کرو، کیونکہ اب میں جانتا ہوں کہ تم خدا سے ڈرتے ہو، کیونکہ تم نے اپنے بیٹے کو مجھ سے نہیں روکا۔\n13۔ اور ابراہیم نے اپنی آنکھیں اٹھائیں، اور دیکھا کہ اس کے پیچھے ایک مینڈھا جھاڑی میں اس کے سینگوں سے پھنس گیا تھا، اور ابراہیم جا کر مینڈھا لے کر اپنے بیٹے کی جگہ اسے جلانے کی قربانی کے طور پر پیش کیا۔\n14۔ اور ابراہیم نے اس جگہ کا نام یہوواہجیرہ پکارا: جیسا کہ آج کہا جاتا ہے، خداوند کے پہاڑ میں یہ دیکھا جائے گا۔ {یہوواہ جیریہ: یعنی، خداوند دیکھے گا، یا فراہم کرے گا}\n15۔ اور خداوند کے فرشتے نے ابراہیم کو دوسری بار آسمان سے بلایا،\n16۔ اور کہا، میں نے خود قسم کھائی ہے، خداوند فرماتا ہے، کیونکہ تو نے یہ کام کیا، اور اپنے بیٹے کو نہیں روکا، صرف تمہارا {بیٹا}:\n17۔ کہ برکت میں میں تمہیں برکت دوں گا، اور بڑھتے ہوئے میں تمہاری نسل کو آسمان کے ستاروں کی طرح بڑھاؤں گا، اور سمندر کے کنارے پر موجود ریت کی طرح؛ اور تمہاری نسل اس کے دشمنوں کے دروازے پر قبضہ کرے گی؛ {شور: عبرانی لپ}\n18۔ اور تیری نسل میں زمین کی تمام قومیں بابرکت ہوں گی؛ کیونکہ تم نے میری آواز مانی۔\n19۔ تو ابراہیم اپنے نوجوانوں کے پاس واپس آیا، اور وہ اٹھے اور مل کر بیر شبع چلے گئے؛ اور ابراہیم بئر شبع میں رہتا تھا۔\n20۔ اور ان باتوں کے بعد ابراہیم کو بتایا گیا، کہ دیکھو، ملکاہ، اس نے بھی تمہارے بھائی ناہور سے بچے پیدا کیے ہیں؛\n21۔ ہوز اس کا پہلا بیٹا، بز اس کا بھائی، اور کیموئیل آرام کا والد،\n22۔ اور چیسد، اور ہازو، اور پیلداش، اور جدلاف، اور بیتھوئیل۔\n23۔ اور بیت ویل نے ربیکا کو جنم دیا: یہ آٹھ ملکا ناحور، ابراہیم کے بھائی کو پیدا ہوئے۔ {ربیکا: گریڈ ربیکا}\n24۔ اور اس کی کنیز، جس کا نام {تھا} رومہ تھا، اس نے بھی تیبہ، گاہم، تہاش، اور معچہ کو جنم دیا۔","1۔ اور سارہ کی عمر ایک سو ستائیس بیس سال تھی: {یہ} سارہ کی زندگی کے سال تھے۔\n2۔ اور سارہ کرجاتھربا میں وفات پا گئی؛ وہی {ہے} ہیبرون ہے کنعان کی سرزمین میں: اور ابراہیم آیا تاکہ سارہ کے لیے سوگ منائے، اور اس کے لیے رونے لگا۔\n3۔ اور ابراہیم اپنے مردوں کے سامنے کھڑا ہوا اور ہیت کے بیٹوں سے کہا،\n4. میں تمہارے ساتھ اجنبی اور ایک مسافر ہوں: مجھے تمہارے ساتھ ایک دفن گاہ کی ملکیت دو، تاکہ میں اپنے مردوں کو اپنی نظر سے دور دفن کر سکوں۔\n5۔ اور ہیت کے بچوں نے ابراہیم کو جواب دیا، اس سے کہا،\n6. ہماری بات سنو، میرے رب: تو ہمارے درمیان ایک طاقتور شہزادہ ہو: ہماری قبروں کے انتخاب میں تمہارے مردوں کو دفناؤ؛ ہم میں سے کوئی بھی تم سے اس کی قبر نہیں چھپائے گا، سوائے اس کے کہ تم اپنے مردوں کو دفن کر سکو۔ {ایک زبردست...: عبرانی۔ خدا کا شہزادہ}\n7۔ اور ابراہیم کھڑا ہوا، اور زمین کے لوگوں کے سامنے سجدہ کیا، {حتیٰ کہ} ہیت کے بچوں کے سامنے بھی۔\n8۔ اور اس نے ان سے رابطہ کیا، کہا، اگر آپ کا خیال ہے کہ میں اپنے مردوں کو اپنی نظر سے دور دفن کر دوں؛ میری بات سنو، اور میرے لیے زوہار کے بیٹے ایفرون سے دعا کرو،\n9۔ تاکہ وہ مجھے وہ غار دے جو اس کے پاس ہے، جو اس کے میدان کے آخر میں ہے؛ جتنی رقم اس کی قیمت ہو، وہ مجھے دے گا تاکہ میں تم سب کے درمیان ایک دفن جگہ بنا سکوں۔ {اتنا ہی...: عبرانی۔ مکمل پیسہ}\n10۔ اور ایفرون ہیت کے بچوں کے درمیان رہتا تھا: اور ایفرون دی ہٹی نے ابراہیم کو ہیت کے بچوں کے سامعین میں جواب دیا، {حتیٰ کہ} ان سب میں سے جو اس کے شہر کے دروازے سے داخل ہوتے تھے، اور کہا، {سامعین: عبرانی۔ کان}\n11۔ نہیں، میرے رب، میری بات سنو: میدان میں تمہیں دیتا ہوں، اور وہ غار جو وہاں ہے، میں تمہیں دیتا ہوں؛ میرے لوگوں کے بیٹوں کی موجودگی میں میں تمہیں دوں: اپنے مردوں کو دفناؤ۔\n12۔ اور ابراہیم نے زمین کے لوگوں کے سامنے سر جھکایا۔\n13۔ اور اس نے ایفرون سے اس سرزمین کے لوگوں کے سامعین میں کہا، لیکن اگر تم دے دو گے، تو میں تم سے دعا کرتا ہوں، میری بات سنو: میں تمہیں کھیت کے لیے پیسے دوں گا؛ مجھے لے لو، اور میں اپنے مردوں کو وہاں دفن کر دوں گا۔\n14۔ اور ایفرون نے ابراہیم کو جواب دیا، اس سے کہا،\n15۔ میرے آقا، میری بات سنو: زمین چار سو شیکل چاندی کے برابر ہے؛ وہ کیا ہے جو میرے اور تمہارے درمیان ہے؟ لہٰذا اپنے مردوں کو دفن کرو۔\n16۔ اور ابراہیم نے ایفرون کی بات مانی؛ اور ابراہیم نے ایفرون کے سامنے چاندی کا وزن کیا، جسے اس نے ہیتھ کے بیٹوں کی ملاقات میں چار سو شیکل چاندی کے برابر رکھا تھا، تاجر کے پاس موجودہ {پیسے}۔\n17. اور ایفرون کا میدان، جو {تھا} مکپیلہ میں، جو {تھا} مامرہ سے پہلے، وہ میدان، اور غار جو {تھا} میں، اور وہ تمام درخت جو {تھے} میدان میں، جو {تھے} ارد گرد کی تمام سرحدوں پر، یقینی بنائے گئے\n18۔ ابراہیم کے پاس ہیتھ کے بچوں کی موجودگی میں ایک ملکیت کے لیے، اس سے پہلے کہ اس کے شہر کے دروازے پر سب کچھ اندر آئے۔\n19۔ اور اس کے بعد، ابراہیم نے اپنی بیوی سارہ کو ممر کے سامنے مکھپلہ کے میدان کی غار میں دفن کیا: وہی {ہے} ہبرون ہے کنعان کی سرزمین میں۔\n20۔ اور وہ کھیت اور وہ غار جو {ہے} ابراہیم کو ہیتھ کے بیٹوں نے دفن کی جگہ کے لیے یقینی بنایا۔","1۔ اور ابراہیم بوڑھا تھا، {اور} بوڑھا ہو چکا تھا: اور خداوند نے ابراہیم کو ہر چیز میں برکت دی تھی۔ {اچھا...: عبوری۔ دنوں میں چلے گئے}\n2۔ اور ابراہیم نے اپنے خاندان کے سب سے بڑے خادم سے کہا، جو اس کی تمام مالکوں پر حکمرانی کرتا تھا، میں تم سے دعا کرتا ہوں کہ اپنا ہاتھ میری ران کے نیچے رکھو:\n3۔ اور میں تم سے وعدہ کروں گا، خداوند کے نام سے، جو آسمان کا خدا ہے، اور زمین کے خدا، کہ تم کنعانیوں کی بیٹیوں میں سے میرے بیٹے سے بیوی نہ لو، جن میں میں رہتا ہوں:\n4۔ لیکن تم میرے ملک اور میرے رشتہ داروں کے پاس جاؤ گے، اور میرے بیٹے اسحاق سے شادی کر لو گے۔\n5۔ اور خادم نے اس سے کہا، شاید وہ عورت میرے ساتھ اس سرزمین پر جانے کو تیار نہ ہو: کیا مجھے تمہارے بیٹے کو اس زمین پر واپس لانا پڑے گا جہاں سے تم آئے ہو؟\n6۔ اور ابراہیم نے اسے کہا، خبردار ہو کہ تم میرے بیٹے کو دوبارہ وہاں نہ لے آؤ۔\n7۔ آسمانوں کے خداوند خدا، جس نے مجھے میرے باپ کے گھر اور میرے رشتہ داروں کی زمین سے لیا، اور جس نے مجھ سے بات کی، اور مجھ سے قسم کھائی کہ میں یہ زمین تیری نسل کو دوں گا؛ وہ اپنا فرشتہ تمہارے سامنے بھیجے گا، اور تم وہاں سے میرے بیٹے کی بیوی لو گے۔\n8۔ اور اگر وہ عورت تمہاری پیروی کرنے کو تیار نہیں، تو تم اس قسم سے واضح ہو جاؤ گے: بس میرے بیٹے کو دوبارہ وہاں نہ لانا۔\n9۔ اور خادم نے اپنے مالک ابراہیم کی ران کے نیچے ہاتھ رکھا اور اس معاملے پر اس سے قسم کھائی۔\n10۔ اور خادم نے اپنے مالک کے اونٹوں کے دس اونٹ لیے اور روانہ ہو گیا؛ کیونکہ اس کے مالک کی تمام اشیاء اس کے ہاتھ میں تھیں: اور وہ اٹھا، اور میسوپوٹیمیا چلا گیا، ناحور شہر کی طرف۔ {for: or, and}\n11۔ اور اس نے اپنے اونٹوں کو شہر کے بغیر پانی کے کنویں کے پاس شام کے وقت گھٹنے ٹیکنے پر مجبور کیا، {حتیٰ کہ} جب عورتیں پانی نکالنے جاتی ہیں۔ {وہ...: عببرانی۔ کہ جو عورتیں پانی کھینچتی ہیں آگے بڑھتی ہیں}\n12۔ اور اس نے کہا، اے خداوند میرے آقا ابراہیم کے، میں دعا کرتا ہوں کہ آج مجھے اچھی جلدی بھیج اور میرے آقا ابراہیم پر مہربانی فرما۔\n13۔ دیکھو، میں یہاں پانی کے کنویں کے پاس کھڑا ہوں؛ اور شہر کے مردوں کی بیٹیاں پانی لینے باہر آتی ہیں:\n14۔ اور یہ ہو جائے کہ وہ لڑکی جسے میں کہوں گا، اپنا جگ نیچے رکھو، میں تم سے دعا کرتا ہوں، تاکہ میں پی سکوں؛ اور وہ کہے گی، پیو، اور میں تمہارے اونٹوں کو بھی پانی دوں گی: {وہی ہو} جو تم نے اپنے خادم اسحاق کے لیے مقرر کی ہے؛ اور اس طرح مجھے معلوم ہوگا کہ تم نے میرے آقا کے ساتھ مہربانی کی ہے۔\n15۔ اور ایسا ہوا، اس سے پہلے کہ وہ بول چکا تھا، کہ دیکھو، ربیکا باہر آئی، جو بیتھوئیل سے پیدا ہوئی، ملکہ کا بیٹا، ناہور کی بیوی تھا، ابراہیم کے بھائی کی بیوی تھی، اور اس کے کندھے پر جگ تھا۔\n16۔ اور وہ دوشیزہ دیکھنے میں بہت خوبصورت تھی، ایک کنواری، نہ ہی کوئی مرد اسے جانتا تھا: اور وہ کنویں پر گئی، اپنا جگ بھر کر اوپر آئی۔ {بہت...: عبرانی خوش آمدید}\n17۔ اور خادم اس سے ملنے دوڑا اور کہا، میں، میں تم سے درخواست کرتا ہوں، تمہارے جگ کا تھوڑا سا پانی پی لوں۔\n18۔ اور اس نے کہا، پی لو، میرے آقا، اور وہ جلدی سے گئی، اپنا جگ اپنے ہاتھ پر رکھ دیا، اور اسے پانی دیا۔\n19۔ اور جب اس نے اسے پانی دے دیا، تو کہا، میں تمہارے اونٹوں کے لیے بھی پانی نکالوں گی، جب تک وہ پی نہ لیں۔\n20۔ اور وہ جلدی سے گئی، اپنا جگ نالی میں خالی کیا، اور دوبارہ کنویں کی طرف دوڑی تاکہ {پانی} لے سکے، اور اس کے تمام اونٹوں کے لیے پانی نکالا۔\n21۔ اور وہ آدمی جو اس پر حیران تھا، خاموش رہا، یعنی کہ آیا خداوند نے اس کا سفر خوشحال بنایا ہے یا نہیں۔\n22۔ اور جب اونٹوں نے شراب پی لی تھی، تو اس آدمی نے اس کے ہاتھوں کے لیے دس شیکل سونے کے دو کنگن لے لیے؛ {بالی: یا، ماتھے کے لیے جواہرات}\n23۔ اور کہا، تم کس کی بیٹی ہو؟ بتاؤ، میں تم سے دعا کرتا ہوں: کیا تمہارے والد کے گھر میں ہمارے قیام کے لیے جگہ ہے؟\n24۔ اور اس نے اس سے کہا، میں بیت ویل ملکہ کے بیٹے کی بیٹی ہوں، جسے اس نے ناحور کو جنم دیا۔\n25۔ اس نے اس سے مزید کہا، ہمارے پاس تنکے اور ثبوت دونوں کافی ہیں، اور رہنے کی جگہ بھی ہے۔\n26۔ اور وہ آدمی سر جھکا کر خداوند کی عبادت کرنے لگا۔\n27۔ اور اس نے کہا، مبارک ہو میرے آقا ابراہیم کے خداوند خدا، جس نے میرے آقا کو اس کی رحمت اور سچائی سے محروم نہیں چھوڑا: میں راستے میں ہوں، خداوند نے مجھے میرے آقا کے بھائیوں کے گھر لے گیا۔\n28۔ اور دوشیزہ بھاگ گئی، اور انہیں اپنی ماں کے گھر کے بارے میں یہ سب بتایا۔\n29۔ اور ربیکا کا ایک بھائی تھا، جس کا نام لابان تھا: اور لابان اس آدمی کی طرف دوڑا، کنویں کی طرف۔\n30۔ اور یہ اس وقت ہوا جب اس نے اپنی بہن کے ہاتھوں میں بالی اور کنگن دیکھے، اور جب اس نے اپنی بہن ربیکا کے الفاظ سنے، جو کہہ رہی تھیں، اس نے مجھ سے کہا؛ کہ وہ اس آدمی کے پاس آیا؛ اور دیکھو، وہ کنویں کے پاس اونٹوں کے پاس کھڑا تھا۔\n31۔ اور اس نے کہا، آؤ، اے خداوند کی برکت یافتہ؛ تم باہر کیوں کھڑے ہو؟ کیونکہ میں نے اونٹوں کے لیے گھر اور جگہ تیار کر دی ہے۔\n32۔ اور وہ آدمی گھر میں آیا، اور اس نے اپنے اونٹوں کو سنہا کیا، اونٹوں کے لیے تنکا اور سامان دیا، اور اپنے پاؤں دھونے کے لیے پانی دیا، اور ان لوگوں کے پاؤں جو اس کے ساتھ تھے۔\n33۔ اور اس کے سامنے کھانے کے لیے گوشت رکھا گیا تھا، لیکن اس نے کہا، میں نہیں کھاؤں گا جب تک اپنا کام نہ بتا دوں۔ اور انہوں نے کہا، بات کریں۔\n34۔ اور اس نے کہا، میں ابراہیم کا خادم ہوں۔\n35۔ اور خداوند نے میرے آقا کو بہت برکت دی ہے؛ اور وہ بڑا ہو گیا ہے: اور اس نے اسے ریوڑ، ریوڑ، چاندی، سونا، نوکر، خادم، اونٹ اور گدھے دیے ہیں۔\n36۔ اور سارہ میرے آقا کی بیوی نے بوڑھی ہو کر میرے آقا سے بیٹا پیدا کیا: اور اس نے جو کچھ بھی اس کے پاس تھا اسے دے دیا۔\n37۔ اور میرے آقا نے مجھ سے قسم لی، کہا کہ تم کنعانیوں کی بیٹیوں میں سے میرے بیٹے سے بیوی نہ لو، جن کی سرزمین میں میں رہتا ہوں:\n38۔ لیکن تم میرے والد کے گھر جاؤ گے، اور میرے رشتہ داروں کے پاس جاؤ گے، اور میرے بیٹے کی بیوی لے لو گے۔\n39۔ اور میں نے اپنے آقا سے کہا، شاید وہ عورت میرے پیچھے نہ آئے۔\n40۔ اور اس نے مجھ سے کہا، خداوند جس کے سامنے میں چلتا ہوں، وہ اپنا فرشتہ تیرے ساتھ بھیجے گا اور تیری راہ کو کامیاب کرے گا؛ اور تم میرے رشتہ داروں اور میرے والد کے گھر کے بیٹے کے لیے بیوی لو گے:\n41۔ تو جب تم میرے رشتہ داروں کے پاس آؤ تو میری {یہ} قسم سے صاف ہو جانا؛ اور اگر وہ تمہیں {ایک} نہ دیں، تو تم میری قسم سے صاف ہو جاؤ گے۔\n42۔ اور میں آج کنویں پر آیا اور کہا، اے خداوند میرے آقا ابراہیم کے خدا، اگر اب تو میری راہ کو کامیاب کرو جس پر میں جا رہا ہوں:\n43۔ دیکھو، میں پانی کے کنویں کے پاس کھڑا ہوں؛ اور ایسا ہوگا کہ جب کنواری باہر آئے گی {پانی} نکالنے کے لیے، اور میں اس سے کہوں، مجھے اپنے جگ کا تھوڑا سا پانی دے دو، میں تم سے دعا کرتا ہوں؛\n44۔ اور وہ مجھ سے کہتی ہے، دونوں پی لو، اور میں بھی تمہارے اونٹوں کے لیے کھینچوں گا: {وہی} وہ عورت ہو جسے خداوند نے میرے آقا کے بیٹے کے لیے مقرر کیا ہے۔\n45۔ اور اس سے پہلے کہ میں اپنے دل میں بات کرتا، دیکھتا، ربیقہ اپنے کندھے پر جگ لیے باہر آئی؛ اور وہ کنویں پر گئی، اور پانی نکالا: اور میں نے اس سے کہا، مجھے پینے دو، میں دعا کرتا ہوں۔\n46۔ اور اس نے جلدی کی، اپنا جگ اپنے کندھے سے اتارا، اور کہا، پی لو، اور میں تمہارے اونٹوں کو بھی پانی دوں گی: میں نے پیا، اور اس نے اونٹوں کو بھی پانی دیا۔\n47۔ اور میں نے اس سے پوچھا اور کہا، تم کس کی بیٹی ہو؟ اور اس نے کہا، ناحور کے بیٹے بیت وئیل کی بیٹی، جسے ملکہ نے اس کے حوالے کیا: اور میں نے اس کے چہرے پر بالی اور کنگن اس کے ہاتھوں میں ڈالے۔\n48۔ اور میں نے سر جھکایا، خداوند کی عبادت کی، اور اپنے آقا ابراہیم کے خداوند خدا کو برکت دی، جس نے مجھے اپنے آقا کے بھائی کی بیٹی کو اس کے بیٹے کے پاس لے جانے کے لیے صحیح راستہ دکھایا۔\n49۔ اور اب اگر تم میرے آقا کے ساتھ مہربانی اور سچائی سے پیش آؤ تو مجھے بتانا: اور اگر نہیں تو بتاؤ؛ تاکہ میں دائیں یا بائیں طرف مڑ سکوں۔\n50۔ پھر لابان اور بیت ویل نے جواب دیا اور کہا، یہ چیز خداوند سے نکلتی ہے: ہم تم سے برا یا اچھا نہیں کہہ سکتے۔\n51۔ دیکھو، ربیکا تمہارے سامنے ہے، اسے لے جاؤ اور چلی جا، اور اسے اپنے مالک کے بیٹے کی بیوی بنا دو، جیسا کہ خداوند نے فرمایا ہے۔\n52۔ اور ایسا ہوا کہ جب ابراہیم کے خادم نے ان کے الفاظ سنے، تو اس نے خداوند کی عبادت کی، {زمین کے سامنے جھک کر}۔\n53۔ اور نوکر نے چاندی کے جواہرات، سونے کے زیورات اور کپڑے نکالے، اور انہیں ربیکا کو دیا: اس نے اس کے بھائی اور اس کی ماں کو قیمتی چیزیں بھی دیں۔ {جیولز: عبوری۔ vessels}\n54۔ اور وہ واقعی کھاتے اور پیتے رہے، وہ اور وہ لوگ جو اس کے ساتھ تھے، اور ساری رات رکے رہے؛ اور وہ صبح اٹھے، اور اس نے کہا، مجھے میرے مالک کے پاس بھیج دو۔\n55۔ اور اس کے بھائی اور اس کی ماں نے کہا، دوشیزہ ہمارے ساتھ چند دن، کم از کم دس دن رہے؛ اس کے بعد وہ جائے گی۔ {چند...: یا، پورا سال، یا دس ماہ}\n56۔ اور اس نے ان سے کہا، مجھے روک نہ دو، کیونکہ خداوند نے میرے راستے کو ترقی دی ہے؛ مجھے بھیج دو تاکہ میں اپنے مالک کے پاس جا سکوں۔\n57۔ اور انہوں نے کہا، ہم دوشیزہ کو بلائیں گے، اور اس کے منہ سے پوچھیں گے۔\n58۔ اور انہوں نے ربیکا کو بلایا اور کہا، کیا تم اس آدمی کے ساتھ جاؤ گی؟ اور اس نے کہا، میں جاؤں گی۔\n59۔ اور انہوں نے اپنی بہن ربیکا، اس کی دایہ، ابراہیم کے خادم اور اس کے آدمیوں کو بھیج دیا۔\n60۔ اور انہوں نے ربیکا کو برکت دی، اور اس سے کہا، تم ہماری بہن ہو، ہزاروں کروڑوں کی ماں بنو، اور اپنی نسل کو ان لوگوں کے دروازے پر قبضہ کر لو جو ان سے نفرت کرتے ہیں۔\n61۔ اور ربیکا اور اس کی لڑکیاں اٹھیں، اور وہ اونٹوں پر سوار ہو کر اس آدمی کے پیچھے چل پڑیں: اور نوکر نے ربیکا کو لے کر اپنی راہ چلائی۔\n62۔ اور اسحاق کنویں کے راستے لاہیروی سے آیا؛ کیونکہ وہ جنوبی علاقے میں رہتا تھا۔\n63۔ اور اسحاق شام کے وقت کھیت میں مراقبہ کرنے نکلا: اور اس نے اپنی آنکھیں اٹھائیں، اور دیکھا، اور دیکھو، اونٹ آ رہے تھے۔ {مراقبہ کرنا: یا، دعا کرنا}\n64۔ اور ربیکا نے اپنی آنکھیں اٹھائیں، اور جب اس نے اسحاق کو دیکھا تو اونٹ کو روشن کر دیا۔\n65۔ کیونکہ اس نے خادم سے کہا تھا، یہ کون سا آدمی ہے جو میدان میں آ کر ہم سے ملنے آتا ہے؟ اور خادمہ نے کہا، یہ {ہے} میرا آقا: اس لیے اس نے ایک پردہ لیا اور خود کو ڈھانپ لیا۔\n66۔ اور خادم نے اسحاق کو وہ سب کچھ بتایا جو اس نے کیا تھا۔\n67۔ اور اسحاق اسے اپنی ماں سارہ کے خیمے میں لے گیا، اور ربیکا کو لے گیا، اور وہ اس کی بیوی بن گئی؛ اور وہ اس سے محبت کرتا تھا: اور آئزک کو اس کی ماں کی {موت} کے بعد تسلی ملی۔","1۔ پھر ابراہیم نے دوبارہ شادی کی، اور اس کا نام کیتورا تھا۔\n2۔ اور اس نے اسے زمران، جوکشان، میدان، مدیان، اشباک، اور شواہ کو جنم دیا۔\n3۔ اور جوکشان نے سبا اور دیدان کو جنم دیا۔ اور دیدان کے بیٹے اشوریم، لیتوشیم، اور لیومیم تھے۔\n4۔ اور مدیان کے بیٹے؛ ایفاہ، ایفر، حنوخ، عبیدہ، اور ایلداہ۔ یہ سب کیٹوراہ کے بچے تھے۔\n5۔ اور ابراہیم نے جو کچھ بھی اس کے پاس تھا اسحاق کو دے دیا۔\n6۔ لیکن ابراہیم کی کنیزوں کے بیٹوں کو جو ابراہیم کے پاس تھے، انہوں نے تحفے دیے اور انہیں اسحاق اپنے بیٹے سے دور بھیج دیا، جب وہ زندہ تھا، مشرق کی طرف، مشرقی ملک کی طرف۔\n7۔ اور یہ ابراہیم کی زندگی کے وہ دن ہیں جو اس نے گزارے، سو تینٹھ پندرہ سال۔\n8۔ پھر ابراہیم نے بھوت کو چھوڑ دیا، اور بوڑھے عمر میں مر گیا، ایک بوڑھا اور مکمل عمر رسیدہ؛ اور اسے اپنے لوگوں کے پاس جمع کر دیا گیا۔\n9۔ اور اس کے بیٹوں اسحاق اور اسماعیل نے اسے مکپیلہ کی غار میں دفن کیا، جو افرون کے میدان میں تھا، جو زوہار دی ہٹی کا بیٹا ہے، جو {مامرے} سے پہلے ہے؛\n10۔ وہ میدان جو ابراہیم نے ہیتھ کے بیٹوں سے خریدا: وہاں ابراہیم دفن تھا، اور سارہ اس کی بیوی۔\n11۔ اور ابراہیم کی موت کے بعد ایسا ہوا کہ خدا نے اس کے بیٹے اسحاق کو برکت دی؛ اور اسحاق لاہیروی کے کنویں کے پاس رہتا تھا۔\n12۔ اب یہ اسماعیل کی نسلیں ہیں، جو ابراہیم کا بیٹا تھا، جسے ہاجرہ مصری، سارہ کی خادم، نے ابراہیم کو جنم دیا:\n13۔ اور یہ اسماعیل کے بیٹوں کے نام ہیں، ان کے ناموں کے مطابق، ان کی نسلوں کے مطابق: اسماعیل کا پہلا اولاد، نباجوت؛ اور کیدار، اور ادبیل، اور میبسام،\n14۔ اور مشمہ، اور دومہ، اور ماسا،\n15. حدار، اور تیما، جیتور، نافش، اور کیدیمہ: {حدار: یا، حداد}\n16۔ یہ اسماعیل کے بیٹے ہیں، اور یہ ان کے نام ہیں، اپنے شہروں اور قلعوں کے ذریعے؛ بارہ شہزادے اپنی قوموں کے مطابق۔\n17۔ اور یہ اسماعیل کی زندگی کے سال ہیں، ایک سو تیس سات سال: اور اس نے بھوت کو چھوڑ دیا اور فوت ہو گیا؛ اور اسے اپنے لوگوں کے پاس جمع کیا گیا۔\n18۔ اور وہ حویلہ سے شور تک بسے، یعنی مصر سے پہلے، جب تم آشور کی طرف جاتے ہو: {اور} وہ اپنے تمام بھائیوں کی موجودگی میں مرا۔ {وفات: عبرانی۔ گر گیا}\n19۔ اور یہ اسحاق کی نسلیں ہیں، جو ابراہیم کا بیٹا تھا: ابراہیم نے اسحاق کو جنم دیا:\n20۔ اور اسحاق چالیس سال کا تھا جب اس نے ربیقہ کو بیوی بنایا، جو پدانارام کے بیت ویل شامی کی بیٹی اور لبان شامی کی بہن تھی۔\n21۔ اور اسحاق نے اپنی بیوی کے لیے خداوند سے دعا کی، کیونکہ وہ بانجھ تھی: اور خداوند نے اس سے دعا کی، اور ربیکا اس کی بیوی حاملہ ہوئی۔\n22۔ اور بچے اس کے اندر مل کر جدوجہد کر رہے تھے؛ اور اس نے کہا، اگر ایسا ہے تو میں ایسا کیوں ہوں؟ اور وہ خداوند سے پوچھنے گئی۔\n23۔ اور خداوند نے اس سے کہا، دو قومیں تیرے پیٹ میں ہیں، اور دو قسم کے لوگ تیرے پیٹ سے جدا ہوں گے؛ اور {ایک} قوم {دوسرے} سے زیادہ طاقتور ہوگی؛ اور بڑا چھوٹے کی خدمت کرے گا۔\n24۔ اور جب اس کی پیدائش کے دن پورے ہوئے، دیکھو، اس کے رحم میں جڑواں بچے تھے۔\n25۔ اور پہلا سرخ نکلا، بالوں والے لباس کی طرح؛ اور انہوں نے اس کا نام عیسو کہا۔\n26۔ اور اس کے بعد اس کا بھائی باہر آیا، اور اس کا ہاتھ عیسو کی ایڑی پر تھام گیا؛ اور اس کا نام یعقوب تھا: اور جب وہ انہیں پیدا ہوئی تو اسحاق تین ساٹھ سال کا تھا۔\n27۔ اور لڑکے بڑے ہو گئے: اور عیسو ایک چالاک شکاری تھا، ایک کھیت کا آدمی؛ اور یعقوب ایک سادہ آدمی تھا، خیموں میں رہتا تھا۔\n28۔ اور اسحاق عیسو سے محبت کرتا تھا، کیونکہ اس نے اپنا ہرن کھایا؛ لیکن ربیکا یعقوب سے محبت کرتا تھا۔ {وہ...: عبرانی۔ ہرن کا گوشت اس کے منہ میں تھا}\n29۔ اور یعقوب نے پوتاج کیا: اور عیسو کھیت سے آیا، اور وہ بے ہوش ہو گیا:\n30۔ اور عیسو نے یعقوب سے کہا، میں دعا کرتا ہوں کہ مجھے اسی سرخ {پوٹیج} سے کھلا دے؛ کیونکہ میں بے ہوش ہوں: اسی لیے اس کا نام ایڈوم تھا۔ {ساتھ...: عبوری۔ اس سرخ کے ساتھ، اس سرخ پوٹیج کے ساتھ} {ایڈوم: وہ سرخ ہے}\n31۔ اور یعقوب نے کہا، آج مجھے اپنا پیدائشی حق بیچ۔\n32۔ اور عیسو نے کہا، دیکھو، میں مرنے کے قریب ہوں، اور یہ پیدائشی حق مجھے کیا فائدہ دے گا؟ {پر...: عبرانی۔ مرنے والا ہوں}\n33۔ اور یعقوب نے کہا، آج مجھ سے قسم کھاؤ؛ اور اس نے اس سے قسم کھائی: اور اس نے اپنا پیدائشی حق یعقوب کو بیچ دیا۔\n34۔ پھر یعقوب نے عیسو کو روٹی اور دالوں کے برتن دیے؛ اور اس نے کھایا، پیا، اٹھ کھڑا ہوا، اور اپنے راستے پر چلا گیا: یوں عیسو نے اپنے پیدائشی حق سے نفرت کی۔","1۔ اور اس سرزمین میں قحط آیا، اس کے علاوہ جو پہلے قحط ابراہیم کے زمانے میں آیا تھا۔ اور اسحاق فلستیوں کے بادشاہ ابیملک، جیرار کے پاس گیا۔\n2۔ اور خداوند اس پر ظاہر ہوا اور کہا، مصر میں مت جاؤ؛ اس سرزمین میں رہو جس کے بارے میں میں تمہیں بتاؤں گا:\n3۔ اس زمین میں قیام کرو، اور میں تمہارے ساتھ ہوں گا، اور تمہیں برکت دوں گا؛ کیونکہ میں تمہیں اور تمہاری نسل کو یہ تمام ممالک دوں گا، اور وہ قسم پوری کروں گا جو میں نے ابراہیم تمہارے باپ سے کیا ہے؛\n4۔ اور میں تمہاری نسل کو آسمان کے ستاروں کی طرح بڑھاؤں گا، اور تمہاری نسل کو یہ تمام ممالک دوں گا؛ اور تیری نسل میں زمین کی تمام قومیں بابرکت ہوں گی؛\n5۔ کیونکہ ابراہیم نے میری آواز مانی، اور میرے احکام، میرے احکامات، میرے قوانین اور میرے قوانین کو پورا کیا۔\n6۔ اور اسحاق جیرار میں رہتا تھا:\n7۔ اور اس جگہ کے مردوں نے اس کی بیوی سے درخواست کی؛ اور اس نے کہا، وہ میری بہن ہے: کیونکہ وہ ڈرتا تھا کہ کہے، {وہ} میری بیوی ہے؛ کہاں، {اس نے کہا} کہ اس جگہ کے لوگ مجھے ربیکا کے لیے مار ڈالیں؛ کیونکہ وہ دیکھنے کے قابل تھی۔\n8۔ اور جب وہ وہاں کافی عرصہ رہا، تو فلستیوں کے بادشاہ ابیملک، نے کھڑکی سے باہر دیکھا اور دیکھا، اور دیکھو، اسحاق اپنی بیوی ربیکا کے ساتھ کھیل رہا تھا۔\n9۔ اور ابیمیلک نے اسحاق کو بلایا اور کہا، دیکھو، وہ تمہاری بیوی ہے، اور تم نے کیسے کہا، وہ میری بہن ہے؟ اور آئزک نے اس سے کہا، کیونکہ میں نے کہا، ورنہ میں اس کے لیے مر جاؤں۔\n10۔ اور ابیملک نے کہا، یہ کیا ہے جو تم نے ہمارے ساتھ کیا ہے؟ ان لوگوں میں سے کوئی تمہاری بیوی کے ساتھ ہلکا سا رشتہ رکھ سکتا تھا، اور تمہیں ہمیں قصوروار کر دینا چاہیے تھا۔\n11۔ اور ابیملک نے اپنے تمام لوگوں کو حکم دیا، کہ جو اس آدمی یا اس کی بیوی کو چھوئے گا اسے ضرور قتل کر دیا جائے گا۔\n12۔ پھر اسحاق نے اس زمین میں بوئے، اور اسی سال سو گنا وصول کیا: اور خداوند نے اسے برکت دی۔ {موصول شدہ: عبوری۔ مل گیا}\n13۔ اور وہ آدمی بڑا ہو گیا، آگے بڑھا، اور بڑھتا گیا یہاں تک کہ وہ بہت بڑا ہو گیا: {چلا گیا...: عبرانی چلا گیا}\n14۔ کیونکہ اس کے پاس ریوڑ، ریوڑ اور خادموں کی بڑی تعداد تھی: اور فلسطینی اس سے حسد کرتے تھے۔ {نوکر: یا، پالنا}\n15۔ جتنے کنویں اس کے والد کے خادموں نے ابراہیم کے زمانے میں کھودے تھے، فلسطینیوں نے انہیں روک دیا اور انہیں مٹی سے بھر دیا۔\n16۔ اور ابیمیلک نے اسحاق سے کہا، ہم سے دور ہو جاؤ؛ کیونکہ تم ہم سے کہیں زیادہ طاقتور ہو۔\n17۔ اور اسحاق وہاں سے روانہ ہوا، جیرار کی وادی میں اپنا خیمہ لگا کر وہاں رہا۔\n18۔ اور اسحاق نے دوبارہ وہ پانی کے کنویں کھودے جو انہوں نے ابراہیم اپنے والد کے زمانے میں کھودے تھے؛ کیونکہ فلسطینیوں نے ابراہیم کی موت کے بعد انہیں روکا تھا: اور اس نے ان کے نام انہی ناموں پر پکارے جن سے اس کے والد نے انہیں پکارا تھا۔\n19۔ اور اسحاق کے خادموں نے وادی میں کھدائی کی، اور وہاں چشموں کا ایک کنواں پایا۔ {چھلانگ لگانا: عبرانی۔ زندہ}\n20۔ اور جیرار کے چرواہوں نے اسحاق کے چرواہوں کے ساتھ لڑائی کی، کہتے ہوئے، پانی ہمارا ہے: اور اس نے کنویں کا نام ایسک رکھا؛ کیونکہ وہ اس کے ساتھ جدوجہد کرتے تھے۔ {ایسک: یعنی، تنازعہ}\n21۔ اور انہوں نے ایک اور کنواں کھودا اور اس کے لیے بھی کوشش کی: اور اس نے اس کا نام سیتنا رکھا۔ {ستنہ: یعنی، نفرت}\n22۔ اور اس نے وہاں سے نکل کر ایک اور کنواں کھودا؛ اور اس کے لیے انہوں نے کوشش نہیں کی: اور اس نے اس کا نام ریہوبوت رکھا؛ اور اس نے کہا، اب خداوند نے ہمارے لیے جگہ بنا دی ہے، اور ہم زمین میں پھل دار ہوں گے۔ {ریہوبوتھ: یہ ہے روم}\n23۔ اور وہ وہاں سے بئر السبع چلا گیا۔\n24۔ اور اسی رات خداوند اس پر ظاہر ہوا اور کہا، میں ابراہیم کا خدا ہوں، تمہارا باپ: ڈر مت، کیونکہ میں تمہارے ساتھ ہوں، اور تمہیں برکت دوں گا، اور تیری نسل کو اپنے بندے ابراہیم کے لیے بڑھاؤں گا۔\n25۔ اور اس نے وہاں ایک قربان گاہ بنائی، خداوند کے نام پر پکارا اور وہاں اپنا خیمہ لگایا: اور وہاں اسحاق کے خادموں نے کنواں کھودا۔\n26۔ پھر ابیمیلخ جیرار سے اس کے پاس آیا، اور آہزتھ اس کے دوستوں میں سے ایک، اور فیشول اس کی فوج کا چیف کپتان۔\n27۔ اور اسحاق نے ان سے کہا، تم میرے پاس کیوں آئے، جب تم مجھ سے نفرت کرتے ہو اور مجھے اپنے سے دور بھیج دیا؟\n28۔ اور انہوں نے کہا، \"ہم نے یقینا دیکھا کہ خداوند تمہارے ساتھ تھا: اور ہم نے کہا، اب ہمارے درمیان ایک قسم ہو، {حتیٰی} ہمارے اور تمہارے درمیان، اور ہم تم سے عہد کریں؛ {ہم نے دیکھا...: عبرانی۔ دیکھ کر ہم نے دیکھا}\n29۔ کہ تم ہمیں کوئی نقصان نہیں پہنچاؤ گے، جیسا کہ ہم نے تمہیں چھوا نہیں، اور جیسا کہ ہم نے تمہارے ساتھ صرف بھلائی کی ہے، اور تمہیں امن کے ساتھ رخصت کیا ہے: تو اب خداوند کی برکت یافتہ ہو۔ {وہ...: عبرانی۔ اگر تم ایسا کرو گے}\n30۔ اور اس نے ان کے لیے دعوت بنائی، اور وہ واقعی کھائے اور پیے۔\n31۔ اور وہ صبح سویرے اٹھ کھڑے ہوئے، اور ایک دوسرے سے قسم کھائے: اور اسحاق نے انہیں بھیج دیا، اور وہ امن کے ساتھ اس سے رخصت ہو گئے۔\n32۔ اور اسی دن آئزک کے خادم آئے اور اسے اس کنویں کے بارے میں بتایا جو انہوں نے کھودا تھا، اور کہا، ہم نے پانی پایا ہے۔\n33۔ اور اس نے اسے سبا کہا: اس لیے آج تک شہر کا نام بئر شبع ہے۔ {شباح: یعنی، ایک حلف} {بیر السبع: یعنی، قسم کا کنواں ہے}\n34۔ اور عیسو چالیس سال کا تھا جب اس نے بیری دی ہٹی کی بیٹی جیوڈتھ اور ایلون دی ہٹی کی بیٹی باشمتھ سے شادی کی:\n35۔ جو اسحاق اور ربیکا کے لیے ذہنی غم تھے۔ {ایک غم...: عبرانی۔ روح کی تلخی}","1۔ اور ایسا ہوا کہ جب اسحاق بوڑھا ہوا اور اس کی آنکھیں مدھم تھیں کہ وہ دیکھ نہ سکتا تھا، اس نے عیسو کو اپنا سب سے بڑا بیٹا بلایا اور کہا، میرا بیٹا۔ اور اس نے کہا، دیکھو، {یہاں ہوں} میں ہوں۔\n2۔ اور اس نے کہا، دیکھو اب میں بوڑھا ہو گیا ہوں، مجھے اپنی موت کا دن معلوم نہیں:\n3۔ اب میں تم سے درخواست کرتا ہوں کہ اپنے ہتھیار، اپنا ترکش اور کمان لے جاؤ، اور میدان میں جاؤ، اور مجھے {کچھ} ہرن لے آؤ؛ {ٹیک: عبوری۔ ہنٹ}\n4۔ اور مجھے وہ لذیذ گوشت بنا دو جو میں پسند کرتا ہوں، اور مجھے لاؤ، تاکہ میں کھا سکوں؛ تاکہ میری روح تمہیں برکت دے اس سے پہلے کہ میں مروں۔\n5۔ اور ربیقا نے سنا جب اسحاق نے عیسو سے اپنے بیٹے سے بات کی۔ اور عیسو کھیت میں گیا تاکہ ہرن کا شکار کرے، اور اسے لے آیا۔\n6۔ اور ربیکا نے اپنے بیٹے یعقوب سے کہا، دیکھو، میں نے تمہارے والد کو اپنے بھائی عیسو سے بات کرتے سنا،\n7۔ میرے لیے ہرن کا گوشت لاؤ، اور مجھے لذیذ گوشت بنا دو، تاکہ میں کھا سکوں، اور میری موت سے پہلے خداوند کے سامنے تمہیں برکت دوں۔\n8۔ اب، میرے بیٹے، میری آواز کی اطاعت کرو جو میں تمہیں حکم دیتا ہوں۔\n9۔ اب ریوڑ کے پاس جاؤ، اور وہاں سے مجھے دو اچھے بکریوں کے بچے لے آؤ؛ اور میں انہیں تمہارے والد کے لیے لذیذ گوشت بناؤں گا، جیسا کہ وہ چاہتا ہے:\n10۔ اور تم اسے اپنے باپ کے پاس لے آؤ، تاکہ وہ کھا سکے، اور اپنی موت سے پہلے تمہیں برکت دے۔\n11۔ اور یعقوب نے اپنی ماں ربیکا سے کہا، دیکھو، عیسو میرا بھائی بالوں والا آدمی ہے، اور میں ایک چالاک آدمی ہوں:\n12۔ میرے والد شاید مجھے محسوس کریں، اور میں انہیں دھوکہ باز سمجھوں گا؛ اور میں اپنے اوپر لعنت لاؤں گا، برکت نہیں۔\n13۔ اور اس کی ماں نے اسے کہا، میرے بیٹے، میری لعنت مجھ پر ہو: صرف میری آواز مانو اور جا کر مجھے لے آؤ۔\n14۔ اور وہ گیا، اور انہیں اپنی ماں کے پاس لایا، اور اس کی ماں نے وہ لذیذ گوشت بنایا جو اس کے والد کو پسند تھا۔\n15۔ اور ربیکا نے اپنے بڑے بیٹے عیسو کے خوبصورت لباس پہنے، جو اس کے ساتھ گھر میں تھے، اور انہیں اپنے چھوٹے بیٹے یعقوب پر پہنایا: {خوبصورت: عبرانی۔ پسندیدہ}\n16۔ اور اس نے بکریوں کے بچوں کی کھال اس کے ہاتھوں اور اس کی گردن کے ہموار حصے پر رکھی:\n17۔ اور اس نے وہ نمکین گوشت اور روٹی جو اس نے تیار کی تھی، اپنے بیٹے یعقوب کے ہاتھ میں دے دی۔\n18۔ اور وہ اپنے والد کے پاس آئے اور کہا، میرے والد: اور کہا، میں یہاں ہوں؛ تم کون ہو، میرے بیٹے؟\n19۔ اور یعقوب نے اپنے والد سے کہا، میں تمہارا پہلا بیٹا عیسو ہوں؛ میں نے ویسا ہی کیا جیسا تم نے مجھے برا کہا: اٹھو، میں تم سے دعا کرتا ہوں، بیٹھو اور میرے گوشت کا گوشت کھاؤ، تاکہ تمہاری روح مجھے برکت دے۔\n20۔ اور اسحاق نے اپنے بیٹے سے کہا، میرے بیٹے، تم نے اتنی جلدی کیسے اسے ڈھونڈ لیا؟ اور اس نے کہا، کیونکہ خداوند تیرے خدا نے {یہ} میرے لیے لایا ہے۔ {میرے لیے: ہیب۔ میرے پہلے}\n21۔ اور اسحاق نے یعقوب سے کہا، قریب آؤ، میں دعا کرتا ہوں، تاکہ میں تمہیں محسوس کر سکوں، میرے بیٹے، چاہے تم میرے بیٹے عیسو ہو یا نہ ہو۔\n22۔ اور یعقوب اپنے والد اسحاق کے قریب گیا؛ اور اس نے اسے محسوس کیا، اور کہا، یہ آواز یعقوب کی آواز ہے، لیکن ہاتھ عیسو کے ہاتھ ہیں۔\n23۔ اور اس نے اسے پہچانا نہیں، کیونکہ اس کے ہاتھ بالوں والے تھے، جیسے اس کے بھائی عیسو کے ہاتھ: اس لیے اس نے اسے برکت دی۔\n24۔ اور اس نے کہا، کیا تم میرا بیٹا عیسو ہو؟ اور اس نے کہا، میں {ہوں}۔\n25۔ اور اس نے کہا، \"اسے میرے قریب لے آؤ، اور میں اپنے بیٹے کے گوشت کا گوشت کھاؤں گا، تاکہ میری جان تمہیں برکت دے۔ اور اس نے اسے اپنے قریب لایا، اور کھایا، اور اسے شراب لایا اور پیا۔\n26۔ اور اس کے والد اسحاق نے اسے کہا، اب قریب آؤ، اور مجھے چومو، میرے بیٹے۔\n27۔ اور وہ قریب آیا، اور اسے بوسہ دیا، اور اس نے اس کے کپڑوں کی خوشبو سونگھی، اور اسے برکت دی، اور کہا، دیکھو، میرے بیٹے کی خوشبو {ہے} اس کھیت کی خوشبو کی طرح ہے جسے خداوند نے برکت دی ہے:\n28۔ لہٰذا خدا تمہیں آسمان کی شبنم، زمین کی موٹائی، اور اناج و شراب کی فراوانی عطا فرمائے:\n29۔ لوگ تمہاری خدمت کریں، اور قومیں تمہارے سامنے جھکیں: اپنے بھائیوں کے سردار بنو، اور اپنی ماں کے بیٹوں کو تمہارے سامنے سجدہ کرو: جو بھی تمہیں لعنت دے، اور جو تمہیں برکت دے، وہ مبارک ہو جو تمہیں برکت دے۔\n30۔ اور جیسے ہی اسحاق نے یعقوب کی دعا ختم کی، اور یعقوب ابھی اسحاق اپنے والد کی موجودگی سے باہر نہیں نکلا، تو عیسو، اس کا بھائی، شکار سے واپس آیا۔\n31۔ اور اس نے لذیذ گوشت بھی بنایا، اور اسے اپنے والد کے پاس لے آیا، اور اپنے والد سے کہا، میرے والد اٹھے اور اپنے بیٹے کے گوشت سے کھاؤ، تاکہ تمہاری روح مجھے برکت دے۔\n32۔ اور اس کے والد اسحاق نے اس سے کہا، تم کون ہو؟ اور اس نے کہا، میں تمہارا بیٹا ہوں، تمہارا پہلا بیٹا عیسو۔\n33۔ اور اسحاق بہت زیادہ کانپ اٹھا اور کہا، کون؟ وہ کہاں ہے جس نے ہرن کا گوشت لیا اور مجھے لایا، اور میں نے تمہارے آنے سے پہلے سب کچھ کھا لیا اور اسے برکت دی؟ ہاں، {اور} وہ برکت یافتہ ہوگا۔ {کانپتے ہوئے...: عبرانی۔ شدید کپکپاہٹ کے ساتھ کانپ رہا تھا} {لیا گیا: عبرانی۔ شکار}\n34۔ اور جب عیسو نے اپنے والد کے الفاظ سنے، تو اس نے ایک بڑی اور تلخ چیخ کے ساتھ رونا شروع کیا اور اپنے والد سے کہا، اے میرے والد سے مجھے بھی برکت دے، مجھے بھی۔\n35۔ اور اس نے کہا، تمہارا بھائی چالاکی سے آیا اور تمہاری برکت چھین لی۔\n36۔ اور اس نے کہا، کیا اس کا نام صحیح طور پر یعقوب نہیں ہے؟ کیونکہ اس نے مجھے دو بار بدل دیا ہے: اس نے میرا پیدائشی حق چھین لیا؛ اور دیکھو، اب اس نے میری برکت چھین لی ہے۔ اور اس نے کہا، کیا تم نے میرے لیے کوئی دعا نہیں رکھی؟ {جیکب: یعنی، ایک متبادل ہے}\n37۔ اور اسحاق نے جواب دیا اور عیسو سے کہا، دیکھو، میں نے اسے اپنا رب بنا لیا ہے، اور اس کے تمام بھائی اسے غلام بنا دیے ہیں؛ اور میں نے اسے اناج اور شراب سے سہارا دیا ہے: اور اب میں تمہارے ساتھ کیا کروں، میرے بیٹے؟ {برقرار ہے: یا، حمایت شدہ}\n38۔ اور عیسو نے اپنے باپ سے کہا، کیا تمہارے پاس صرف ایک برکت ہے، میرے والد؟ مجھے بھی برکت دے، اے میرے والد۔ اور عیسو نے اپنی آواز بلند کی اور رونے لگا۔\n39۔ اور اس کے باپ اسحاق نے جواب دیا اور کہا، دیکھو، تمہارا گھر زمین کی موٹی پن ہوگا، اور آسمان کی شبنم اوپر سے؛ {موٹاپی: یا، موٹاپے کی}\n40۔ اور اپنی تلوار سے زندہ رہو گے، اور اپنے بھائی کی خدمت کرو گے؛ اور جب تمہیں حکمرانی ملے گی، تو تم اس کا جوا اپنی گردن سے توڑو گے۔\n41۔ اور عیسو نے یعقوب سے اس نعمت کی وجہ سے نفرت کی جو اس کے والد نے اسے دی تھی: اور عیسو نے دل ہی دل میں کہا، میرے والد کے لیے سوگ کے دن قریب آ گئے ہیں؛ پھر میں اپنے بھائی یعقوب کو مار ڈالوں گا۔\n42۔ اور عیسو، اس کے بڑے بیٹے کے یہ الفاظ ربیکا کو سنائے گئے: اور اس نے یعقوب کو اپنے چھوٹے بیٹے کو بلایا، اور کہا، دیکھو، تمہارا بھائی عیسو، جیسا کہ تمہیں چھو رہا ہے، خود کو تسلی دیتا ہے اور تمہیں مارنے کا ارادہ رکھتا ہے۔\n43۔ اب، میرے بیٹے، میری آواز مانو؛ اور اٹھو، میرے بھائی ہاران کے پاس لابان بھاگو؛\n44۔ اور اس کے ساتھ چند دن رہو، جب تک کہ تمہارا بھائی غصہ واپس نہ لے جائے؛\n45۔ جب تک تمہارے بھائی کا غصہ تم سے دور نہ ہو جائے اور وہ بھول جائے کہ تم نے اس کے ساتھ کیا کیا ہے: تب میں بھیجوں گا، اور تمہیں وہاں سے لے آؤں گا: میں تم دونوں سے ایک دن میں کیوں محروم ہو جاؤں؟\n46۔ اور ربیکا نے اسحاق سے کہا، میں ہیت کی بیٹیوں کی وجہ سے اپنی زندگی سے تھک چکا ہوں: اگر یعقوب ہیتھ کی بیٹیوں کی بیوی لے لے، جیسے یہ زمین کی بیٹیوں کی ہیں، تو میری زندگی کا کیا فائدہ ہوگا؟","1۔ اور اسحاق نے یعقوب کو بلایا، اسے دعا دی، حکم دیا اور کہا، \"تم کنعان کی بیٹیوں کی بیوی نہ لو۔\n2۔ اٹھو، پادانارم جاؤ، جو تمہاری ماں کے والد بیت ویل کے گھر ہے؛ اور وہاں سے تمہاری ماں کے بھائی لابان کی بیٹیوں کی بیوی لے۔\n3۔ اور خدا تعالیٰ تمہیں برکت دے، تمہیں پھل دار اور بڑھائے تاکہ تم لوگوں کی کثرت بن سکو؛ {ایک ہجوم...: عبرانی۔ لوگوں کی ایک مجلس}\n4۔ اور تمہیں ابراہیم کی برکت دے، اپنے لیے اور تمہاری نسل کو بھی تمہارے ساتھ؛ تاکہ تم اس زمین کے وارث بن سکو جس میں تم اجنبی ہو، جو خدا نے ابراہیم کو دی تھی۔ {جس میں...: عبرانی۔ تمہارے قیام کے بارے میں}\n5۔ اور اسحاق نے یعقوب کو بھیج دیا: اور وہ پدانارام گیا، لابان کے پاس گیا، جو بیت ویل شامی کا بیٹا تھا، جو یعقوب اور عیسو کی ماں ربیکا کا بھائی تھا۔\n6۔ جب عیسو نے دیکھا کہ اسحاق نے یعقوب کو برکت دی ہے، اور اسے پادانارم بھیج دیا تاکہ وہاں سے اس کی بیوی لے جائے؛ اور جب اس نے اسے برکت دی تو اسے حکم دیا کہ تم کنعان کی بیٹیوں کی بیوی نہ لو؛\n7۔ اور جیکب نے اپنے والد اور والدہ کی اطاعت کی، اور پیڈانرام چلا گیا؛\n8۔ اور عیسو، جب اس نے دیکھا کہ کنعان کی بیٹیاں اسحاق کو اس کے والد کو پسند نہیں کرتیں؛ {خوش...: عبرانی۔ آنکھوں میں برے تھے وغیرہ}\n9۔ پھر عیسو اسماعیل کے پاس گیا، اور اپنی بیویوں کو ملا، جو اسماعیل ابراہیم کے بیٹے کی بیٹی اور نباجوت کی بہن تھی، کو اپنی بیوی بنا لیا۔ {محلات: یا، باشمتھ}\n10۔ اور یعقوب بیرشبع سے باہر نکلا اور ہاران کی طرف روانہ ہوا۔ {ہاران: گریڈ چاران}\n11۔ اور اس نے ایک خاص جگہ پر روشنی ڈالی اور ساری رات وہاں رکا کیونکہ سورج غروب ہو چکا تھا؛ اور اس نے اس جگہ کے پتھر اتارے، انہیں اپنے تکیوں کے طور پر رکھا، اور اسی جگہ لیٹ کر سو گیا۔\n12۔ اور اس نے خواب دیکھا، اور دیکھا کہ زمین پر ایک سیڑھی نصب ہے، جس کا اوپر آسمان تک پہنچا ہوا ہے: اور دیکھو خدا کے فرشتے اس پر چڑھ رہے ہیں اور اتر رہے ہیں۔\n13۔ اور دیکھو، خداوند اس کے اوپر کھڑا ہوا اور کہا، میں ابراہیم کا خداوند خدا ہوں، تمہارا باپ اور اسحاق کا خدا: وہ زمین جس پر تم لیٹے ہو، میں اسے تمہیں اور تمہاری نسل کو دوں گا؛\n14۔ اور تمہاری نسل زمین کی خاک کی طرح ہوگی، اور تم مغرب، مشرق، شمال اور جنوب میں پھیل جاؤ گے، اور تیرے اور تیری نسل میں زمین کے تمام خاندان برکت پائیں گے۔ {پھیلاؤ...: عببرانی۔ بریک فورتھ}\n15۔ اور دیکھو، میں تمہارے ساتھ ہوں، اور تمہیں ہر {جگہ} میں رکھوں گا جہاں تم جاؤ گے، اور تمہیں اس زمین میں واپس لاؤں گا؛ کیونکہ میں تمہیں نہیں چھوڑوں گا، جب تک میں وہ نہ کر لوں جو میں نے تم سے بتایا ہے۔\n16۔ اور یعقوب اپنی نیند سے جاگا اور کہا، یقینا خداوند اسی جگہ ہے؛ اور میں جانتا تھا کہ ایسا نہیں ہے۔\n17۔ اور وہ ڈر گیا، اور کہا، یہ جگہ کتنی خوفناک ہے! یہ {ہے} خدا کا گھر ہے، اور یہ {ہے} جنت کا دروازہ۔\n18۔ اور یعقوب صبح سویرے اٹھا، اور وہ پتھر لیا جو اس نے اپنے تکیوں کے لیے رکھا تھا، اور اسے ایک ستون کے طور پر لگایا اور اس کے اوپر تیل ڈالا۔\n19۔ اور اس نے اس جگہ کا نام بیت ایل رکھا: لیکن اس شہر کا نام پہلے لوز تھا۔ {بیت ھل: یعنی خدا کا گھر}\n20۔ اور یعقوب نے قسم کھائی، کہا، اگر خدا میرے ساتھ ہو، اور مجھے اسی راستے میں رکھے، اور مجھے روٹی دے تاکہ میں کھاؤں، اور لباس پہنوں،\n21. تاکہ میں اپنے والد کے گھر امن کے ساتھ واپس آؤں؛ تب خداوند میرا خدا ہوگا:\n22۔ اور یہ پتھر، جو میں نے ایک ستون کے طور پر رکھا ہے، خدا کا گھر ہوگا: اور جو کچھ تم مجھے دو گے، اس میں سے میں تمہیں دسواں ضرور دوں گا۔","1۔ پھر یعقوب اپنے سفر پر روانہ ہوا اور مشرق کے لوگوں کی سرزمین میں داخل ہوا۔ {گیا...: عببرانی۔ اس کے پاؤں اٹھائیں} {لوگ: عبرانی۔ بچے}\n2۔ اور اس نے دیکھا کہ کھیت میں ایک کنواں ہے، اور وہاں تین بھیڑوں کے ریوڑ پڑے تھے؛ کیونکہ اس کنویں سے وہ ریوڑوں کو پانی دیتے تھے: اور کنویں کے منہ پر ایک بڑا پتھر تھا۔\n3۔ اور وہاں تمام ریوڑ جمع ہو گئے، انہوں نے کنویں کے منہ سے پتھر کو رول کیا، بھیڑوں کو پانی دیا، اور اس کی جگہ پتھر دوبارہ کنویں کے منہ پر رکھ دیا۔\n4۔ اور یعقوب نے ان سے کہا، میرے بھائیو، تم کہاں سے ہو؟ اور انہوں نے کہا، ہاران کے بارے میں ہم ہیں۔\n5۔ اور اس نے ان سے کہا، کیا تم ناحور کے بیٹے لابان کو جانتے ہو؟ اور انہوں نے کہا، ہم اسے جانتے ہیں۔\n6۔ اور اس نے ان سے کہا، {کیا} وہ ٹھیک ہے؟ اور انہوں نے کہا، {وہ ہے} خیر: اور دیکھو، راحیل، اس کی بیٹی بھیڑوں کے ساتھ آتی ہے۔ {کیا وہ...: عبرانی۔ کیا اس میں سکون ہے؟}\n7۔ اور اس نے کہا، دیکھو، ابھی بڑا دن ہے، نہ ہی مویشیوں کو اکٹھا کرنے کا وقت ہے: بھیڑوں کو پانی دو، اور جاؤ اور ان کو کھلاؤ۔ {یہ ہے...: عبرانی۔ پھر بھی دن بہت اچھا ہے}\n8۔ اور انہوں نے کہا، ہم نہیں کر سکتے، جب تک کہ تمام ریوڑ اکٹھے نہ ہو جائیں، اور {جب تک} وہ کنویں کے منہ سے پتھر نہ اتار دیں؛ پھر ہم بھیڑوں کو پانی دیتے ہیں۔\n9۔ اور جب وہ ابھی ان سے بات کر رہا تھا، راحیل اپنے باپ کی بھیڑوں کے ساتھ آئی، کیونکہ اس نے انہیں سنبھالا۔\n10۔ اور جب یعقوب نے راحیل، لابان کی بیٹی، جو اس کی ماں کا بھائی تھا، اور لابان کی بھیڑ، جو اس کی ماں کا بھائی تھا، دیکھا، تو یعقوب قریب گیا، اور کنویں کے منہ سے پتھر نکالا، اور اپنی ماں کے بھائی لابان کے ریوڑ کو پانی دیا۔\n11۔ اور یعقوب نے راحیل کو چوما، اپنی آواز بلند کی، اور رویا۔\n12۔ اور یعقوب نے راحیل کو بتایا کہ وہ اس کے والد کا بھائی ہے، اور وہ ربیکا کا بیٹا ہے: اور وہ بھاگ گئی اور اپنے والد کو بتایا۔\n13۔ اور جب لابان نے اپنی بہن کے بیٹے یعقوب کی خبر سنی تو وہ اس سے ملنے دوڑا، اسے گلے لگایا، بوسہ دیا، اور اپنے گھر لے آیا۔ اور اس نے لابان کو یہ سب باتیں بتائیں۔ {خبریں: عبرانی۔ سماعت}\n14۔ اور لابان نے اس سے کہا، یقینا تو میری ہڈی اور گوشت ہو۔ اور وہ ایک مہینے کے عرصے کے لیے اس کے ساتھ رہا۔ {دی اسپیس...: ہیب۔ ایک مہینہ دن}\n15۔ اور لابان نے یعقوب سے کہا، چونکہ تم میرے بھائی ہو، کیا تم میری بے کار خدمت کرو گے؟ بتاؤ، تمہاری اجرت کیا ہوگی؟\n16۔ اور لابان کی دو بیٹیاں تھیں: بڑی کا نام {تھا} لیح، اور چھوٹی کا نام {تھا} راحیل۔\n17۔ لیا {تھی} نرم آنکھوں والی؛ لیکن ریچل خوبصورت اور پسندیدہ تھی۔\n18۔ اور یعقوب نے ریچل سے محبت کی؛ اور کہا، میں تمہاری چھوٹی بیٹی راحیل کے لیے سات سال تمہاری خدمت کروں گا۔\n19۔ اور لابان نے کہا، {یہ بہتر ہے کہ میں اسے تمہیں دوں، بجائے اس کے کہ میں اسے کسی اور مرد کو دوں: میرے ساتھ رہو۔\n20۔ اور جیکب نے ریچل کے لیے سات سال خدمات انجام دیں؛ اور وہ چند دن لگے، اس محبت کی وجہ سے جو وہ اس کے دل میں رکھتا تھا۔\n21۔ اور یعقوب نے لابان سے کہا، میری بیوی دے دو، کیونکہ میرے دن مکمل ہو گئے ہیں، تاکہ میں اس کے پاس جا سکوں۔\n22۔ اور لابان نے اس جگہ کے تمام لوگوں کو جمع کیا اور دعوت دی۔\n23۔ اور شام کو ایسا ہوا کہ اس نے لیا کو اپنی بیٹی لے کر اپنے پاس لے آیا؛ اور وہ اس کے پاس گیا۔\n24۔ اور لابان نے اپنی بیٹی لیہ زلپاہ کو اپنی خادمہ کے طور پر دی۔\n25۔ اور ایسا ہوا کہ صبح کے وقت، دیکھو، یہ [تھا} لیا: اور اس نے لابان سے کہا، یہ کیا ہے جو تم نے میرے ساتھ کیا ہے؟ کیا میں نے راحیل کے لیے تمہارے ساتھ خدمت نہیں کی؟ تو پھر تم نے مجھے کیوں بہکایا؟\n26۔ اور لابان نے کہا، ہمارے ملک میں ایسا نہیں ہونا چاہیے کہ چھوٹے کو پہلے دیا جائے۔ {ملک: عبرانی۔ جگہ}\n27۔ اس کا ہفتہ پورا کرو، اور ہم تمہیں یہ بھی دیں گے اس خدمت کے لیے جو تم میرے ساتھ سات سال اور خدمت کرو گے۔\n28۔ اور یعقوب نے ایسا کیا، اور اس کا ہفتہ پورا کیا: اور اس نے اپنی بیٹی راحیل کو بھی بیوی کے لیے دے دیا۔\n29۔ اور لابان نے اپنی بیٹی بلحہ کو اپنی خادمہ راحیل کو دے دیا تاکہ وہ اس کی خادمہ بن جائے۔\n30۔ اور وہ بھی ریحیل کے پاس گیا، اور اس نے ریحیل سے لیا سے زیادہ محبت کی، اور سات سال اور اس کے ساتھ خدمت کی۔\n31. اور جب خداوند نے دیکھا کہ لیہ {نفرت کی جاتی ہے}، تو اس نے اس کا رحم کھول دیا: لیکن ریحیل {بانجھ} تھی۔\n32۔ اور لیاہ نے حاملہ ہوا اور ایک بیٹا پیدا کیا، اور اس کا نام روبن رکھا، کیونکہ اس نے کہا، یقینا خداوند نے میری مصیبت دیکھی ہے؛ اب اس لیے میرا شوہر مجھ سے محبت کرے گا۔ {روبن: یعنی، بیٹے کو دیکھو}\n33۔ اور وہ دوبارہ حاملہ ہوئی، اور ایک بیٹا پیدا ہوا؛ اور کہا، کیونکہ خداوند نے سنا کہ مجھے نفرت کی جاتی ہے، اس لیے اس نے مجھے یہ بیٹا بھی دیا ہے: اور اس نے اس کا نام شمعون رکھا۔ {سیمیون: یعنی، سماعت}\n34۔ اور وہ دوبارہ حاملہ ہوئی، اور بیٹا پیدا ہوا؛ اور کہا، اب میرا شوہر میرے ساتھ شامل ہو جائے گا، کیونکہ میں نے اسے تین بیٹے دیے ہیں: اسی لیے اس کا نام لاوی تھا۔ {لیوی: یعنی، جوڑا گیا}\n35۔ اور اس نے دوبارہ حاملہ ہوا اور بیٹا پیدا ہوا، اور کہا، اب میں خداوند کی تعریف کروں گی، اس لیے اس نے اس کا نام یہوداہ رکھا؛ اور بائیں سمت میں۔ {یہوداہ: یعنی، تعریف} {بائیں...: عبرانی۔ برداشت سے کھڑا ہوا}","1۔ اور جب راحیل نے دیکھا کہ اس کے ہاں کوئی اولاد نہیں ہوئی، تو راحیل نے اپنی بہن سے حسد کیا؛ اور یعقوب سے کہا، مجھے بچے دو، ورنہ میں مر جاؤں گا۔\n2۔ اور یعقوب کا غصہ ریحیل پر بھڑکا، اور اس نے کہا، {کیا میں خدا کی جگہ ہوں، جس نے تم سے رحم کا پھل چھپایا ہے؟\n3۔ اور اس نے کہا، دیکھو میری خادمہ بلحا، اس کے پاس جاؤ؛ اور وہ میرے گھٹنے ٹیکے گی، تاکہ میں بھی اس سے بچے پیدا کر سکوں۔ {have...: عبرانی اس کے ذریعے بنایا جائے گا}\n4۔ اور اس نے بلحہ کو اپنی خادمہ دے دی، اور یعقوب اس کے پاس گیا۔\n5۔ اور بلحہ نے حاملہ کیا، اور یعقوب کو بیٹا دیا۔\n6۔ اور راحیل نے کہا، خدا نے مجھے فیصلہ کیا ہے، اور میری آواز بھی سنی ہے، اور مجھے بیٹا دیا ہے: اس لیے اس نے اس کا نام دان رکھا۔ {دان: یعنی، فیصلہ کرنا}\n7۔ اور بلحا راحیل کی خادمہ دوبارہ حاملہ ہوئی، اور یعقوب کو دوسرا بیٹا دیا۔\n8۔ اور راحیل نے کہا، میں نے اپنی بہن کے ساتھ بڑی کشمکش کی، اور میں کامیاب ہو گیا: اور اس نے اس کا نام نفتالی پکارا۔ {زبردست...: عبرانی۔ خدا کی کشتی} {نفتالی: یعنی، میری کشتی: Gr. Nephthalim}\n9۔ جب لیہ نے دیکھا کہ وہ حمل چھوڑ چکی ہے، تو اس نے زلپاہ کو اپنی خادمہ لے لیا اور اپنے یعقوب کو بیوی دے دیا۔\n10۔ اور زلپا لیا کی نوکرانی یعقوب کو بیٹا پیدا کرتی ہے۔\n11۔ اور لیا نے کہا، ایک فوج آتی ہے: اور اس نے اس کا نام گاد پکارا۔ {گیڈ: یعنی، اے ٹروپ، یا، کمپنی}\n12۔ اور زلپا لیہ کی خادمہ نے یعقوب کو دوسرا بیٹا جنم دیا۔\n13۔ اور لیاہ نے کہا، مبارک ہوں میں، کیونکہ بیٹیاں مجھے مبارک کہیں گی: اور اس نے اس کا نام آشر کہا۔ {خوش...: عبوری۔ میری خوشی میں} {آشر: یعنی، خوش}\n14۔ اور روبن گندم کی فصل کے دنوں میں گیا، کھیت میں منڈریک پایا اور انہیں اپنی ماں لیاہ کے پاس لے آیا۔ پھر راحیل نے لیہ سے کہا، میں دعا کرتی ہوں کہ اپنے بیٹے کے مینڈریک میں سے مجھے دے دو۔\n15۔ اور اس نے اس سے کہا، {کیا یہ چھوٹی بات ہے} کہ تم نے میرے شوہر کو لے لیا ہے؟ اور کیا تم میرے بیٹے کے مینڈریک بھی لے لو گے؟ اور راحیل نے کہا، اس لیے وہ تمہارے بیٹے کی منڈریکس کے لیے رات کو تمہارے ساتھ رہے گا۔\n16۔ اور یعقوب شام کو کھیت سے باہر آیا، اور لیا اس سے ملنے باہر گئی اور کہا، تمہیں میرے پاس آنا ہوگا؛ کیونکہ یقینا میں نے تمہیں اپنے بیٹے کے مینڈریک کے ساتھ رکھا ہے۔ اور اس رات وہ اس کے ساتھ لیٹ گیا۔\n17۔ اور خدا نے لیاہ کی بات مانی، اور وہ حاملہ ہوئی اور یعقوب پانچواں بیٹا پیدا ہوا۔\n18۔ اور لیاہ نے کہا، خدا نے مجھے میری اجرت دی ہے، کیونکہ میں نے اپنی کنواری اپنے شوہر کو دے دی ہے، اور اس نے اس کا نام اساکر رکھا۔ {اساکر: یعنی، ایک کرایہ دار}\n19۔ اور لیاہ دوبارہ حاملہ ہوئی، اور یعقوب چھٹا بیٹا پیدا ہوا۔\n20۔ اور لیا نے کہا، خدا نے مجھے اچھا جہیز دیا ہے؛ اب میرا شوہر میرے ساتھ رہے گا، کیونکہ میں نے اسے چھ بیٹے پیدا کیے ہیں: اور اس نے اس کا نام زبولون رکھا۔ {زبولون: یعنی، رہائش: گریڈ زابولون}\n21۔ اور بعد میں اس نے ایک بیٹی پیدا کی، اور اس کا نام دینا رکھا۔ {دینا: یہ ہے ججمنٹ}\n22۔ اور خدا نے راحیل کو یاد کیا، اور خدا نے اس کی بات سنی اور اس کا رحم کھول دیا۔\n23۔ اور اس نے حاملہ ہوا اور بیٹا پیدا ہوا؛ اور کہا، خدا نے میری ملامت چھین لی ہے:\n24۔ اور اس نے اس کا نام یوسف کہا؛ اور کہا، خداوند مجھ میں ایک اور بیٹا شامل کرے گا۔ {جوزف: یعنی، ایڈنگ}\n25۔ اور جب راحیل نے یوسف کو جنم دیا، تو جیکب نے لابان سے کہا، مجھے بھیج دو، تاکہ میں اپنی جگہ اور اپنے ملک جا سکوں۔\n26. میری بیویوں اور بچوں کو دے دو، جن کے لیے میں نے تمہاری خدمت کی ہے، اور مجھے جانے دو: کیونکہ تم جانتے ہو کہ میں نے تمہاری خدمت کیا ہے۔\n27۔ اور لابان نے اس سے کہا، میں تم سے دعا کرتا ہوں، اگر میں نے تمہاری آنکھوں میں عنایت پائی ہے، {رک جاؤ: کیونکہ} میں نے تجربے سے سیکھا ہے کہ خداوند نے مجھے تیری خاطر برکت دی ہے۔\n28۔ اور اس نے کہا، اپنی اجرت مجھے مقرر کرو، اور میں اسے دوں گا۔\n29۔ اور اس نے اس سے کہا، تم جانتے ہو کہ میں نے تمہاری خدمت کیسے کی، اور تمہارے مویشی میرے ساتھ کیسے تھے۔\n30۔ کیونکہ وہ بہت کم تھا جو تمہارے پاس تھا اس سے پہلے کہ میں آیا، اور اب یہ بہت زیادہ ہو گیا ہے؛ اور خداوند نے میرے آنے کے بعد سے تمہیں برکت دی ہے: اور اب میں کب اپنے گھر کا انتظام کروں گا؟ {بڑھا کر: عبوری۔ ٹوٹا ہوا ہے} {چون...: عبرانی۔ میرے قدموں میں}\n31۔ اور اس نے کہا، میں تمہیں کیا دوں؟ اور یعقوب نے کہا، تم مجھے کچھ نہیں دو گے: اگر تم یہ کام میرے لیے کرو گے تو میں دوبارہ تمہارے ریوڑ کو کھلاؤں گا اور رکھوں گا:\n32۔ میں آج تک تمہارے تمام ریوڑ سے گزروں گا، وہاں سے تمام دھبے دار اور دھبے دار مویشی، بھیڑوں کے درمیان تمام بھورے مویشی، اور بکریوں میں سے دھبے دار اور دھبے دار نکالوں گا، اور ان کا میرا اجرت ہوگا۔\n33. اسی طرح میری راستبازی میرے لیے وقت آنے والے وقت میں جواب دے گی، جب وہ تمہارے سامنے میرے اجرت کے لیے آئے گی: ہر وہ جو بکریوں میں دھبے دار اور داغ دار نہیں، اور بھیڑوں میں بھوری ہے، جو میرے ساتھ چوری شدہ شمار کی جائے گی۔ {وقت کے ساتھ...: عبرانی۔ مورو کے لیے}\n34۔ اور لابان نے کہا، دیکھو، کاش یہ تمہارے کلام کے مطابق ہو۔\n35۔ اور اس دن اس نے وہ بکریاں جو رنگ اسٹریک اور دھبے دار تھیں، اور تمام مادہ بکریاں جو دھبے دار اور دھبے دار تھیں، {اور} ہر وہ بکریاں جن میں {کچھ} سفید تھیں، اور بھیڑوں میں سے تمام بھوری بھیڑوں کو ہٹا دیا، اور انہیں اپنے بیٹوں کے ہاتھ میں دے دیا۔\n36۔ اور اس نے اپنے اور یعقوب کے درمیان تین دن کا سفر طے کیا: اور یعقوب نے لابن کے باقی ریوڑ کو کھلایا۔\n37۔ اور یعقوب نے اسے سبز پاپلر کی چھڑیاں اور ہیزل اور شطرنج کے درخت کے لیے؛ اور ان میں سفید پٹیاں لگا کر، اور وہ سفید دکھایا جو راڈز میں موجود تھا۔\n38۔ اور اس نے وہ چھڑیاں جو اس نے ریوڑوں کے سامنے رکھی تھیں، جب ریوڑ پانی پینے کے لیے نالیوں میں رکھی تھیں، تاکہ جب وہ پینے آئیں تو حاملہ ہو جائیں۔\n39۔ اور ریوڑوں نے چھڑیوں کے سامنے حاملہ ہو کر مویشی پیدا کیے، جو رنگ اسٹریک، دھبے دار اور دھبے دار تھے۔\n40۔ اور یعقوب نے بھیڑوں کو الگ کیا، اور ریوڑوں کے چہرے رنگ اسٹریک والے کی طرف رکھے، اور لابان کے ریوڑ کے تمام بھورے بھیڑ کی طرف رکھا؛ اور اس نے اپنے ریوڑ خود ہی رکھے، اور انہیں لابان کے مویشیوں کے لیے نہیں رکھا۔\n41۔ اور جب بھی طاقتور مویشی حاملہ ہوئے، یعقوب نے گالیوں میں مویشیوں کی آنکھوں کے سامنے چھڑیاں رکھ دیں تاکہ وہ لاٹھیوں کے درمیان حاملہ ہو سکیں۔\n42۔ لیکن جب مویشی کمزور ہو گئے، تو اس نے انہیں شامل نہیں کیا: اسی طرح لابان کے کمزور تھے، اور مضبوط یعقوب کے۔\n43۔ اور اس آدمی نے بہت زیادہ ترقی کی، اس کے پاس بہت سا مویشی، خادم، نوکر، اونٹ اور گدھے تھے۔","1۔ اور اس نے لابان کے بیٹوں کے الفاظ سنے، کہ یعقوب نے ہمارے باپ کی سب کچھ چھین لی ہے؛ اور اس {وہ} سے جو {تھا} ہمارے والد کا تھا، اسے یہ ساری شان ملی۔\n2۔ اور یعقوب نے لابان کا چہرہ دیکھا، اور دیکھو، وہ اس کے لیے پہلے جیسا نہیں تھا۔ {جیسا کہ پہلے تھا: عبرانی۔ جیسے کل اور اس سے پہلے کے دن}\n3۔ اور خداوند نے یعقوب سے کہا، اپنے باپ اجداد کی زمین اور اپنے رشتہ داروں کی طرف واپس آؤ؛ اور میں تمہارے ساتھ ہوں گا۔\n4۔ اور یعقوب نے راحیل اور لیاہ کو اپنے ریوڑ کے لیے میدان میں بلایا،\n5۔ اور میں نے ان سے کہا، میں تمہارے والد کا چہرہ دیکھ رہا ہوں، کہ وہ میرے لیے پہلے جیسا نہیں ہے؛ لیکن میرے والد کا خدا میرے ساتھ ہے۔\n6۔ اور تم جانتے ہو کہ میں نے اپنی پوری طاقت سے تمہارے والد کی خدمت کی ہے۔\n7۔ اور تمہارے والد نے مجھے دھوکہ دیا، اور میری تنخواہ دس بار بدل دی؛ لیکن خدا نے اسے اجازت دی کہ وہ مجھے تکلیف نہ دے۔\n8۔ اگر اس نے ایسا کہا، تو دھبے دار تمہاری اجرت ہوں گے؛ تو تمام مویشی ننگا ہو گئے: اور اگر وہ ایسا کہے، تو رنگ اسٹریکڈ تمہارا اجرت ہوگا؛ پھر تمام مویشیوں کو رنگ اسٹریک کر کے ننگا کر دیا گیا۔\n9۔ یوں خدا نے تمہارے باپ کے مویشی لے لیے اور مجھے دے دیے۔\n10۔ اور جب مویشیوں نے حاملہ ہوا تو میں نے اپنی آنکھیں اٹھائیں، اور خواب میں دیکھا، اور دیکھو، وہ مینڈھے جو مویشیوں پر چھلانگ لگا رہے تھے، انگوٹھی، دھبے دار اور خوفناک تھے۔ {مینڈے: یا، وہ بکریاں کرتا ہے}\n11۔ اور خدا کے فرشتے نے خواب میں مجھ سے کہا، {کہا}، یعقوب: اور میں نے کہا، میں یہاں ہوں۔\n12۔ اور اس نے کہا، اب اپنی آنکھیں اٹھاؤ، اور دیکھو، وہ سب مینڈھے جو مویشیوں پر چھلانگ لگاتے ہیں، انگوٹھی، دھبے دار اور ریشے دار ہیں: کیونکہ میں نے وہ سب کچھ دیکھا ہے جو لابان تمہارے ساتھ کرتا ہے۔\n13. میں بیت ال کا خدا ہوں، جہاں تم نے ستون مسح کیا، اور جہاں تم نے مجھ سے قسم کھائی: اب اٹھو، اس زمین سے نکل جاؤ، اور اپنے رشتہ داروں کی سرزمین میں واپس جاؤ۔\n14۔ اور راحیل اور لیاہ نے جواب دیا اور اس سے کہا، {کیا ابھی تک ہمارے والد کے گھر میں ہمارے لیے کوئی حصہ یا وراثت ہے؟'\n15. کیا ہم اس کے اجنبی نہیں ہیں؟ کیونکہ اس نے ہمیں بیچ دیا ہے، اور ہمارا پیسہ بھی نگل لیا ہے۔\n16۔ خدا نے جو دولت ہمارے باپ سے لی ہے، جو ہماری اور ہمارے بچوں کی ہے، اس کے لیے جو بھی خدا نے تم سے کہا ہے، وہ کرو۔\n17۔ پھر یعقوب اٹھا اور اپنے بیٹوں اور بیویوں کو اونٹوں پر بٹھایا؛\n18۔ اور اس نے اپنے تمام مویشی اور جو کچھ اس نے حاصل کیا تھا، جو اس نے پادانارم میں حاصل کیا تھا، لے گیا تاکہ وہ اپنے والد اسحاق کے پاس کنعان کی سرزمین پر جا سکے۔\n19۔ اور لابان اپنی بھیڑیں کاٹنے گیا: اور راحیل نے وہ تصویریں چرا لی تھیں جو اس کے والد کی تھیں۔ {تصاویر: عبرانی۔ ٹیرافیم}\n20۔ اور یعقوب اچانک لابان شامی کے پاس چلا گیا، اس نے اسے بتایا کہ وہ فرار نہیں ہوا۔ {بے خبر...: عببرانی۔ لابان کا دل}\n21۔ تو وہ اپنی پوری طاقت کے ساتھ بھاگ گیا؛ اور وہ اٹھا، دریا کے اوپر سے گزرا، اور اپنا چہرہ جبل جلعاد کی طرف موڑ لیا۔\n22۔ اور تیسرے دن لابان کو بتایا گیا کہ یعقوب فرار ہو گیا ہے۔\n23۔ اور اس نے اپنے بھائیوں کو ساتھ لے کر سات دن کا سفر کیا؛ اور انہوں نے اسے جبل جلعاد میں پیچھے چھوڑ دیا۔\n24۔ اور خدا رات کو خواب میں لابان سریانی کے پاس آیا اور اسے کہا، \"خبردار رہو کہ تم یعقوب سے نہ اچھے سے بات کرو نہ برا۔ {یا تو...: عبرانی۔ اچھے سے برے تک}\n25۔ پھر لابان نے یعقوب کو پیچھے چھوڑ دیا۔ اب یعقوب نے پہاڑ میں اپنا خیمہ لگا دیا تھا: اور لابان اپنے بھائیوں کے ساتھ گلعاد کے پہاڑ میں لگا رہا تھا۔\n26۔ اور لابان نے یعقوب سے کہا، تم نے کیا کیا ہے کہ تم نے مجھے بے خبری میں چرا لیا، اور میری بیٹیوں کو تلوار کے ساتھ قیدی بنا کر اغوا کر لیا؟\n27۔ کیوں تم چپکے سے بھاگ گئے اور مجھ سے چھپ گئے؟ اور کیا تم نے مجھے نہیں بتایا کہ میں تمہیں خوشی، گیتوں، تابریٹ اور ہارپ کے ساتھ بھیج سکتا ہوں؟ {چوری کرو...: عبوری۔ مجھے چرا لیا ہے}\n28۔ اور کیا تم نے مجھے اپنے بیٹوں اور بیٹیوں کو بوسہ دینے کی اجازت نہیں دی؟ اب تم نے بے وقوفی سے ایسا کیا ہے۔\n29۔ یہ میرے ہاتھ کی طاقت میں ہے کہ میں تمہیں تکلیف پہنچاؤں: لیکن تمہارے باپ کے خدا نے کل رات مجھ سے کہا، \"خبردار ہو کہ تم یعقوب سے نہ اچھی بات کرو نہ برا۔\n30۔ اور اب، {اگرچہ} تم جانا چاہتے ہو، کیونکہ تم اپنے والد کے گھر کے لیے ترس رہے تھے، {لیکن} تم نے میرے دیوتاؤں کو کیوں چرا لیا؟\n31۔ اور یعقوب نے جواب دیا اور لابان سے کہا، کیونکہ میں ڈرتا تھا: کیونکہ میں نے کہا، شاید تم اپنی بیٹیوں کو زبردستی مجھ سے چھین لو۔\n32۔ جس کے ساتھ تم اپنے معبودوں کو پاؤ گے، اسے زندہ نہ رہنے دو: اس سے پہلے کہ ہمارے بھائیوں یہ پہچان لو کہ میرے پاس کیا ہے، اور اسے اپنے پاس لے لو۔ کیونکہ جیکب نہیں جانتا تھا کہ ریچل نے انہیں چرا لیا تھا۔\n33۔ اور لابان یعقوب کے خیمے میں گیا، پھر لیہ کے خیمے میں، اور دو خادماؤں کے خیموں میں داخل ہوا؛ لیکن انہوں نے انہیں نہیں پایا۔ پھر وہ لیا کے خیمے سے باہر نکلا اور ریچل کے خیمے میں داخل ہوا۔\n34۔ اب راحیل نے مجسمے لے کر اونٹ کے فرنیچر میں رکھ دیے اور ان پر بیٹھ گئی۔ اور لابان نے تمام خیمے تلاش کیے، لیکن {ان} نہیں ملے۔ {تلاش کیا: عبرانی۔ فیلٹ}\n35۔ اور اس نے اپنے والد سے کہا، میرے آقا کو یہ پسند نہ آئے کہ میں تمہارے سامنے نہیں اٹھ سکتی؛ کیونکہ عورتوں کی رسم میرے اوپر ہے۔ اور اس نے تلاش کیا، لیکن تصاویر نہیں ملیں۔\n36۔ اور یعقوب غصے میں آ گیا، اور لبان سے محبت کرنے لگا: اور یعقوب نے جواب دیا اور لابان سے کہا، میری غلطی کیا ہے؟ میرا گناہ کیا ہے، جو تم نے میرے پیچھے اتنی شدت سے پیچھا کیا؟\n37۔ جب تم نے میرا سارا سامان تلاشی لیا، تو تم نے اپنے سارے گھریلو سامان میں سے کیا پایا؟ یہاں میرے بھائیوں اور تمہارے بھائیوں کے سامنے رکھو، تاکہ وہ ہمارے درمیان فیصلہ کر سکیں۔ {تلاش شدہ: عبوری۔ فیلٹ}\n38۔ یہ بیس سال {میں} میں نے {تمہارے ساتھ گزارا}؛ تمہاری بھیڑیں اور تمہاری بکریوں نے اپنے بچے نہیں چھوڑے، اور تمہارے ریوڑ کے مینڈھے میں نے نہیں کھایا۔\n39۔ جو کچھ جانوروں سے پھٹا گیا، میں نے تمہارے پاس نہیں لایا؛ میں اس کے نقصان کو برداشت کرتا ہوں؛ تمہیں میرے ہاتھ کی ضرورت تھی، {چاہے}دن میں چوری کی گئی ہو، یا رات میں چرائی گئی ہو۔\n40۔ {یہ} میں تھا؛ دن میں خشک سالی نے مجھے نگل لیا، اور رات کو سردی نے بھی؛ اور میری نیند میری آنکھوں سے چلی گئی۔\n41. یوں میں بیس سال سے تمہارے گھر میں ہوں؛ میں نے تمہاری دو بیٹیوں کے لیے چودہ سال خدمت کی، اور تمہارے مویشیوں کے لیے چھ سال: اور تم نے میری اجرت دس گنا بدل دی۔\n42. اگر میرے والد کا خدا، ابراہیم کا خدا، اور اسحاق کا خوف میرے ساتھ نہ ہوتا، تو یقینا تم نے مجھے اب خالی بھیج دیا ہوتا۔ خدا نے میری تکلیف اور میرے ہاتھوں کی محنت دیکھی ہے، اور کل رات تمہیں ڈانٹا ہے۔\n43۔ اور لابان نے جواب دیا اور یعقوب سے کہا، {یہ} بیٹیاں {ہیں} میری بیٹیاں، اور {یہ} بچے {ہیں} میرے بچے ہیں، اور {یہ} مویشی {ہیں} میرے مویشی ہیں، اور جو کچھ تم دیکھتے ہو {میرا} ہے: اور آج میں ان بیٹیوں یا ان کے پیدا کردہ بچوں کے ساتھ کیا کر سکتا ہوں؟\n44۔ اب آؤ، آؤ ہم ایک عہد کریں، میں اور تم؛ اور یہ میرے اور تمہارے درمیان گواہی کے لیے ہو۔\n45۔ اور یعقوب نے ایک پتھر لیا، اور اسے ایک ستون کے طور پر لگا دیا۔\n46۔ اور یعقوب نے اپنے بھائیوں سے کہا، پتھر جمع کرو؛ انہوں نے پتھر لیے، اور ڈھیر بنایا: اور وہاں ڈھیر پر کھایا۔\n47۔ اور لابان نے اسے جگرسادوتھا کہا: لیکن یعقوب نے اسے گلید کہا۔ {جگرسہادوتھا: یعنی، گواہوں کا ڈھیر، کلدی} {گیلد: یعنی، گواہوں کا ڈھیر، عبرانی۔}\n48۔ اور لابان نے کہا، یہ ڈھیر آج میرے اور تمہارے درمیان گواہی ہے۔ اسی لیے اس کا نام گیلید رکھا گیا؛\n49۔ اور مزپاہ؛ کیونکہ اس نے کہا، خداوند میرے اور تیرے درمیان نظر رکھے، جب ہم ایک دوسرے سے غائب ہوں۔ {مزپاہ: یعنی، ایک بیکن، یا، واچ ٹاور}\n50۔ اگر تم میری بیٹیوں کو تکلیف دو، یا اگر تم میری بیٹیوں کے علاوہ {اور} بیویاں لے لو، تو کوئی مرد ہمارے ساتھ نہیں ہوگا؛ دیکھو، خدا میرے اور تمہارے درمیان گواہ ہے۔\n51۔ اور لابان نے یعقوب سے کہا، اس ڈھیر کو دیکھو، اور دیکھو {یہ} ستون، جو میں نے اپنے اور تمہارے درمیان رکھا ہے؛\n52. یہ ڈھیر گواہی دو، اور یہ ستون گواہی دو کہ میں اس ڈھیر کو تم تک نہیں پہنچاؤں گا، اور تم اس ڈھیر اور اس ستون کو میرے لیے نقصان پہنچانے کے لیے نہیں گزرو گے۔\n53۔ ابراہیم کا خدا، اور ناحور کا خدا، ان کے باپ کا خدا، ہمارے درمیان فیصلہ کرتے ہیں۔ اور جیکب اپنے والد اسحاق کے خوف کی قسم کھاتا ہے۔\n54۔ پھر یعقوب نے پہاڑ پر قربانی دی، اور اپنے بھائیوں کو روٹی کھانے کے لیے بلایا، اور انہوں نے روٹی کھائی، اور ساری رات پہاڑ پر ٹھہرے رہے۔ {پیش کیا گیا...: یا، جانوروں کو مارا}\n55۔ اور صبح سویرے لابان اٹھا، اپنے بیٹوں اور بیٹیوں کو بوسہ دیا اور انہیں برکت دی: اور لابان روانہ ہو کر اپنے گھر واپس چلا گیا۔","1۔ اور یعقوب اپنے راستے پر چلا گیا، اور خدا کے فرشتے اس سے ملے۔\n2۔ اور جب یعقوب نے انہیں دیکھا تو اس نے کہا، یہ خدا کی لشکر ہے: اور اس نے اس جگہ کا نام مہانیم رکھا۔ {مہنائم: یعنی، دو لشکر، یا، کیمپ}\n3۔ اور یعقوب نے اپنے بھائی عیسو کے پاس سعیر کے علاقے میں بھیجے جو ایڈوم کا ملک تھا۔ {ملک: عبرانی۔ فیلڈ}\n4۔ اور اس نے انہیں حکم دیا، کہا، یوں تم میرے رب عیسو سے بات کرو گے؛ تمہارا خادم یعقوب یوں کہتا ہے، میں لابان کے ساتھ رہا، اور اب تک وہاں رہا:\n5۔ اور میرے پاس بیل، گدھے، ریوڑ، خادم، اور عورتیں ہیں: اور میں نے اپنے آقا کو بتانے کے لیے بھیجا ہے تاکہ میں آپ کی نظر میں فضل پا سکوں۔\n6۔ اور قاصد یعقوب کے پاس واپس آئے اور کہا، ہم تیرے بھائی عیسو کے پاس آئے ہیں، اور وہ بھی آپ سے ملنے آ رہا ہے، اور اس کے ساتھ چار سو آدمی بھی ہیں۔\n7۔ تب یعقوب بہت خوفزدہ اور پریشان ہوا: اور اس نے اپنے ساتھ موجود لوگوں، ریوڑوں، ریوڑوں اور اونٹوں کو دو گروہوں میں تقسیم کر دیا؛\n8۔ اور کہا، اگر عیسو ایک گروہ کے پاس آ کر اسے مار ڈالے، تو باقی بچا ہوا گروہ فرار ہو جائے گا۔\n9۔ اور یعقوب نے کہا، اے میرے والد ابراہیم کے خدا، اور میرے والد اسحاق کے خدا، وہ خداوند جس نے مجھ سے کہا، اپنے ملک اور اپنے رشتہ داروں کی طرف واپس جاؤ، اور میں تمہارے ساتھ اچھا سلوک کروں گا:\n10۔ میں ان تمام رحمتوں اور تمام سچائی کے لائق نہیں ہوں جو تم نے اپنے خادم کو دکھائی؛ کیونکہ میں نے اپنی چھڑی کے ساتھ اس اردن کو پار کیا؛ اور اب میں دو بینڈز بن چکا ہوں۔ {میں نہیں ہوں...: عبرانی۔ میں سب سے کم ہوں}\n11۔ میں دعا کرتا ہوں کہ مجھے میرے بھائی کے ہاتھوں سے، عیسو کے ہاتھ سے نجات دے، کیونکہ میں اس سے ڈرتا ہوں، کہیں وہ آ کر مجھے نہ مار دے، {اور} ماں اور بچوں کو۔ {ساتھ: عبرانی upon}\n12۔ اور تم نے کہا، میں ضرور تمہارے لیے بھلائی کروں گا، اور تمہاری نسل کو سمندر کی ریت کی طرح بنا دوں گا، جسے کثرت سے گنا نہیں جا سکتا۔\n13۔ اور اسی رات وہاں ٹھہرے؛ اور جو کچھ اس کے ہاتھ میں آیا اس میں سے عیسو کے بھائی کے لیے تحفہ لیا؛\nچودہ۔ دو سو بکریاں، بیس بکریاں، دو سو بھیڑیں اور بیس مینڈے،\n15۔ تیس دودھ دینے والے اونٹ اپنے بچوں کے ساتھ، چالیس کین، اور دس بیل، بیس گدھے، اور دس بچے۔\n16۔ اور اس نے {انہیں} اپنے بندوں کے ہاتھ میں دے دیے، ہر ایک کو اپنی مرضی سے دھکیل دیا گیا؛ اور اپنے خادموں سے کہا، میرے سامنے سے گزر جاؤ، اور ایک فاصلہ رکھ دو اور گاڑی چلاؤں۔\n17۔ اور اس نے سب سے پہلے والے کو حکم دیا، کہا، جب عیسو میرا بھائی تم سے ملے گا اور تم سے پوچھے گا، تم کس کے ہو؟ اور کہاں جا رہے ہو؟ اور یہ تمہارے سامنے کس کے ہیں؟\n18. پھر تم کہو گے، {یہ تمہارے خادم یعقوب کے ہیں}؛ یہ میرے آقا عیسو کے لیے بھیجا گیا تحفہ ہے: اور دیکھو، وہ بھی ہمارے پیچھے ہے۔\n19۔ اور اس نے دوسرے، تیسرے اور ان کے پیچھے آنے والے سب لوگوں کو حکم دیا، کہا، اس طرح تم عیسو سے بات کرو گے جب تم اسے پاؤ گے۔\n20۔ اور مزید کہو، دیکھو، تمہارا خادم یعقوب ہمارے پیچھے ہے۔ کیونکہ اس نے کہا، میں اسے اس تحفے سے خوش کروں گا جو میرے سامنے آئے گا، اور بعد میں اس کا چہرہ دیکھوں گا؛ شاید وہ مجھے قبول کر لے۔ {میرے بارے میں: عبرانی۔ میرا چہرہ}\n21. یوں اس کے سامنے موجود شخص گیا: اور وہ خود اس رات کمپنی میں ٹھہرا۔\n22۔ اور اس رات وہ اٹھ کھڑا ہوا، اپنی دو بیویاں، اپنی دو خادماؤں اور گیارہ بیٹوں کو لے کر جابوک کے پار چلا گیا۔\n23۔ اور اس نے انہیں لیا، ندی کے پار بھیج دیا، اور جو کچھ اس کے پاس تھا بھیج دیا۔ {بھیجا انہیں: عبرانی۔ گزرنے کی وجہ سے}\n24۔ اور یعقوب اکیلا رہ گیا؛ اور وہاں ایک آدمی اس کے ساتھ لڑتا رہا یہاں تک کہ دن کا طلوع ہوا۔ {بریکنگ...: عببرانی۔ صبح کا عروج}\n25۔ اور جب اس نے دیکھا کہ وہ اس پر غالب نہیں آ سکا، تو اس نے اپنی ران کے گڑھے کو چھوا؛ اور جیکب کی ران کا کھوکھلا حصہ بے ربط تھا، جب وہ اس سے لڑ رہا تھا۔\n26۔ اور اس نے کہا، مجھے جانے دو، کیونکہ دن طلوع ہو رہا ہے۔ اور اس نے کہا، میں تمہیں جانے نہیں دوں گا، جب تک تم مجھے برکت نہ دو۔\n27۔ اور اس نے اس سے کہا، تمہارا نام کیا ہے؟ اور اس نے کہا، جیکب۔\n28۔ اور اس نے کہا، تیرا نام اب یعقوب کے سوا نہیں پکارا جائے گا، کیونکہ تم ایک شہزادے کی طرح خدا اور انسانوں کے ساتھ طاقت رکھتے ہو، اور غالب آ گئے ہو۔ {اسرائیل: یعنی، خدا کا شہزادہ}\n29۔ اور یعقوب نے اس سے پوچھا اور کہا، \"مجھے بتاؤ، میں تم سے دعا کرتا ہوں، اپنا نام۔ اور اس نے کہا، کیوں تم میرا نام پوچھتے ہو؟ اور اس نے وہاں اسے برکت دی۔\n30۔ اور یعقوب نے اس جگہ کا نام پینیئل رکھا: کیونکہ میں نے خدا کو آمنے سامنے دیکھا ہے، اور میری زندگی محفوظ رہی۔ {پینیئل: یعنی، خدا کا چہرہ}\n31۔ اور جب وہ پینویل کے اوپر سے گزرا تو سورج اس پر طلوع ہوا، اور وہ اپنی ران پر رک گیا۔\n32. اسی لیے بنی اسرائیل اس ریشے کو نہیں کھاتے جو آج تک ران کے گڑھے پر سکڑ گئی ہے، کیونکہ اس نے یعقوب کی ران کے گڑھے کو اس ریشے میں چھوا جو سکڑ گئی تھی۔","1۔ اور یعقوب نے اپنی آنکھیں اٹھائیں اور دیکھا، اور دیکھتے ہی عیسو آیا، اور اس کے ساتھ چار سو آدمی بھی تھے۔ اور اس نے بچوں کو لیہ، راحیل، اور دونوں خادماؤں میں تقسیم کر دیا۔\n2۔ اور اس نے خادماؤں اور ان کے بچوں کو سب سے آگے رکھا، اور لیہ اور اس کے بچوں کو پیچھے، اور راحیل اور یوسف کو سب سے زیادہ رکاوٹ بنایا۔\n3۔ اور وہ ان کے سامنے سے گزرا، سات بار زمین پر جھکا، یہاں تک کہ اپنے بھائی کے قریب پہنچا۔\n4۔ اور عیسو اس سے ملنے دوڑا، اسے گلے لگا لیا، اس کی گردن پر گر گیا، اور اسے بوسہ دیا، اور وہ روئے۔\n5۔ اور اس نے اپنی آنکھیں اٹھائیں، اور عورتوں اور بچوں کو دیکھا؛ اور کہا، وہ لوگ کون ہیں جو تمہارے ساتھ ہیں؟ اور اس نے کہا، وہ بچے جو خدا نے تمہارے خادم کو مہربانی سے دیے ہیں۔ {ساتھ...: عبوری۔ تمہارے لیے}\n6۔ پھر خادمائیں قریب آئیں، وہ اور ان کے بچے، اور انہوں نے جھک کر سلام کیا۔\n7۔ اور لیہ بھی اپنے بچوں کے ساتھ قریب آئی، اور جھک گئی، اور اس کے بعد یوسف اور ریحیل قریب آئے، اور انہوں نے جھک کر سلام کیا۔\n8۔ اور اس نے کہا، تم نے اس سب سے برا کیا کہا جس سے میں ملا؟ اور اس نے کہا، {یہ} میرے رب کی نظر میں فضل پانے کے لیے ہیں۔ {کیا...: عبرانی۔ یہ سارا بینڈ تمہارے لیے کیا ہے؟}\n9۔ اور عیسو نے کہا، میرے بھائی، میرے پاس کافی ہے؛ جو تمہارے پاس ہے اسے اپنے پاس رکھو۔ {برقرار رکھو...: عبوری۔ یہ تمہارے لیے ہو}\n10۔ اور یعقوب نے کہا، نہیں، میں تم سے درخواست کرتا ہوں، اگر اب میں نے تمہاری نظر میں فضل پا لیا ہے تو میرا تحفہ میرے ہاتھ میں لے لو، کیونکہ اس لیے میں نے تمہارا چہرہ دیکھا ہے، جیسے میں نے خدا کا چہرہ دیکھا ہو، اور تم مجھ سے خوش تھے۔\n11. میں تم سے دعا کرتا ہوں کہ میری برکت جو تمہیں دی گئی ہے، قبول کرو؛ کیونکہ خدا نے میرے ساتھ مہربانی کی ہے، اور کیونکہ میرے پاس کافی ہے۔ اور اس نے اسے زور دیا، اور اس نے اسے لے لیا۔ {کافی: عبرانی۔ تمام باتیں}\n12۔ اور اس نے کہا، آؤ اپنا سفر کریں، اور چلیں، اور میں تمہارے سامنے جاؤں گا۔\n13۔ اور اس نے اس سے کہا، میرے آقا جانتے ہیں کہ بچے نرم دل ہیں، اور ریوڑ اور بچے میرے ساتھ ہیں: اور اگر ایک دن لوگ انہیں شکست دے دیں تو سارا ریوڑ مر جائے گا۔\n14۔ میرے رب، میں آپ سے درخواست کرتا ہوں، اپنے خادم کے سامنے گزر جائے: اور میں نرمی سے آگے بڑھوں گا، جیسے وہ مویشی جو میرے اور بچوں کے سامنے آتے ہیں، برداشت کر سکیں، جب تک کہ میں اپنے رب کے پاس سیئر نہ آ جاؤں۔ {مطابق...: عبرانی کام کے پاؤں کے مطابق وغیرہ، اور بچوں کے پاؤں کے مطابق\n15۔ اور عیسو نے کہا، اب میں تمہارے ساتھ {کچھ} لوگوں کو چھوڑ دوں جو میرے ساتھ ہیں۔ اور اس نے کہا، اس کی کیا ضرورت ہے؟ مجھے اپنے رب کی نظر میں فضل تلاش کرنے دو۔ {چھوڑیں: عبرانی۔ سیٹ، یا، پلیس} {کیا...: عبرانی یہ کیوں ہے؟}\n16۔ تو عیسو اسی دن واپس آیا، راستے میں سعیر۔\n17۔ اور یعقوب سکوتھ گیا، اس کے لیے ایک گھر بنایا، اور اپنے مویشیوں کے لیے بوتھ بنائے۔ اسی لیے اس جگہ کا نام سکوتھ ہے۔ {سکوٹھ: یعنی، بوتھس}\n18۔ اور یعقوب شلم آیا، جو شیکم کا ایک شہر ہے، جو کنعان کی سرزمین میں ہے، جب وہ پڈانارم سے آیا؛ اور شہر کے سامنے اپنا خیمہ لگایا۔ {شیکیم: گریڈ سیکیم}\n19۔ اور اس نے ایک کھیت کا ٹکڑا خریدا، جہاں اس نے اپنا خیمہ لگایا تھا، حامور کے بچوں کے ہاتھوں سو پیسوں کے بدلے۔ {ہیمور: گریڈ ایمور} {ٹکڑے...: یا، بھیڑیں}\n20۔ اور اس نے وہاں ایک قربان گاہ تعمیر کی، اور اسے ایللوہے اسرائیل کا نام دیا۔ {ایلوہی-اسرائیل: وہ ہے خدا، اسرائیل کا خدا}","1۔ اور دینا لیاح کی بیٹی، جسے اس نے یعقوب کے حوالے کیا، زمین کی بیٹیوں سے ملنے نکلی۔\n2۔ اور جب حامور حویوی کے بیٹے شیخم، جو ملک کا شہزادہ تھا، نے اسے دیکھا، تو اسے لے گیا، اس کے ساتھ لیٹ گیا اور اسے ناپاک کر دیا۔ {ناپاک...: عبرانی۔ اسے عاجز کیا}\n3۔ اور اس کی روح نے یعقوب کی بیٹی دینا سے محبت کی، اور اس نے اس دوشیزہ سے محبت کی، اور اس سے مہربانی کی۔ {مہربانی سے...: عبرانی۔ دوشیزہ کے دل تک}\n4۔ اور شیکم نے اپنے والد حمور سے کہا، \"مجھے یہ دوشیزہ بیوی دے دو۔\n5۔ اور یعقوب نے سنا کہ اس نے اپنی بیٹی دینا کو ناپاک کر دیا ہے: اب اس کے بیٹے اپنے مویشیوں کے ساتھ کھیت میں تھے، اور یعقوب خاموش رہا جب تک وہ آ نہ گئے۔\n6۔ اور حمور، شیکم کا باپ، یعقوب کے پاس گیا تاکہ اس سے رابطہ کرے۔\n7۔ اور یعقوب کے بیٹے میدان سے باہر آئے جب انہوں نے یہ سنا: اور لوگ غمگین اور بہت غصے میں آ گئے، کیونکہ اس نے اسرائیل میں بے وقوفی کی تھی جب وہ یعقوب کی بیٹی کے ساتھ لیٹ گیا تھا؛ جو کام نہیں کرنا چاہیے۔\n8۔ اور حمور نے ان سے بات کی اور کہا، میرے بیٹے شیکم کی روح تمہاری بیٹی کے لیے ترس رہی ہے: میں دعا کرتا ہوں کہ تم اسے بیوی کے طور پر دے دو۔\n9۔ اور ہم سے شادی کرو، {اور} اپنی بیٹیاں ہمیں دو، اور ہماری بیٹیوں کو اپنے پاس لے جاؤ۔\n10۔ اور تم ہمارے ساتھ رہو گے: اور زمین تمہارے سامنے ہوگی؛ وہاں رہو اور تجارت کرو، اور اپنی چیزیں وہاں حاصل کرو۔\n11۔ اور شیکم نے اپنے باپ اور اپنے بھائیوں سے کہا، مجھے تمہاری آنکھوں میں فضل تلاش کرنے دو، اور جو تم مجھ سے کہو گے وہ میں دوں گا۔\n12۔ مجھ سے کبھی زیادہ جہیز اور تحفہ نہ مانگو، اور میں ویسا ہی دوں گا جیسا تم مجھ سے کہو گے: لیکن مجھے دوشیزہ کو بیوی کے حوالے کر دو۔\n13۔ اور یعقوب کے بیٹوں نے شیکم اور حمور اپنے باپ کو دھوکہ دے کر جواب دیا، اور کہا، کیونکہ اس نے ان کی بہن دینا کو ناپاک کیا تھا:\n14۔ اور انہوں نے ان سے کہا، ہم یہ کام نہیں کر سکتے کہ اپنی بہن کو ایک غیر ختنہ شدہ کو دے دیں؛ اس لیے کہ وہ ہمارے لیے ملامت تھے:\n15۔ لیکن اس میں ہم آپ کو رضامند کریں گے: اگر آپ ہماری طرح بننا چاہیں تو آپ میں سے ہر مرد کا ختنہ ہو جائے؛\n16۔ پھر ہم اپنی بیٹیاں تمہیں دیں گے، اور تمہاری بیٹیوں کو اپنے پاس لے جائیں گے، اور تمہارے ساتھ رہیں گے، اور ہم ایک قوم بن جائیں گے۔\n17۔ لیکن اگر تم ہماری بات نہیں سنو گے تو ختنہ ہو جاؤ؛ پھر ہم اپنی بیٹی کو لے جائیں گے، اور ہم چلے جائیں گے۔\n18۔ اور ان کے الفاظ حمور اور شیکم حامور کے بیٹے کو خوش کر گئے۔\n19۔ اور نوجوان نے یہ کام کرنے سے گریز کیا، کیونکہ اسے یعقوب کی بیٹی سے خوشی تھی: اور وہ اپنے والد کے تمام گھرانے سے زیادہ معزز تھا۔\n20۔ اور اس کا بیٹا حامور اور شیکم اپنے شہر کے دروازے پر آئے اور اپنے شہر کے لوگوں سے بات چیت کی، کہا،\n21. یہ لوگ ہمارے ساتھ امن کے طور پر ہیں؛ لہٰذا انہیں زمین میں رہنے دو، اور وہاں تجارت کرنے دو؛ کیونکہ زمین، دیکھو، یہ ان کے لیے کافی وسیع ہے؛ آئیے ہم ان کی بیٹیوں کو بیویاں بنا لیں، اور انہیں اپنی بیٹیاں دیں۔\n22. صرف یہاں مرد ہمیں ہمارے ساتھ رہنے کے لیے رضامند ہوں گے، ایک قوم بننے کے لیے، اگر ہم میں سے ہر مرد ختنہ شدہ ہو، جیسا کہ وہ ختنہ شدہ ہیں۔\n23. کیا ان کا مویشی، مال اور ان کا ہر جانور ہمارا نہیں ہوگا؟ صرف ہمیں ان کی رضامندی دیں، اور وہ ہمارے ساتھ رہیں گے۔\n24۔ اور اس کے بیٹے حمور اور شیکم کی طرف اس کے شہر کے دروازے سے نکلنے والے سب کچھ سننے لگا؛ اور ہر مرد کا ختنہ کیا گیا، جو اس کے شہر کے دروازے سے باہر جاتا تھا۔\n25۔ اور تیسرے دن، جب وہ ناراض تھے، ایسا ہوا کہ یعقوب کے دو بیٹے، شمعون اور لاوی، جو دینا کے بھائیوں تھے، نے ہر آدمی کی تلوار لے کر شہر پر بہادری سے حملہ کیا اور تمام مردوں کو قتل کر دیا۔\n26۔ اور انہوں نے حمور اور اس کے بیٹے کو تلوار کی نوک سے قتل کر دیا، اور دینا کو شیکم کے گھر سے نکال کر باہر نکل گئے۔ {ایج: عبوری۔ منہ}\n27۔ یعقوب کے بیٹے مارے گئے اور شہر کو لوٹا دیا، کیونکہ انہوں نے اپنی بہن کو ناپاک کیا تھا۔\n28۔ انہوں نے اپنی بھیڑیں، بیل اور گدھا، اور شہر میں جو کچھ تھا اور کھیت میں جو کچھ تھا، اسے لے لیا،\n29۔ اور ان کی ساری دولت، ان کے تمام چھوٹے بچے اور ان کی بیویوں نے انہیں قید کر لیا، اور گھر میں موجود سب کچھ بھی برباد کر دیا۔\n30۔ اور یعقوب نے شمعون اور لاوی سے کہا، تم نے مجھے اس لیے پریشان کیا ہے کہ میں اس سرزمین کے باشندوں، کنعانیوں اور پریزیوں میں بدبو دار بنا دوں؛ اور چونکہ میں تعداد میں کم ہوں، وہ میرے خلاف جمع ہو کر مجھے قتل کر دیں گے؛ اور میں تباہ ہو جاؤں گا، میں اور میرا گھر۔\n31۔ اور انہوں نے کہا، کیا اسے ہماری بہن کے ساتھ بدکار عورت کی طرح برتاؤ کرنا چاہیے؟","1۔ اور خدا نے یعقوب سے کہا، اٹھو، بیٹھل جا کر وہاں رہو، اور وہاں خدا کے لیے ایک قربان گاہ بنا دو، جو تمہیں اس وقت نظر آئی جب تم اپنے بھائی عیسو کے چہرے سے دور ہوئے۔\n2۔ پھر یعقوب نے اپنے گھرانے اور اس کے ساتھ موجود سب لوگوں سے کہا، اپنے درمیان موجود عجیب دیوتاؤں کو چھوڑ دو، پاک ہو جاؤ اور اپنے کپڑے بدل لو:\n3۔ اور آؤ اٹھیں، اور بیت ال کی طرف جائیں؛ اور میں وہاں خدا کے لیے ایک قربان گاہ بناؤں گا، جس نے میرے مصیبت کے دن مجھے جواب دیا، اور جس راستے میں میں گیا وہ میرے ساتھ تھا۔\n4۔ اور انہوں نے یعقوب کو وہ تمام عجیب دیوتا دے دیے جو {تھے} ان کے ہاتھ میں، اور {ان کے} بالیاں جو {تھے} ان کے کانوں میں؛ اور یعقوب نے انہیں بلوط کے درخت کے نیچے چھپا دیا جو {شیکیم} نے بنایا تھا۔\n5۔ اور وہ روانہ ہوئے: اور خدا کا خوف ان شہروں پر چھا گیا جو ان کے ارد گرد تھے، اور انہوں نے یعقوب کے بیٹوں کا پیچھا نہیں کیا۔\n6۔ تو یعقوب لوز آیا، جو {ہے} کنعان کی سرزمین میں، یعنی {ہے} بیت ایل، وہ اور وہ سب لوگ جو {اس کے ساتھ} تھے۔\n7۔ اور اس نے وہاں ایک قربان گاہ بنائی، اور اس جگہ کا نام ایل بیت ایل رکھا: کیونکہ وہاں خدا اس پر ظاہر ہوا، جب وہ اپنے بھائی کے سامنے سے بھاگا۔ {ایل بیتھل: یعنی، بیت ھل کا خدا}\n8۔ لیکن دبورہ ربیکا کی آیا فوت ہو گئی، اور اسے بیت ھل کے نیچے ایک بلوط کے درخت کے نیچے دفن کیا گیا: اور اس کا نام ایلونباخوت رکھا گیا۔ {الونباچوتھ: یعنی، رونے کا بلوط}\n9۔ اور خدا نے یعقوب کو دوبارہ ظاہر کیا، جب وہ پڈانارم سے باہر آیا، اور اسے برکت دی۔\n10۔ اور خدا نے اسے کہا، تیرا نام یعقوب ہے: تیرا نام اب یعقوب نہیں پکارا جائے گا، بلکہ اسرائیل تیرا نام ہوگا، اور اس نے اپنا نام اسرائیل رکھا۔\n11۔ اور خدا نے اس سے کہا، میں {ہوں} خدا قادر مطلق: پھل دار ہو اور بڑھو؛ ایک قوم اور قوموں کی جماعت تمہاری طرف سے ہوں گی، اور بادشاہ تمہاری کمر سے نکلیں گے؛\n12۔ اور وہ زمین جو میں نے ابراہیم اور اسحاق کو دی، وہ تمہیں دوں گا، اور تمہاری نسل کو تمہارے بعد زمین دوں گا۔\n13۔ اور خدا اس جگہ سے اوپر گیا جہاں اس نے اس سے بات کی۔\n14۔ اور یعقوب نے اس جگہ ایک ستون لگایا جہاں وہ اس سے بات کر رہا تھا، {حتیٰ کہ} ایک پتھر کا ستون بھی، اور اس پر شراب کی قربانی ڈالی، اور اس پر تیل ڈالا۔\n15۔ اور یعقوب نے اس جگہ کا نام رکھا جہاں خدا نے اس سے بات کی، بیت ایل۔\n16۔ اور وہ بیت ایل سے روانہ ہوئے؛ اور ایفرات تک پہنچنے کے لیے صرف تھوڑا سا فاصلہ تھا: اور ریحیل نے سخت محنت کی، اور اسے سخت محنت کرنی پڑی۔ {تھوڑا سا...: عبرانی۔ ایک چھوٹا سا زمین کا ٹکڑا}\n17۔ اور جب وہ سخت زچگی میں تھیں، تو دائی نے ان سے کہا، خوف نہ کرو؛ تمہیں یہ بیٹا بھی ملے گا۔\n18۔ اور جب اس کی روح رخصت ہو رہی تھی (کیونکہ وہ مر گئی) تو اس نے اس کا نام بینونی رکھا: لیکن اس کے والد نے اسے بنیامین کہا۔ {بینونی: یعنی، میرے غم کا بیٹا} {بینجمن: یعنی، دائیں ہاتھ کا بیٹا}\n19۔ اور راحیل مر گئی، اور ایفرات کے راستے میں دفن کی گئی، جو بیت لحم ہے۔\n20۔ اور یعقوب نے اس کی قبر پر ایک ستون رکھا: جو آج تک ریحیل کی قبر کا ستون ہے۔\n21۔ اور اسرائیل روانہ ہوا اور اپنا خیمہ ایدار کے مینار کے پار پھیلایا۔\n22۔ اور جب اسرائیل اس سرزمین میں آباد ہوا، تو روبن اپنے والد کی کنیز بلحہ کے ساتھ سو گیا: اور اسرائیل نے سنا۔ اب یعقوب کے بیٹے بارہ سال کے تھے:\n23۔ لیہ کے بیٹے؛ روبن، یعقوب کا پہلا بیٹا، اور شمعون، اور لاوی، اور یہوداہ، اور عیساکر، اور زبولون:\n24۔ ریچل کے بیٹے؛ جوزف، اور بینجمن:\n25۔ اور بلحا کے بیٹے، راحیل کی خادمہ؛ ڈین، اور نفتالی:\n26۔ اور زلپا کے بیٹے، لیہ کی خادم؛ گاد، اور آشر: یہ یعقوب کے بیٹے ہیں، جو اسے پدانارام میں پیدا ہوئے۔\n27۔ اور یعقوب اپنے والد اسحاق کے پاس مامرے، شہر اربہ آیا، جو کہ ہبرون ہے، جہاں ابراہیم اور اسحاق قیام کرتے تھے۔\n28۔ اور اسحاق کے دن ایک سو چولیس سال تھے۔\n29۔ اور اسحاق نے بھوت کو چھوڑ دیا، اور مر گیا، اور اپنے لوگوں کے پاس جمع ہو گیا، {بوڑھا} اور دنوں سے بھرا ہوا: اور اس کے بیٹوں عیسو اور یعقوب نے اسے دفن کیا۔","1. اب یہ عیسو کی نسلیں ہیں، جو ادم ہے۔\n2۔ عیسو نے کنعان کی بیٹیوں کی اپنی بیویوں کو لیا؛ آداہ، ایلون دی ہٹی کی بیٹی، اور اہولیبامہ، عناہ کی بیٹی، زبیعون دی ہیوی کی بیٹی؛\n3۔ اور بشمعت اسماعیل کی بیٹی، نباجوت کی بہن۔ {باشمتھ: یا، مہالات}\n4۔ اور عدہ عیسو الیفاز کے لیے پیدا ہوئی؛ اور باشمتھ بیئر روئیل؛\n5۔ اور اہولیبامہ نے یسوع، جلم، اور قارح کو جنم دیا: یہ عیسو کے بیٹے ہیں، جو کنعان کی سرزمین میں اس کے ہاں پیدا ہوئے۔\n6۔ اور عیسو نے اپنی بیویاں، بیٹے، بیٹیاں، اپنے گھر کے تمام جانور، مویشی، تمام جانور اور اپنی تمام دولت لے لی، جو اسے کنعان کی زمین سے ملی تھی؛ اور اپنے بھائی جیکب کے سامنے دیہات میں داخل ہوا۔ {افراد: عبرانی۔ روحیں}\n7۔ کیونکہ ان کی دولت اس سے زیادہ تھی کہ وہ ایک ساتھ رہ سکیں؛ اور وہ زمین جہاں وہ اجنبی تھے، اپنے مویشیوں کی وجہ سے انہیں برداشت نہیں کر سکتی تھی۔\n8۔ یوں عیسو کوہ سعیر میں رہتا تھا: عیسو {ہے} ادوم۔\n9۔ اور یہ عیسو کی نسلیں ہیں، جو پہاڑ سعیر میں ایڈومیوں کے والد تھے: {ایڈومی: عبرانی۔ ایڈوم}\n10۔ یہ عیسو کے بیٹوں کے نام ہیں؛ الیفاز، عدہ کا بیٹا، عیسو کی بیوی، ریوئیل، بشمتھ کا بیٹا، عیسو کی بیوی۔\n11۔ اور الیفاز کے بیٹے تیمان، عمر، زیفو، گاتم اور کناز تھے۔ {زیفو: یا، زیفی}\n12۔ اور تیمنا الیفاز عیسو کے بیٹے کی کنیز تھی؛ اور اس نے الیفاز عمالیق کو جنم دیا: یہ لوگ عدہ عیسو کی بیوی کے بیٹے تھے۔\n13۔ اور یہ {ہیں} رئیل کے بیٹے؛ نہات، زراح، شماہ اور مزہ: یہ باشمتھ عیسو کی بیوی کے بیٹے تھے۔\n14۔ اور یہ احولیبامہ کے بیٹے تھے، جو عناہ کی بیٹی تھی جو زبعون کی بیٹی تھی، عیسو کی بیوی، اور اس نے عیسو، یسوع، یعلم، اور قورح کو جنم دیا۔\n15۔ یہ عیسو کے بیٹوں کے ڈیوک تھے: الیفاز کے بیٹے جو عیسو کا پہلا بیٹا تھا؛ ڈیوک تیمان، ڈیوک عمر، ڈیوک زیفو، ڈیوک کیناز،\n16۔ ڈیوک کورح، ڈیوک گاتم، {اور} ڈیوک امالیک: یہ {ہیں} وہ ڈیوک {جو الیفاز کے زمین ادوم میں آئے تھے}؛ یہ {تھے} آداہ کے بیٹے۔\n17. اور یہ ریوئل عیسو کے بیٹے ہیں؛ ڈیوک نہات، ڈیوک زراہ، ڈیوک شماہ، ڈیوک مزہ: یہ {ہیں} وہ ڈیوک {جو ریویل کے زمین ایڈوم میں آئے تھے}؛ یہ بشیمتھ عیسو کی بیوی کے بیٹے ہیں۔\n18۔ اور یہ احولیبامہ عیسو کی بیوی کے بیٹے ہیں؛ ڈیوک یسوع، ڈیوک جلم، ڈیوک کورح: یہ {تھے} وہ دوک {جو آئے} احولیبامہ کے تھے، جو عیسو کی بیوی عناہ کی بیٹی تھی۔\n19۔ یہ عیسو کے بیٹے ہیں، جو ادوم ہے، اور یہ ان کے ڈیوک ہیں۔\n20۔ یہ {ہیں} سعیر حوری کے بیٹے، جو اس زمین پر آباد تھے؛ لوتان، اور شوبل، اور زیبیون، اور عنا،\n21۔ اور دیشون، ایزر، اور دیشان: یہ ہورائٹس کے ڈیوک ہیں، سعیر کے بچے ادوم کی سرزمین میں۔\n22۔ اور لوٹن کے بچے ہوری اور ہیمام تھے؛ اور لوٹن کی بہن ٹمنا تھی۔ {ہیمام: یا، ہومام}\n23۔ اور شوبال کے بچے یہ تھے؛ الوان، اور ماناہات، اور ایبل، شیفو، اور اونام۔ {الوان: یا، الیان} {شیفو: یا، شیفی}\n24۔ اور یہ {ہیں} زیبون کے بچے ہیں؛ آجاہ اور عناہ دونوں: یہ وہی عنا تھی جس نے صحرا میں خچروں کو پایا تھا، جب وہ اپنے باپ زبیعون کے گدھوں کو کھلا رہا تھا۔\n25۔ اور عناہ کے بچے یہ تھے؛ دیشون، اور احولیبامہ، انا کی بیٹی۔\n26۔ اور یہ دیشون کے بچے ہیں؛ ہیمدان، اور اشبان، اور ایتھران، اور چیران۔ {ہیمدان: یا، امرام}\n27. ایزر کے بچے یہ ہیں؛ بلہان، زاوان، اور اکان۔ {اکان: یا، جاکان}\n28۔ دشن کے بچے {یہ ہیں}؛ اوز، اور آران۔\n29۔ یہ {ہیں} وہ ڈیوک {جو ہورائٹس کے آئے}؛ ڈیوک لوتان، ڈیوک شوبل، ڈیوک زیبیون، ڈیوک عناہ،\n30۔ ڈیوک دیشون، ڈیوک ایزر، ڈیوک دیشان: یہ {ہیں} وہ ڈیوک {جو ہوری کے آئے}، اپنے ڈیوکوں میں سیئر کی سرزمین میں۔\n31۔ اور یہ وہ بادشاہ ہیں جو ادوم کی سرزمین پر حکمرانی کرتے تھے، اس سے پہلے کہ کوئی بادشاہ بنی اسرائیل پر حکمرانی کرے۔\n32۔ اور بیور کا بیٹا بیلا نے ایڈم میں حکومت کی: اور اس کے شہر کا نام {تھا} دنہابا۔\n33۔ اور بیلا فوت ہوا، اور جوباب، زرا آف بزرہ کا بیٹا، اس کی جگہ حکومت کرنے لگا۔\n34۔ اور جوباب فوت ہوا، اور تیمانی کی سرزمین کے ہوشام نے اس کی جگہ حکومت کی۔\n35۔ اور حشام مر گیا، اور حداد، جو بیداد کا بیٹا تھا، جس نے موآب کے میدان میں مدیان کو مارا تھا، اس کی جگہ حکومت کی: اور اس کے شہر کا نام آویت ہو گیا۔\n36۔ اور حداد فوت ہو گیا، اور مصریکہ کا سملہ اس کی جگہ حکومت کرنے لگا۔\n37۔ اور سملہ فوت ہو گیا، اور رہوبوتھ کے ساؤل {بائی} دریا نے اس کی جگہ حکومت کی۔\n38۔ اور ساؤل فوت ہو گیا، اور اخبور کا بیٹا بعلحنان اس کی جگہ حکومت کرنے لگا۔\n39۔ اور اخبور کا بیٹا بعلحنان فوت ہوا، اور حدر نے اس کی جگہ حکومت کی: اور اس کے شہر کا نام {تھا} پاؤ؛ اور ان کی بیوی کا نام {تھا} مہتابل تھا، جو میترد کی بیٹی تھیں، جو مزاہاب کی بیٹی تھیں۔ {حدار، پاؤ: یا، حداد، پائی: ان کی وفات کے بعد اشرافیہ تھے}\n40۔ اور یہ {ہیں} عیسو کے ان ڈیوکوں کے نام {جو آئے}، ان کے خاندانوں کے مطابق، ان کے مقامات کے مطابق، ان کے ناموں سے؛ ڈیوک تیمنا، ڈیوک الواہ، ڈیوک جیتھیتھ، {الواہ: یا، عالیہ}\n41۔ ڈیوک اہولیبامہ، ڈیوک ایلاہ، ڈیوک پینون،\n42۔ ڈیوک کیناز، ڈیوک تیمان، ڈیوک میبزار،\n43۔ ڈیوک مگدیئل، ڈیوک ایرام: یہ {ہیں} ادوم کے ڈیوک، اپنی ملکیت کی زمین میں رہائش کے مطابق: وہ {ہے} عیسو جو ایڈومیوں کا باپ ہے۔ {ادومیتی: عبرانی۔ ایڈوم}","1۔ اور یعقوب اس سرزمین میں رہتا تھا جہاں اس کا باپ اجنبی تھا، یعنی کنعان کی سرزمین میں۔ {جس میں...: عبرانی۔ اپنے والد کے قیام کے بارے میں}\n2. یہ {ہیں} یعقوب کی نسلیں۔ جوزف، جو سترہ سال کا تھا، اپنے بھائیوں کے ساتھ ریوڑ کو کھلا رہا تھا؛ اور وہ لڑکا بلحا کے بیٹوں کے ساتھ، اور زلپا کے بیٹوں کے ساتھ، جو اس کے والد کی بیویاں تھیں، اور یوسف نے اپنے والد کو ان کی بری خبر دی۔\n3۔ اب اسرائیل یوسف سے اس کے تمام بچوں سے زیادہ محبت کرتا تھا، کیونکہ وہ اس کی بوڑھی عمر کا بیٹا تھا: اور اس نے اسے {کئی} رنگوں کا کوٹ بنایا۔ {رنگ: یا، ٹکڑے}\n4۔ اور جب اس کے بھائیوں نے دیکھا کہ ان کے والد اسے سب بھائیوں سے زیادہ چاہتے ہیں، تو وہ اس سے نفرت کرنے لگے اور اس سے سکون سے بات نہ کر سکے۔\n5۔ اور یوسف نے خواب دیکھا، اور اپنے بھائیوں کو بتایا: اور وہ اسے اور زیادہ نفرت کرنے لگے۔\n6۔ اور اس نے ان سے کہا، سنو، میں تم سے دعا کرتا ہوں، یہ خواب جو میں نے دیکھا ہے:\n7۔ دیکھو، ہم کھیت میں گٹھیاں باندھ رہے تھے، اور دیکھو، میرا گچھا اٹھا اور سیدھا کھڑا ہو گیا؛ اور دیکھو، تمہارے گچھے اردگرد کھڑے ہو گئے، اور میرے گچھے کے سامنے سجدہ کیا۔\n8۔ اور اس کے بھائیوں نے اسے کہا، کیا تم واقعی ہم پر حکمرانی کرو گے؟ یا کیا تم واقعی ہم پر حکمرانی کرو گے؟ اور وہ اس سے اس کے خوابوں اور الفاظ کی وجہ سے اور بھی زیادہ نفرت کرتے تھے۔\n9۔ اور اس نے ایک اور خواب دیکھا، اور اپنے بھائیوں کو سنایا، اور کہا، دیکھو، میں نے ایک اور خواب دیکھا ہے؛ اور دیکھو، سورج، چاند اور گیارہ ستارے میرے سامنے جھک گئے۔\n10۔ اور اس نے یہ اپنے والد اور اپنے بھائیوں کو بتایا: اور اس کے والد نے اسے ڈانٹا اور کہا، یہ خواب کیا ہے جو تم نے دیکھا؟ کیا میں، تمہاری ماں اور تمہارے بھائی واقعی زمین کے سامنے سجدہ کرنے آئیں گے؟\n11۔ اور اس کے بھائی اس سے حسد کرتے تھے؛ لیکن اس کے والد نے کہاوت پر عمل کیا۔\n12۔ اور اس کے بھائی اپنے باپ کے ریوڑ کو شیکم میں کھلانے گئے۔\n13۔ اور اسرائیل نے یوسف سے کہا، کیا تمہارے بھائی شیکم میں ریوڑ کو کھلاتے نہیں؟ آؤ، اور میں تمہیں ان کے پاس بھیجوں گا۔ اور اس نے اس سے کہا، میں یہاں ہوں۔\n14۔ اور اس نے اس سے کہا، جاؤ، میں تم سے درخواست کرتا ہوں کہ دیکھو کہ تمہارے بھائیوں اور ریوڑوں کے لیے خیریت ہے یا نہیں؛ اور مجھے دوبارہ خبر دو۔ لہٰذا اس نے اسے وادی حبرون سے نکالا اور وہ شیکم آیا۔ {دیکھیں...: عبرانی اپنے بھائیوں کا امن دیکھیں، وغیرہ۔}\n15۔ اور ایک آدمی نے اسے پایا، اور دیکھو، وہ کھیت میں بھٹک رہا تھا: اور آدمی نے اس سے پوچھا، تم کیا تلاش کر رہے ہو؟\n16۔ اور اس نے کہا، میں اپنے بھائیوں کو تلاش کرتا ہوں: مجھے بتاؤ، میں دعا کرتا ہوں، کہ وہ کہاں کھاتے ہیں۔\n17۔ اور آدمی نے کہا، وہ یہاں سے جا چکے ہیں؛ کیونکہ میں نے انہیں کہتے سنا، چلو دوتھان چلتے ہیں۔ اور یوسف اپنے بھائیوں کے پیچھے گیا، اور انہیں دوتان میں پایا۔\n18۔ اور جب انہوں نے اسے دور سے دیکھا، یہاں تک کہ اس کے قریب آنے سے پہلے، تو انہوں نے اس کے خلاف سازش کی کہ اسے قتل کر دیں۔\n19۔ اور انہوں نے ایک دوسرے سے کہا، دیکھو، یہ خواب دیکھنے والا آ رہا ہے۔ {خواب دیکھنے والا: عبرانی۔ خوابوں کا ماسٹر\n20۔ تو اب آؤ، اور اسے مار ڈالیں، اور کسی گڑھے میں پھینک دیں، اور ہم کہیں گے، کسی شیطانی جانور نے اسے کھا لیا ہے: اور دیکھیں گے کہ اس کے خوابوں کا کیا بنے گا۔\n21. اور روبن نے سنا، اور اسے ان کے ہاتھوں سے آزاد کر دیا؛ اور کہا، آؤ اسے نہ ماریں۔\n22۔ اور روبن نے ان سے کہا، خون نہ بہاؤ، {لیکن} اسے اس گڑھے میں پھینک دو جو بیابان میں ہے، اور اس پر ہاتھ نہ رکھو؛ تاکہ وہ اسے ان کے ہاتھوں سے آزاد کر سکے، تاکہ اسے دوبارہ اپنے والد کے حوالے کر سکے۔\n23. اور جب یوسف اپنے بھائیوں کے پاس آیا، تو انہوں نے یوسف کی کوٹ اتار دی، جو {بہت سے} رنگوں کا کوٹ تھا جو {تھا} تھا؛ {رنگ: یا، ٹکڑے}\n24۔ اور انہوں نے اسے لے کر ایک گڑھے میں پھینک دیا: اور گڑھا خالی ہو گیا، اس میں پانی نہیں تھا۔\n25۔ اور وہ بیٹھ کر روٹی کھانے لگے، اور اپنی آنکھیں اٹھائیں اور دیکھا، اور دیکھتے ہوئے اسماعیلیوں کا ایک گروہ گلعاد سے اپنے اونٹوں کے ساتھ آیا، مصالحہ، مرہم اور مر، مصر لے جانے کے لیے۔\n26۔ اور یہوداہ نے اپنے بھائیوں سے کہا، اگر ہم اپنے بھائی کو مار ڈالیں اور اس کا خون چھپائیں تو کیا فائدہ؟\n27۔ آؤ، اور اسے اسماعیلیوں کے حوالے کریں، اور ہمارا ہاتھ اس پر نہ ہو؛ کیونکہ وہ ہمارا بھائی ہے اور ہمارا جسم ہے۔ اور اس کے بھائی مطمئن تھے۔ {تھے...: عبرانی سنا}\n28۔ پھر وہاں مدیانی کے تاجروں کے پاس سے گزرے؛ اور انہوں نے یوسف کو گڑھے سے نکالا اور اٹھایا، اور یوسف کو اسماعیلیوں کو بیس چاندی کے سکے بیچ دیے، اور وہ یوسف کو مصر لے آئے۔\n29۔ اور روبن گڑھے میں واپس آیا؛ اور دیکھو، یوسف گڑھے میں نہیں تھا؛ اور اس نے اپنے کپڑے کرائے پر دیے۔\n30۔ اور وہ اپنے بھائیوں کے پاس واپس آیا، اور کہا، بچہ {نہیں}؛ اور میں، کہاں جاؤں؟\n31۔ اور انہوں نے یوسف کا کوٹ لے کر بکریوں کے ایک بچے کو مار ڈالا، اور کوٹ کو خون میں ڈبو دیا؛\n32۔ اور انہوں نے {کئی} رنگوں کا کوٹ بھیجا، اور وہ اسے اپنے والد کے پاس لے گئے؛ اور کہا، یہ ہم نے پایا ہے: اب جان لو کہ یہ تمہارے بیٹے کا کوٹ ہے یا نہیں۔\n33۔ اور وہ جانتا تھا، اور کہا، {یہ} میرے بیٹے کا کوٹ ہے؛ ایک شیطانی جانور نے اسے نگل لیا ہے؛ جوزف بلا شبہ ٹکڑوں میں بکھرا ہوا ہے۔\n34۔ اور جیکب نے اپنے کپڑے پھاڑے، اس کی کمر پر تھیلا پہنا دیا، اور اپنے بیٹے کے لیے کئی دن سوگ منایا۔\n35۔ اور اس کے تمام بیٹے اور تمام بیٹیاں اسے تسلی دینے کے لیے اٹھ کھڑے ہوئے؛ لیکن وہ تسلی پانے سے انکار کرتا تھا؛ اور اس نے کہا، کیونکہ میں اپنے بیٹے کے سوگ میں قبر میں جاؤں گا۔ یوں اس کے والد اس کے لیے روئے۔\n36۔ اور مدیانیوں نے اسے مصر میں پوتیفار کو بیچ دیا، جو فرعون کا افسر اور گارڈ کا کپتان تھا۔ {افسر: عبوری۔ خواجہ سرا: لیکن یہ لفظ صرف خواجہ سرا کے لیے نہیں بلکہ چیمبرلینز، درباری اور افسران کے لیے بھی استعمال ہوتا ہے} {کپتان...: یا، چیف مارشل: عبرانی۔ قتل عام کرنے والوں یا پھانسی دینے والوں کا سردار}","1۔ اور اسی وقت ہوا کہ یہوداہ اپنے بھائیوں سے نیچے آ کر ایک عدولامت کے پاس آ گیا، جس کا نام حیرہ تھا۔\n2۔ اور یہوداہ نے وہاں ایک کنعانی کی بیٹی دیکھی، جس کا نام شواہ تھا؛ اور وہ اسے لے گیا، اور اس کے پاس گیا۔\n3۔ اور اس نے حاملہ ہوا اور بیٹا پیدا ہوا؛ اور اس نے اپنا نام 'ار' پکارا۔\n4۔ اور وہ دوبارہ حاملہ ہوئی، اور ایک بیٹا پیدا ہوا؛ اور اس نے اس کا نام اونان پکارا۔\n5۔ اور وہ پھر حاملہ ہوئی، اور ایک بیٹا پیدا کیا؛ اور اس کا نام شیلہ رکھا: اور وہ چزیب میں تھا، جب اس نے اسے جنم دیا۔\n6۔ اور یہوداہ نے اپنے سب سے بڑے بیٹے ایر کے لیے بیوی لی، جس کا نام {تامار} تھا۔\n7۔ اور ایر، یہوداہ کا پہلا بیٹا، خداوند کی نظر میں بدکار تھا؛ اور خداوند نے اسے مار ڈالا۔\n8۔ اور یہوداہ نے اونان سے کہا، اپنے بھائی کی بیوی کے پاس جاؤ، اس سے شادی کرو، اور اپنے بھائی کے لیے نسل پیدا کرو۔\n9۔ اور اونان جانتا تھا کہ بیج اس کا نہیں ہونا چاہیے؛ اور جب وہ اپنے بھائی کی بیوی کے پاس گیا، تو اس نے زمین پر گرا دیا، کہیں وہ اپنے بھائی کو نسل نہ دے دے۔\n10۔ اور جو کام اس نے کیا وہ خدا کو ناراض کر گیا، اس لیے اس نے اسے بھی قتل کر دیا۔ {ناراض...: عبرانی خداوند کی نظر میں برا تھا}\n11۔ پھر یہوداہ نے اپنی بہو تامار سے کہا، اپنے والد کے گھر بیوہ رہو، جب تک کہ میرا بیٹا شیلہ بڑا نہ ہو جائے: کیونکہ اس نے کہا، تاکہ وہ بھی مر نہ جائے، جیسا کہ اس کے بھائیوں نے کیا۔ اور تمر جا کر اپنے والد کے گھر میں رہنے لگی۔\n12۔ اور وقت کے ساتھ شواہ یہوداہ کی بیوی کی بیٹی فوت ہو گئی؛ اور یہوداہ کو تسلی ملی، اور وہ اپنے بھیڑ کاٹنے والوں کے پاس تیمنات چلا گیا، جو وہ اور اس کا دوست ہیرہ عدالمی تھا۔ {عمل میں...: عبرانی دن کئی گنا بڑھ گئے}\n13۔ اور کہا گیا کہ تامار نے کہا، دیکھو تمہارا سسر تمناتھ کے پاس اپنی بھیڑیں کاٹنے جاتا ہے۔\n14۔ اور اس نے اپنی بیوہ کے کپڑے اتارے، اسے پردے سے ڈھانپ دیا، اور خود کو لپیٹ کر ایک کھلی جگہ پر بیٹھ گئی، جو راستے میں تیمناتھ تک ہے؛ کیونکہ اس نے دیکھا کہ شیلہ بڑا ہو گیا ہے، اور اسے بیوی کے طور پر نہیں دیا گیا۔ {ایک کھلا...: عبرانی آنکھوں کا دروازہ، یا، ایناجیم کا}\n15۔ جب یہوداہ نے اسے دیکھا تو اس نے اسے ایک بدکار عورت سمجھا؛ کیونکہ اس نے اپنا چہرہ ڈھانپ لیا تھا۔\n16۔ اور وہ راستے میں اس کی طرف مڑا اور کہا، جاؤ، میں تم سے دعا کرتا ہوں، مجھے تمہارے پاس آنے دو؛ (کیونکہ وہ نہیں جانتا تھا کہ وہ اس کی بہو ہے۔) اور اس نے کہا، تم مجھے کیا دو گے، تاکہ تم میرے پاس آ سکو؟\n17۔ اور اس نے کہا، میں ریوڑ میں سے ایک بچہ بھیجوں گا۔ اور اس نے کہا، کیا تم مجھے کوئی وعدہ دو گے، جب تک کہ تم اسے بھیج نہ دو؟ {ایک بچہ: عبرانی۔ بکریوں کا بچہ}\n18۔ اور اس نے کہا، میں تمہیں کیا وعدہ دوں؟ اور اس نے کہا، تمہارا نشان، اور تمہارا کنگن، اور تمہارا عصا جو تمہارے ہاتھ میں ہے۔ اور اس نے اسے دیا، اور اس کے پاس آیا، اور وہ اس سے حاملہ ہوئی۔\n19۔ اور وہ اٹھی، چلی گئی، اور اپنی چادر کے پاس لیٹ گئی، اور اپنی بیوہ ہونے کے کپڑے پہن لیے۔\n20۔ اور یہوداہ نے بچے کو اپنے دوست عدولمی کے ہاتھ سے بھیجا، تاکہ وہ عورت کے ہاتھ سے عہد وصول کرے: لیکن اسے نہیں ملا۔\n21۔ پھر اس نے اس جگہ کے مردوں سے پوچھا، کہاں ہے وہ بدکار عورت، جو کھلے عام راستے کے کنارے ہے؟ اور انہوں نے کہا، اس {جگہ} میں کوئی بدکار عورت نہیں تھی۔ {کھل کر: یا، ایناجیم میں}\n22۔ اور وہ یہوداہ کے پاس واپس آیا، اور کہا، میں اسے نہیں ڈھونڈ پا رہا؛ اور اس جگہ کے مردوں نے کہا، {کہ} اس {جگہ} میں کوئی بدکار عورت نہیں ہے۔\n23۔ اور یہوداہ نے کہا، اسے اپنے پاس لے جائے، کہیں ہم شرمندہ نہ ہوں: دیکھو، میں نے یہ بچی بھیجی ہے، اور تم نے اسے نہیں پایا۔ {شرمندہ ہوں: عبرانی۔ حقارت بن جاؤ}\n24۔ اور تقریبا تین ماہ بعد ہوا کہ یہوداہ کو بتایا گیا، کہا گیا، تیمار نے تمہاری بہو نے بدکار لڑائی کی ہے؛ اور دیکھو، وہ بدکاری سے حاملہ ہے۔ اور یہوداہ نے کہا، اسے باہر لے آؤ، اور اسے جلا دو۔\n25۔ جب وہ پیدا ہوئی، تو اس نے اپنے سسر کے پاس بھیجا، کہا، اس آدمی کی قسم، جس کے یہ [ہیں] میں حاملہ ہوں: اور اس نے کہا، سمجھو، میں تم سے دعا کرتی ہوں، جس کے پاس یہ ہیں، نشان، کنگن اور عصا۔\n26۔ اور یہوداہ نے ان کو تسلیم کیا اور کہا، وہ مجھ سے زیادہ نیک رہی ہے؛ کیونکہ میں نے اسے اپنے بیٹے شیلہ کو نہیں دیا۔ اور وہ اسے دوبارہ نہیں جانتا۔\n27۔ اور اس کی آزمائش کے وقت یہ ہوا کہ دیکھو، اس کے رحم میں جڑواں بچے تھے۔\n28۔ اور جب وہ تڑپ رہی تھی، تو {ایک نے} نے اپنا ہاتھ آگے بڑھایا: اور دائی نے اس کے ہاتھ میں ایک سرخ دھاگہ باندھ کر کہا، یہ سب سے پہلے نکلا۔\n29۔ اور جب اس نے اپنا ہاتھ پیچھے کھینچا، تو اس کا بھائی باہر آیا، اور اس نے کہا، تم کیسے ٹوٹ گئے؟ {یہ} مجھ پر ظلم ہے: اس لیے اس کا نام فاریز رکھا گیا۔ {کتنی جلدی...: یا، تم نے یہ خلاف ورزی کیوں کی؟} {فیریز: یہ ہے ایک دراڑ}\n30۔ اور اس کے بعد اس کا بھائی باہر آیا، جس کے ہاتھ پر سرخ دھاگہ تھا، اور اس کا نام زارح تھا۔","1۔ اور یوسف مصر میں لایا گیا؛ اور پوتیفار، فرعون کا ایک افسر، محافظ کا کپتان، ایک مصری، نے اسے اسماعیلیوں کے ہاتھوں سے خریدا، جنہوں نے اسے وہاں اتارا تھا۔\n2۔ اور خداوند یوسف کے ساتھ تھا، اور وہ خوشحال انسان تھا؛ اور وہ اپنے آقا مصری کے گھر میں تھا۔\n3۔ اور اس کے آقا نے دیکھا کہ خداوند اس کے ساتھ ہے، اور خداوند نے جو کچھ بھی اس نے کیا اسے اپنے ہاتھ میں کامیاب بنایا۔\n4۔ اور یوسف نے اس کی نظر میں فضل پایا، اس کی خدمت کی، اور اسے اپنے گھر کا نگران بنا دیا، اور جو کچھ بھی اس نے اپنے ہاتھ میں دے دیا۔\n5۔ اور یہ اس وقت سے ہوا جب اس نے اسے اپنے گھر میں نگران بنایا، اور جو کچھ اس کے پاس تھا، خداوند نے یوسف کے لیے مصری کے گھر کو برکت دی؛ اور خداوند کی برکت اس کے گھر اور میدان میں موجود تمام چیزوں پر تھی۔\n6۔ اور اس نے جو کچھ اس کے پاس تھا وہ سب یوسف کے ہاتھ میں چھوڑ دیا؛ اور وہ جانتا تھا کہ اسے کیا کھانا چاہیے تھا، سوائے اس روٹی کے جو اس نے کھائی۔ اور یوسف {ایک}نیک انسان تھا، اور بہت پسندیدہ تھا۔\n7۔ اور ان واقعات کے بعد ہوا کہ اس کے مالک کی بیوی نے یوسف پر نظر ڈالی؛ اور اس نے کہا، میرے ساتھ لیٹ جاؤ۔\n8۔ لیکن اس نے انکار کر دیا، اور اپنے مالک کی بیوی سے کہا، دیکھو، میرے مالک کو وہ سب کچھ نہیں جو میرے گھر میں ہے، اور اس نے جو کچھ بھی ہے وہ میرے ہاتھ میں دے دیا ہے؛\n9. {اس گھر میں مجھ سے بڑا کوئی نہیں؛ اس نے مجھ سے کچھ بھی نہیں چھپایا سوائے تمہارے کے، کیونکہ تم اس کی بیوی ہو: تو پھر میں یہ بڑی بدکاری اور خدا کے خلاف گناہ کیسے کر سکتی ہوں؟\n10۔ اور ایسا ہوا، جیسا کہ وہ روز بہ دن یوسف سے بات کرتی رہی، کہ وہ اس کی بات نہیں سنے، اس کے ساتھ لیٹنے یا اس کے ساتھ رہنے کو نہیں۔\n11۔ اور اسی وقت ہوا کہ {جوزف} اپنے کام کے لیے گھر میں گیا؛ اور {وہاں} گھر کے مردوں میں سے کوئی بھی نہیں تھا۔\n12۔ اور اس نے اسے اس کے کپڑے سے پکڑ کر کہا، میرے ساتھ لیٹ جاؤ: اور اس نے اپنا لباس اس کے ہاتھ میں چھوڑ دیا، اور بھاگ گیا اور اسے باہر نکال لیا۔\n13۔ اور یہ ہوا جب اس نے دیکھا کہ اس نے اپنا لباس اس کے ہاتھ میں چھوڑ دیا ہے، اور وہ باہر بھاگ گیا،\n14۔ کہ اس نے اپنے گھر کے مردوں کو بلایا اور ان سے کہا، دیکھو، اس نے ہمارے پاس ایک عبرانی زبان لائی ہے تاکہ ہمارا مذاق اڑائے؛ وہ میرے پاس آیا تاکہ میرے ساتھ لیٹ جائے، اور میں زور سے رونے لگا: {اونچی: عبرانی۔ زبردست}\n15۔ اور جب اس نے سنا کہ میں نے اپنی آواز بلند کی اور رویا تو وہ اپنا لباس میرے پاس چھوڑ گیا، اور بھاگ گیا، اور اسے باہر نکال لیا۔\n16۔ اور اس نے اس کا لباس اپنے پاس رکھ دیا، یہاں تک کہ اس کا رب گھر آ گیا۔\n17۔ اور اس نے اس سے ان الفاظ کے مطابق کہا، \"وہ عبرانی خادم، جسے تم ہمارے پاس لایا ہے، میرے پاس آیا اور میرا مذاق اڑانے آیا:\n18۔ اور جب میں نے اپنی آواز بلند کی اور رونے لگا، تو اس نے اپنا لباس میرے پاس چھوڑ دیا اور بھاگ گیا۔\n19۔ اور ایسا ہوا جب اس کے مالک نے اپنی بیوی کے الفاظ سنے، جو اس نے اس سے کہے، کہا، اس طرح تمہارا خادم میرے ساتھ آیا؛ کہ اس کا غصہ بھڑک اٹھا۔\n20۔ اور یوسف کے مالک نے اسے لے کر قید خانے میں ڈال دیا، جہاں بادشاہ کے قیدی بندھے جاتے تھے: اور وہ وہاں قید میں تھا۔\n21۔ لیکن خداوند یوسف کے ساتھ تھا، اس نے اس پر رحم کیا، اور قید خانے کے محافظ کی نظر میں اس پر فضل کیا۔ {دکھایا...: ہیب۔ اس پر مہربانی کا اظہار کریں}\n22۔ اور قید خانے کے نگہبان نے قید خانے میں موجود تمام قیدیوں کو یوسف کے حوالے کر دیا؛ اور جو کچھ بھی وہاں ہوا، وہی اس کا کرنے والا تھا۔\n23۔ قید خانے کا رکھوالا اپنے ہاتھ کے نیچے کسی بھی چیز کی طرف نہیں دیکھتا تھا؛ کیونکہ خداوند اس کے ساتھ تھا، اور جو اس نے کیا، خداوند نے اسے خوشحال بنایا۔","1۔ اور ان واقعات کے بعد یہ ہوا کہ مصر کے بادشاہ کے بٹلر اور اس کے بیکر نے اپنے آقا مصر کے بادشاہ کو ناراض کیا۔\n2۔ اور فرعون اپنے دو افسران، بٹلر کے سردار اور بیکروں کے سردار پر غصہ ہوا۔\n3۔ اور اس نے انہیں محافظ کے کپتان کے گھر میں قید خانے میں رکھا، اس جگہ جہاں یوسف کو بندھا دیا گیا تھا۔\n4۔ اور محافظوں کے کپتان نے یوسف کو ان کی خدمت سونپی، اور وہ ایک عرصہ قید میں رہے۔\n5۔ اور دونوں نے ایک خواب دیکھا، ہر آدمی ایک رات میں اپنا خواب، ہر آدمی اپنے خواب کی تعبیر کے مطابق، مصر کے بادشاہ کا بٹلر اور بیکر، جو قید میں بندھے ہوئے تھے۔\n6۔ اور یوسف صبح ان کے پاس آیا، انہیں دیکھا، اور دیکھتے ہوئے وہ اداس تھے۔\n7۔ اور اس نے فرعون کے افسران سے پوچھا جو اس کے ساتھ اس کے آقا کے گھر کی سرپرستی میں تھے، اور کہا، آج کیوں تم اتنی افسردگی سے دیکھ رہے ہو؟ {دیکھیں...: عبوری۔ کیا تمہارے چہرے برے ہیں؟}\n8۔ اور انہوں نے اس سے کہا، ہم نے خواب دیکھا ہے، اور اس کا کوئی تعبیر کرنے والا نہیں۔ اور یوسف نے ان سے کہا، کیا تشریحات خدا کی ملکیت نہیں ہیں؟ مجھے بتائیں {انہیں}، میں آپ سے دعا کرتا ہوں۔\n9۔ اور چیف بٹلر نے یوسف کو اپنا خواب سنایا اور کہا، دیکھو میرے خواب میں ایک بیل میرے سامنے تھی؛\n10. اور بیل میں تین شاخیں تھیں: اور وہ {تھا} جیسے وہ نکل آئی ہو، {اور} اس کے پھول نکل آئے؛ اور اس کے جھرمٹ سے پکے ہوئے انگور نکلے:\n11۔ اور فرعون کا پیالہ میرے ہاتھ میں تھا، اور میں نے انگور لیے، انہیں فرعون کے پیالے میں دبا دیا، اور پیالہ فرعون کے ہاتھ میں دے دیا۔\n12۔ اور یوسف نے اس سے کہا، یہ اس کی تشریح ہے: تین شاخیں تین دن ہیں:\n13۔ پھر بھی تین دن کے اندر فرعون تمہارا سر اٹھائے گا، اور تمہیں تمہاری جگہ واپس لے آئے گا: اور تم فرعون کا پیالہ اس کے ہاتھ میں دے دو گے، جیسا کہ تم اس کے خادم تھے جب تم اس کے خادم تھے۔ {اٹھاؤ...: یا، خیال ہے}\n14۔ لیکن جب سب تمہارے لیے ٹھیک ہو جائے تو مجھ پر غور کرو اور مہربانی کرو، میں تم سے دعا کرتا ہوں، مجھ سے دعا کرتا ہوں، اور فرعون کے سامنے میرا ذکر کرنا، اور مجھے اس گھر سے نکالنا: {سوچو...: عبرانی۔ مجھے اپنے ساتھ یاد رکھو}\n15۔ کیونکہ واقعی مجھے عبرانیوں کی سرزمین سے چھین لیا گیا تھا: اور یہاں بھی میں نے کچھ نہیں کیا کہ وہ مجھے قید خانے میں ڈال دیں۔\n16۔ جب چیف بیکر نے دیکھا کہ تعبیر اچھی ہے، تو اس نے یوسف سے کہا، میں بھی اپنے خواب میں تھا، اور دیکھو، میرے سر پر تین سفید ٹوکریاں تھیں: سفید: یا، سوراخوں سے بھرپور۔\n17۔ اور سب سے اوپر کی ٹوکری میں فرعون کے لیے ہر قسم کے گوشت رکھے ہوئے تھے؛ اور پرندوں نے انہیں میرے سر پر رکھی ٹوکری سے کھا لیا۔ {بیک میٹس...: عببرانی۔ فرعون کا گوشت، ایک بیکر کا کام، یا، باورچی کا}\n18۔ اور یوسف نے جواب دیا اور کہا، یہ اس کی تشریح ہے: تین ٹوکریاں تین دن ہیں:\n19۔ پھر بھی تین دن کے اندر فرعون تمہارا سر تم سے اٹھا کر تمہیں درخت پر لٹکائے گا؛ اور پرندے تمہارا گوشت تم سے کھا جائیں گے۔ {اٹھاؤ...: یا، فرض کرو، اور اپنا عہدہ تم سے لے لو}\n20۔ اور تیسرے دن، جو فرعون کی سالگرہ تھی، اس نے اپنے تمام خادموں کے لیے دعوت منائی: اور سردار بٹلر اور چیف بیکر کا سر اپنے خادموں میں سے اٹھایا۔ {اٹھایا گیا...: یا، اندازہ ہو گیا}\n21۔ اور اس نے چیف بٹلر کو دوبارہ اس کی بٹلر شپ پر بحال کیا؛ اور اس نے پیالہ فرعون کے ہاتھ میں دے دیا:\n22۔ لیکن اس نے سردار بیکر کو پھانسی دے دی: جیسا کہ یوسف نے ان سے ترجمہ کیا تھا۔\n23۔ پھر بھی چیف بٹلر نے یوسف کو یاد نہیں کیا، بلکہ اسے بھول گیا۔","1۔ اور دو سال مکمل ہونے کے بعد، فرعون نے خواب دیکھا: اور دیکھو، وہ دریا کے کنارے کھڑا تھا۔\n2۔ اور دیکھو، دریا سے سات پسندیدہ گائے اور موٹے گوشت والے جانور نکلے؛ اور وہ ایک چراگاہ میں کھاتے تھے۔\n3۔ اور دیکھو، سات اور جانور دریا سے ان کے پیچھے آئے، بدتمیز اور دبلا پتلا؛ اور دریا کے کنارے {دوسری} کائی کے پاس کھڑا رہا۔\n4۔ اور بدتمیز اور دبلا پتلا کائن سات پسندیدہ اور موٹے کائنز کو کھا گیا۔ تو فرعون جاگا۔\n5۔ اور اس نے دوسری بار سویا اور خواب دیکھا: اور دیکھتے دیکھتے سات مکئی کے بال ایک تنوں پر آ گئے، جو سیدھا اور اچھا تھا۔ {رینک: عبرانی۔ موٹا}\n6۔ اور دیکھو، سات پتلے کان اور مشرقی ہوا سے اڑ کر ان کے پیچھے پھوٹ پڑے۔\n7۔ اور سات پتلے کانوں نے سات درجے اور بھرے ہوئے کانوں کو نگل لیا۔ اور فرعون جاگا، اور دیکھو، یہ ایک خواب تھا۔\n8۔ اور صبح کے وقت اس کی روح پریشان ہو گئی؛ اور اس نے مصر کے تمام جادوگروں اور اس کے تمام دانا لوگوں کو بلایا: اور فرعون نے انہیں اپنا خواب سنایا؛ لیکن کوئی ایسا نہیں تھا جو فرعون کو ان کی تشریح کر سکے۔\n9۔ پھر چیف بٹلر نے فرعون سے کہا، میں آج اپنی غلطیاں یاد رکھتا ہوں:\n10۔ فرعون اپنے خادموں سے ناراض ہوا، اور مجھے محافظ کے کپتان کے گھر میں رکھ دیا، {دونوں} مجھے اور چیف بیکر:\n11۔ اور ہم نے ایک رات میں خواب دیکھا، میں اور وہ؛ ہم نے ہر آدمی کو اس کے خواب کی تعبیر کے مطابق خواب دیکھا۔\n12۔ اور وہاں ہمارے ساتھ ایک نوجوان تھا، ایک عبرانی شخص، محافظ کے کپتان کا خادم؛ اور ہم نے اسے بتایا، اور اس نے ہمارے خوابوں کی تعبیر کی؛ ہر آدمی کو اس کے خواب کے مطابق اس نے ترجمہ کیا۔\n13۔ اور ایسا ہوا، جیسا کہ اس نے ہمیں سمجھا، ایسا ہی ہوا؛ مجھے اس نے میرے عہدے پر بحال کیا، اور اسے پھانسی دی گئی۔\n14۔ پھر فرعون نے بھیجا اور یوسف کو بلایا، اور اسے جلدی سے قید خانے سے نکالا، اور اس نے خود کو شیو کیا، اپنا لباس بدل لیا، اور فرعون کے پاس آ گیا۔ {لایا...: عبوری۔ اسے بھاگنے پر مجبور کیا}\n15۔ اور فرعون نے یوسف سے کہا، میں نے خواب دیکھا ہے، اور کوئی نہیں جو اسے تعبیر کر سکے، اور میں نے تمہارے بارے میں یہ کہتے سنا ہے کہ تم خواب کو سمجھ کر اس کی تعبیر کر سکتے ہو۔ {تم...: یا، جب تم خواب سنو تو اسے سمجھ سکتے ہو}\n16۔ اور یوسف نے فرعون کو جواب دیا، کہا، {یہ مجھ میں نہیں}: خدا فرعون کو امن کا جواب دے گا۔\n17۔ اور فرعون نے یوسف سے کہا، اپنے خواب میں، میں دریا کے کنارے کھڑا تھا:\n18۔ اور دیکھو، دریا سے سات موٹے اور پسندیدہ جانور نکلے؛ اور وہ ایک چراگاہ میں کھاتے تھے:\n19۔ اور دیکھو، سات اور جانور ان کے پیچھے آئے، غریب، بہت بدتمیز اور دبلا پتلا، جو میں نے پورے مصر کی سرزمین میں کبھی برائی کے لیے نہیں دیکھا:\n20۔ اور دبلا پتلا اور ناپسندیدہ کائی نے پہلے سات موٹے کائنز کو کھا لیا:\n21۔ اور جب انہوں نے انہیں کھا لیا تو یہ معلوم نہیں ہو سکتا تھا کہ انہوں نے انہیں کھا لیا ہے؛ لیکن وہ اب بھی شروع کی طرح ناپسندیدہ تھے۔ تو میں جاگا۔ {کھایا گیا...: عبرانی۔ ان کے اندرونی حصوں میں آؤ}\n22۔ اور میں نے اپنے خواب میں دیکھا، اور دیکھو، سات کان ایک ہی تنوں میں نکلے، بھرے اور اچھے تھے:\n23۔ اور دیکھو، سات کان، مرجھا، پتلے، {اور} مشرقی ہوا سے اڑ گئے، ان کے پیچھے پھوٹ پڑے: {مرجھا: یا، چھوٹے}\n24۔ اور پتلے کانوں نے سات اچھے کانوں کو نگل لیا: اور میں نے یہ بات جادوگروں کو بتائی؛ لیکن {ایسا کوئی نہیں تھا} جو {یہ} مجھ سے کہہ سکے۔\n25۔ اور یوسف نے فرعون سے کہا، فرعون کا خواب ایک ہے: خدا نے فرعون کو دکھایا ہے کہ وہ کیا کرنے والا ہے۔\n26. سات نیک گائے سات سال ہیں؛ اور سات اچھے کان سات سال ہیں: خواب ایک ہے۔\n27۔ اور سات پتلے اور بدقسمت گائے جو ان کے بعد آئے {ہیں} سات سال؛ اور سات خالی کان جو مشرقی ہوا سے اڑ چکے ہیں، سات سال قحط ہوں گے۔\n28. یہی وہ بات ہے جو میں نے فرعون سے کہی ہے: جو خدا کرنے والا ہے وہ فرعون کو دکھاتا ہے۔\n29۔ دیکھو، پورے مصر کی سرزمین میں سات سال بڑی فراوانی آ جاتی ہے:\n30۔ اور ان کے بعد سات سال قحط پیدا ہوں گے؛ اور مصر کی سرزمین میں ساری فراوانی بھلا دی جائے گی؛ اور قحط زمین کو نگل جائے گا؛\n31۔ اور اس قحط کی وجہ سے زمین میں فراوانی معلوم نہیں ہوگی؛ کیونکہ یہ {بہت خوفناک} ہوگا۔ {گریویس: عبدی۔ ہیوی}\n32۔ اور اس کے لیے خواب دو بار فرعون کے لیے دوگنا ہوا؛ {یہ ہے} کیونکہ وہ چیز {ہے} خدا کی طرف سے قائم کی گئی ہے، اور خدا جلد ہی اسے حقیقت میں لے آئے گا۔ {قائم...: یا، خدا کی طرف سے تیار}\n33۔ اب فرعون ایک ہوشیار اور دانا آدمی کو دیکھے اور اسے مصر کی سرزمین پر مقرر کرے۔\n34۔ فرعون یہ کرے، اور زمین پر افسران مقرر کرے، اور سات وافر سالوں میں مصر کی سرزمین کا پانچواں حصہ سنبھالے۔ {افسران: یا، نگران افراد}\n35۔ اور آنے والے اچھے سالوں کا سارا کھانا جمع کریں، فرعون کے ہاتھوں اناج رکھیں، اور شہروں میں کھانا رکھیں۔\n36۔ اور وہ خوراک زمین کو سات سال قحط کے مقابلے میں ذخیرہ کرنے کے لیے ہوگی، جو مصر کی سرزمین میں ہوں گے؛ کہ زمین قحط سے ختم نہ ہو۔ {perish...: عبرانی۔ کٹ نہ جائیں}\n37۔ اور وہ چیز فرعون کی نظر میں اور اس کے تمام خادموں کی نظر میں اچھی تھی۔\n38۔ اور فرعون نے اپنے بندوں سے کہا، کیا ہم ایسا شخص تلاش کر سکتے ہیں جیسے یہ {ہے}، ایک ایسا شخص جس میں خدا کی روح {ہے}؟\n39۔ اور فرعون نے یوسف سے کہا، چونکہ خدا نے تمہیں یہ سب دکھایا ہے، {اتنے ہوشیار اور دانا} کوئی نہیں جتنا تم ہو:\n40۔ تو میرے گھر پر رہو گے، اور تیری بات کے مطابق میری تمام قوم پر حکومت کی جائے گی: صرف تخت پر میں تم سے بڑا ہوں گا۔ {حکم دیا جائے: عبرانی۔ مسلح ہو جاؤ، یا، چومو}\n41۔ اور فرعون نے یوسف سے کہا، دیکھو، میں نے تمہیں پورے مصر کی سرزمین پر مقرر کیا ہے۔\n42۔ اور فرعون نے اپنے ہاتھ سے اپنی انگوٹھی اتاری، یوسف کے ہاتھ پر پہنائی، اسے عمدہ کپڑے کے لباس میں پہنایا اور اس کے گلے میں سونے کی زنجیر ڈالی؛ {ٹھیک...: یا، ریشم}\n43۔ اور اس نے اسے اپنے پاس موجود دوسری رتھ میں سوار کروایا؛ اور وہ اس کے سامنے پکارے، گھٹنے ٹیکو: اور اس نے اسے مصر کی پوری سرزمین پر حکمران بنا دیا۔ {کمان...: یا، نرم والد: عبرانی۔ ابریچ}\n44۔ اور فرعون نے یوسف سے کہا، میں فرعون ہوں، اور تمہارے بغیر کوئی مصر کی سرزمین میں اپنا ہاتھ یا پاؤں نہیں اٹھا سکتا۔\n45۔ اور فرعون نے یوسف کا نام زفناتپانیہ کہا؛ اور اس نے اسے اپنی بیوی اسیناتھ کو دے دیا، جو پوٹیفیرا، پجاری آف اون کی بیٹی تھی۔ اور یوسف پورے مصر کی سرزمین پر چلا گیا۔ {زفناتھ پانہ: جو قبطی زبان میں راز افشا کرنے والا ہے، یا، وہ آدمی جس کے لیے راز ظاہر کیے جاتے ہیں} {پادری: یا، شہزادہ}\n46۔ اور یوسف تیس سال کا تھا جب وہ مصر کے بادشاہ فرعون کے سامنے کھڑا تھا۔ اور یوسف فرعون کی موجودگی سے باہر نکلا اور پورے مصر کی سرزمین میں گھومنے لگا۔\n47۔ اور سات خوشحال سالوں میں زمین نے مٹھی بھر سے جنم لیا۔\n48۔ اور اس نے سات سالوں کا سارا کھانا جو مصر کی سرزمین میں تھا، جمع کیا اور وہ کھانا شہروں میں رکھ دیا: کھیت کا کھانا، جو ہر شہر کے گرد تھا، اسی میں رکھا گیا۔\n49۔ اور یوسف نے مکئی کو سمندر کی ریت کی طرح بہت زیادہ جمع کیا، یہاں تک کہ وہ گنتی چھوڑ گیا؛ کیونکہ {یہ تھا} بغیر نمبر کے۔\n50۔ اور یوسف کو قحط کے سال آنے سے پہلے دو بیٹے پیدا ہوئے، جنہیں اسناتھ، پوٹیفیرا کے کاہن آف آن کی بیٹی نے اسے جنم دیا۔ {پادری: یا، شہزادہ}\n51۔ اور یوسف نے پہلے بچے مناسی کا نام پکارا: خدا نے مجھے میری ساری محنت اور میرے والد کے گھر کو بھلا دیا ہے۔ {مناسے: یعنی، بھولنا}\n52۔ اور دوسرے کا نام افرائیم کہلا: کیونکہ خدا نے مجھے میری مصیبت کی زمین میں پھلدار بنایا ہے۔ {افرائیم: یعنی، پھلدار ہے}\n53۔ اور مصر کی سرزمین میں سات سال کی فراوانی ختم ہو گئی۔\n54۔ اور جیسا کہ یوسف نے کہا تھا، سات سال کی کمی آنے لگی: اور تمام زمینوں میں کمی تھی؛ لیکن مصر کی پوری سرزمین میں روٹی موجود تھی۔\n55۔ اور جب ساری مصر کی سرزمین بھوکی ہو گئی، لوگوں نے فرعون سے روٹی مانگنے کی آواز دی: اور فرعون نے سب مصریوں سے کہا، یوسف کے پاس جاؤ؛ جو وہ تم سے کہے، کرو۔\n56۔ اور قحط نے زمین پر سب کچھ چھا گیا: اور یوسف نے تمام گودام کھول دیے اور مصریوں کو بیچ دیے؛ اور قحط مصر کی سرزمین میں شدت اختیار کر گیا۔ {تمام گودام: عبرانی۔ سب کچھ وہیں تھا}\n57۔ اور تمام ممالک مصر میں یوسف کے پاس آئے تاکہ {ماج} خرید سکیں؛ کیونکہ قحط تمام علاقوں میں {اتنا} شدید تھا۔","1۔ جب یعقوب نے دیکھا کہ مصر میں مکئی ہے، تو یعقوب نے اپنے بیٹوں سے کہا، تم ایک دوسرے کو کیوں دیکھتے ہو؟\n2۔ اور اس نے کہا، دیکھو، میں نے سنا ہے کہ مصر میں اناج ہے، تم وہاں سے نیچے آؤ اور ہمارے لیے وہاں سے خرید لو؛ تاکہ ہم زندہ رہیں، نہ مریں۔\n3۔ اور یوسف کے دس بھائی مصر میں اناج خریدنے گئے۔\n4۔ لیکن بنیمن، یوسف کا بھائی، یعقوب نے اپنے بھائیوں کے ساتھ نہیں بھیجا؛ کیونکہ اس نے کہا، تاکہ کوئی شرارت نہ ہو جائے۔\n5۔ اور اسرائیل کے بیٹے آنے والوں میں سے اناج خریدنے آئے: کیونکہ قحط کنعان کی سرزمین میں تھا۔\n6۔ اور یوسف زمین کا حکمران تھا، {اور} وہی تھا جس نے زمین کے تمام لوگوں کو بیچ دیا: اور یوسف کے بھائی آئے اور اس کے سامنے سجدہ کر کے زمین کے سامنے سجدہ کیا۔\n7۔ اور یوسف نے اپنے بھائیوں کو دیکھا، اور انہیں پہچانا، لیکن ان سے اجنبی ہو گیا اور ان سے سختی سے بات کی؛ اور اس نے ان سے کہا، تم کہاں سے آئے ہو؟ اور انہوں نے کہا، کنعان کی سرزمین سے کھانا خریدنے کے لیے۔ {تقریبا...: عبرانی۔ ان کے ساتھ مشکل چیزیں}\n8۔ اور یوسف اپنے بھائیوں کو جانتا تھا، لیکن وہ اسے نہیں جانتے تھے۔\n9۔ اور یوسف نے ان خوابوں کو یاد کیا جو اس نے ان کے بارے میں دیکھے تھے، اور ان سے کہا، تم جاسوس ہو؛ تم اس سرزمین کی برہنگی دیکھنے آئے ہو۔\n10۔ اور انہوں نے اس سے کہا، نہیں، میرے آقا، لیکن تمہارے خادم کھانا خریدنے آئے ہیں۔\n11. ہم سب ایک آدمی کے بیٹے ہیں؛ ہم {سچے} {انسان} ہیں، تیرے خادم جاسوس نہیں ہیں۔\n12۔ اور اس نے ان سے کہا، نہیں، لیکن زمین کی برہنگی دیکھنے آئے ہو۔\n13۔ اور انہوں نے کہا، تیرے بندے بارہ بھائی ہیں، کنعان کی سرزمین میں ایک آدمی کے بیٹے؛ اور دیکھو، سب سے چھوٹا {ہے} آج ہمارے والد کے ساتھ، اور ایک {نہیں} ہے۔\n14۔ اور یوسف نے ان سے کہا، یہی میں نے تم سے کہا تھا، تم جاسوس ہو:\n15۔ اس سے ثابت ہو جائے گا: فرعون کی جان کی قسم، تم یہاں سے نہیں جاؤ گے، سوائے اس کے کہ تمہارا سب سے چھوٹا بھائی یہاں آ جائے۔\n16۔ تم میں سے کسی کو بھیجو، اور وہ تمہارے بھائی کو لے آئے، اور تمہیں قید میں رکھا جائے گا، تاکہ تمہاری باتیں ثابت ہوں، چاہے تم میں کوئی سچائی ہو: ورنہ فرعون کی جان سے تم جاسوس ہو۔ {برقرار رہا...: عببرانی۔ باؤنڈ}\n17۔ اور اس نے انہیں تین دن وارڈ میں اکٹھا کر دیا۔ {لکھیں: عببرانی۔ جمع کیا گیا}\n18۔ اور یوسف نے تیسرے دن ان سے کہا، یہ کرو، اور زندہ رہو؛ {for} میں خدا سے ڈرتا ہوں:\n19۔ اگر تم {سچے} ہو، تو اپنے بھائیوں میں سے کسی کو تمہارے قید کے گھر میں باندھا جائے: جاؤ، اپنے گھروں کے قحط کے لیے اناج لے جاؤ:\n20۔ لیکن اپنے سب سے چھوٹے بھائی کو میرے پاس لے آؤ؛ اسی طرح تمہارے الفاظ کی تصدیق ہو گی، اور تم نہیں مرو گے۔ اور انہوں نے ایسا ہی کیا۔\n21۔ اور انہوں نے ایک دوسرے سے کہا، ہم اپنے بھائی کے بارے میں واقعی قصوروار ہیں، کیونکہ ہم نے اس کی روح کا دکھ دیکھا، جب اس نے ہم سے درخواست کی، اور ہم سننے کو تیار نہیں تھے؛ لہٰذا یہ پریشانی ہم پر آ گئی ہے۔\n22۔ اور روبن نے ان کا جواب دیا، کہا، میں نے تم سے یہ نہیں کہا کہ بچے کے خلاف گناہ مت کرنا؛ اور تم سننا نہیں چاہتے؟ لہٰذا، دیکھو، اس کا خون بھی درکار ہے۔\n23۔ اور انہیں معلوم نہیں تھا کہ یوسف انہیں سمجھتا ہے؛ کیونکہ اس نے ایک مترجم کے ذریعے ان سے بات کی۔ {اس نے کہا...: عبوری۔ ان کے درمیان ایک مترجم تھا}\n24۔ اور اس نے ان سے منہ موڑ لیا اور رویا؛ اور پھر ان کے پاس واپس آیا، ان سے رابطہ کیا، ان سے شمعون لے کر ان کی آنکھوں کے سامنے باندھ دیا۔\n25۔ پھر یوسف نے حکم دیا کہ ان کے تھیلوں کو اناج سے بھر دیں، اور ہر آدمی کا پیسہ اس کے تھیلے میں واپس رکھیں، اور انہیں راستے کے لیے سامان دیا جائے: اور اس نے انہیں ایسا ہی کیا۔\n26۔ اور انہوں نے اپنے گدھے اناج سے بھر دیے اور وہاں سے روانہ ہو گئے۔\n27۔ اور جب ان میں سے ایک نے اپنا تھیلا کھول کر سرائے میں اپنی گانڈ پرووینڈر دی، تو اس نے اپنے پیسے دیکھے؛ کیونکہ دیکھو، وہ اس کے تھیلے کے منہ میں تھا۔\n28۔ اور اس نے اپنے بھائیوں سے کہا، میرا پیسہ واپس آ گیا ہے؛ اور، دیکھو، {یہ ہے} یہاں تک کہ میرے بوری میں بھی: اور ان کا دل ناکام ہو گیا، اور وہ ڈر گئے، ایک دوسرے سے کہہ رہے تھے، یہ {یہ} خدا نے ہمارے ساتھ کیا کیا ہے؟ {ناکام...: عبوری۔ آگے بڑھا}\n29۔ اور وہ اپنے باپ یعقوب کے پاس کنعان کی سرزمین آئے اور اسے وہ سب کچھ بتایا جو ان کے ساتھ ہوا؛ کہتا ہے،\n30۔ وہ آدمی، جو زمین کا مالک ہے، ہم سے سختی سے بات کرتا ہے اور ہمیں ملک کے جاسوس سمجھتا ہے۔ {تقریبا...: عبرانی۔ ہمارے ساتھ مشکل چیزیں}\n31۔ اور ہم نے اس سے کہا، ہم {ہیں} سچے {انسان}؛ ہم جاسوس نہیں ہیں:\n32. ہم بارہ بھائی ہیں، اپنے باپ کے بیٹے؛ ایک {نہیں}، اور سب سے چھوٹا {ہے} آج ہمارے والد کے ساتھ کنعان کی سرزمین میں۔\n33۔ اور اس آدمی، ملک کے مالک، نے ہم سے کہا، اس سے میں جانوں گا کہ تم سچے {لوگ} ہو؛ اپنے بھائیوں میں سے کسی کو {یہاں} میرے ساتھ چھوڑ دو، اور اپنے گھروں کے قحط کے لیے {کھانا} لے لو، اور چلے جاؤ:\n34۔ اور اپنے سب سے چھوٹے بھائی کو میرے پاس لے آؤ: تب میں جان جاؤں گا کہ تم جاسوس نہیں ہو، بلکہ {یہ} کہ تم {سچے} لوگ ہو: تو میں تمہیں تمہارا بھائی دوں گا، اور تم زمین میں تجارت کرو گے۔\n35۔ اور جب وہ اپنے تھیلے خالی کر رہے تھے، تو ہر آدمی کا پیسے کا گٹھا اس کے تھیلے میں تھا، اور جب وہ اور ان کے والد دونوں نے پیسے کے گچھے دیکھے تو وہ ڈر گئے۔\n36۔ اور ان کے والد یعقوب نے ان سے کہا، \"تم نے میرے بچوں کا سوگ مجھے کھو دیا ہے: یوسف نہیں، اور شمعون نہیں، اور تم بنیامین کو لے جاؤ گے: یہ سب میرے خلاف ہے۔\n37۔ اور روبن نے اپنے والد سے کہا، \"میرے دو بیٹوں کو مار ڈالا، اگر میں اسے تمہارے پاس نہ لاؤں، تو اسے میرے ہاتھ میں دے دو، اور میں اسے دوبارہ تمہارے پاس لے آؤں گا۔\n38۔ اور اس نے کہا، میرا بیٹا تمہارے ساتھ نہیں جائے گا؛ کیونکہ اس کا بھائی مر چکا ہے، اور وہ اکیلا رہ گیا ہے: اگر اس پر اس راستے سے کوئی مصیبت آ جائے جس میں تم جا رہے ہو، تو تم میرے سفید بال غم کے ساتھ قبر تک لے جاؤ گے۔","1۔ اور قحط زمین میں شدید تھا۔\n2۔ اور ایسا ہوا، جب انہوں نے وہ اناج کھا لیا جو انہوں نے مصر سے نکالا تھا، تو ان کے والد نے ان سے کہا، دوبارہ جاؤ، ہمیں تھوڑا سا کھانا خرید دو۔\n3۔ اور یہوداہ نے اس سے کہا، 'اس آدمی نے سنجیدگی سے ہم سے احتجاج کیا، کہا، تم میرا چہرہ نہیں دیکھو گے، سوائے اپنے بھائی کے جو تمہارے ساتھ ہو۔ {کیا...: عبرانی۔ احتجاج کرتے ہوئے}\n4۔ اگر تم ہمارے بھائی کو ہمارے ساتھ بھیجو گے، تو ہم نیچے جا کر تمہیں کھانا خریدیں گے:\n5۔ لیکن اگر تم اسے نہیں بھیجو گے، تو ہم نیچے نہیں جائیں گے: کیونکہ اس آدمی نے ہم سے کہا، تم میرا چہرہ نہیں دیکھو گے، سوائے اپنے بھائی کے جو تمہارے ساتھ ہو۔\n6۔ اور اسرائیل نے کہا، \"تم نے میرے ساتھ اتنا برا کیوں کیا، {جیسے} اس آدمی کو بتایا کہ کیا تمہارا بھائی ہے؟\n7۔ اور انہوں نے کہا، اس آدمی نے ہم سے ہماری حالت اور ہمارے رشتہ داروں کے بارے میں سختی سے پوچھا، کہا، {کیا} تمہارے والد ابھی زندہ ہیں؟ کیا تمہارا کوئی اور بھائی ہے؟ اور ہم نے انہیں ان الفاظ کے لہجے کے مطابق بتایا: کیا ہم یقین کر سکتے ہیں کہ وہ کہیں گے، اپنے بھائی کو نیچے لے آؤ؟ {پوچھا...: عبرانی۔ ہم سے پوچھا} {ٹینور: عبرانی۔ منہ} {ہو سکتا ہے...: عبرانی۔ جانتے ہوئے کہ کیا ہم جان سکتے ہیں}\n8۔ اور یہوداہ نے اسرائیل سے اپنے باپ سے کہا، لڑکے کو میرے ساتھ بھیجو، ہم اٹھیں گے اور جائیں گے؛ تاکہ ہم زندہ رہیں، نہ مریں، ہم دونوں، اور آپ بھی، {اور} اپنے چھوٹے بچے بھی۔\n9. میں اس کے لیے ضمانت دوں گا؛ تم اسے میرے ہاتھ سے مانگو گے: اگر میں اسے تمہارے پاس نہ لاؤں اور تمہارے سامنے نہ رکھوں، تو مجھے ہمیشہ کے لیے اس الزام کا سامنا کرنا پڑے گا:\n10۔ کیونکہ جب تک ہم ٹھہرے، تو یقینا اب ہم دوسری بار واپس آ چکے تھے۔ {یہ: یا، اس سے دو بار}\n11۔ اور ان کے والد اسرائیل نے ان سے کہا، اگر اب ایسا ہی ہے تو یہ کرو؛ زمین کے بہترین پھلوں میں سے اپنے برتنوں میں رکھو، اور اس آدمی کو تحفہ، ایک چھوٹا مرہم، اور تھوڑا سا شہد، مصالحے، مر، گری دار میوے اور بادام لے جاؤ:\n12۔ اور اپنے ہاتھ میں دوگنا پیسہ لے لیں؛ اور جو پیسہ تمہارے تھیلوں کے منہ میں دوبارہ لایا گیا، اسے دوبارہ اپنے ہاتھ میں لے جاؤ؛ لیکن یہ محض ایک غفلت تھی:\n13۔ اپنے بھائی کو بھی لے جاؤ، اور اٹھو، دوبارہ اس آدمی کے پاس جاؤ:\n14۔ اور خدا قادر مطلق تمہیں اس آدمی کے سامنے رحم دے، تاکہ وہ تمہارے دوسرے بھائی اور بنیامین کو بھیج دے۔ اگر میں اپنے بچوں کا سوگوار ہو جاؤں، تو میں سوگوار ہوں۔ {اگر...: یا، اور میں، جیسا کہ میں رہا ہوں، وغیرہ}\n15۔ اور مردوں نے وہ تحفہ لیا، اور اپنے ہاتھ میں دوگنا پیسہ لیا، اور بنیمن؛ اور اٹھ کھڑا ہوا، مصر میں نیچے گیا، اور یوسف کے سامنے کھڑا ہو گیا۔\n16۔ اور جب یوسف نے بنیامین کو ان کے ساتھ دیکھا، تو اس نے اپنے گھرانے کے حکمران سے کہا، ان لوگوں کو گھر لے آؤ، قتل کرو، اور تیار ہو جاؤ؛ کیونکہ {یہ} لوگ دوپہر کو میرے ساتھ کھانا کھائیں گے۔ {سلی: ہیب۔ قتل کرو} {ڈائن: ہیب۔ کھاؤ}\n17۔ اور اس آدمی نے یوسف کے حکم پر عمل کیا؛ اور وہ آدمی ان مردوں کو یوسف کے گھر لے آیا۔\n18۔ اور مرد ڈر گئے، کیونکہ انہیں یوسف کے گھر لایا گیا؛ اور انہوں نے کہا، کیونکہ پہلی بار ہمارے تھیلوں میں واپس آنے والے پیسے ہمیں لائے گئے ہیں؛ تاکہ وہ ہمارے خلاف موقع تلاش کرے، ہم پر گر جائے، اور ہمیں غلام اور ہمارے گدھے سمجھے۔ {تلاش کریں...: عببرانی۔ اپنے آپ کو ہم پر لڑھکتا ہے}\n19۔ اور وہ یوسف کے گھر کے منتظم کے قریب آئے، اور گھر کے دروازے پر اس سے بات چیت کی،\n20۔ اور کہا، اے صاحب، ہم واقعی پہلی بار کھانا خریدنے آئے تھے: {ہم...: عبرانی۔ نیچے آ رہے تھے ہم نیچے آئے}\n21۔ اور جب ہم سرائے پر پہنچے، تو ہم نے اپنے تھیلے کھولے، اور دیکھو، ہر آدمی کا پیسہ اس کے تھیلے کے منہ میں تھا، ہمارا پیسہ مکمل وزن میں: اور ہم نے اسے دوبارہ اپنے ہاتھ میں لے آیا۔\n22۔ اور دیگر پیسے جو ہم نے اپنے ہاتھوں میں کھانا خریدنے کے لیے لائے ہیں: ہم نہیں بتا سکتے کہ ہمارا پیسہ کس نے ہمارے تھیلوں میں رکھا۔\n23۔ اور اس نے کہا، تم پر سلامتی ہو، ڈرو مت: تمہارا خدا اور تمہارے باپ کے خدا نے تمہیں تمہارے تھیلوں میں خزانہ دیا ہے: میرے پاس تمہارا پیسہ تھا۔ اور اس نے شمعون کو ان کے پاس لے آیا۔ {میرے پاس...: عبرانی تمہارا پیسہ میرے پاس آیا}\n24۔ اور وہ آدمی ان لوگوں کو یوسف کے گھر لے آیا، انہیں پانی دیا، اور انہوں نے اپنے پاؤں دھوئے؛ اور اس نے انہیں ثبوت دیا۔\n25۔ اور انہوں نے دوپہر کو جوزف کے خلاف تحفہ تیار کیا، کیونکہ انہوں نے سنا کہ وہاں روٹی کھانی چاہیے۔\n26۔ اور جب یوسف گھر آیا، تو انہوں نے اس کے ہاتھ میں موجود تحفہ گھر میں لایا اور زمین کے سامنے اس کے سامنے جھک گئے۔\n27۔ اور اس نے ان سے ان کی خیریت کے بارے میں پوچھا اور کہا، {کیا تمہارا والد} خیریت سے ہے، وہ بوڑھا آدمی جس کے بارے میں تم نے بات کی؟ {کیا} وہ ابھی زندہ ہے؟ {ویلفیئر: عبرانی۔ امن} {کیا آپ کا...: عبرانی ہے۔ کیا تمہارے والد کو سکون ملتا ہے؟}\n28۔ اور انہوں نے جواب دیا، تیرا خادم ہمارا باپ صحت مند ہے، وہ ابھی زندہ ہے۔ اور انہوں نے سر جھکا کر سجدہ کیا۔\n29۔ اور اس نے اپنی آنکھیں اٹھائیں، اور اپنے بھائی بنیامین کو دیکھا، جو اس کی ماں کا بیٹا تھا، اور کہا، {کیا} یہ تمہارا چھوٹا بھائی ہے، جس کے بارے میں تم نے مجھ سے بات کی؟ اور اس نے کہا، خدا تم پر مہربان ہو، میرے بیٹے۔\n30۔ اور یوسف نے جلدی کی؛ کیونکہ اس کی آنتیں اپنے بھائی کے لیے تڑپ رہی تھیں: اور وہ رونے کی تلاش میں تھا؛ اور وہ {اپنے} کمرے میں داخل ہوا، اور وہاں رو پڑا۔\n31۔ اور اس نے اپنا چہرہ دھویا، باہر گیا، خود کو روک کر کہا، روٹی پر بیٹھ گیا۔\n32۔ اور وہ خود اس کے لیے روانہ ہوئے، اپنے لیے، اور ان مصریوں کے لیے جو اس کے ساتھ کھاتے تھے، اکیلے روانہ ہوئے: کیونکہ مصری عبرانیوں کے ساتھ روٹی نہیں کھا سکتے تھے؛ کیونکہ یہ مصریوں کے لیے ایک مکروہ ہے۔\n33۔ اور وہ اس کے سامنے بیٹھے تھے، سب سے بڑا اس کے پیدائشی حق کے مطابق، اور سب سے چھوٹا اپنی جوانی کے مطابق، اور مرد ایک دوسرے پر حیران رہ گئے۔\n34۔ اور اس نے اپنے سامنے سے ان کے لیے گندگی بھیجی: لیکن بنیامین کی گڑبڑ ان سب کے مقابلے میں پانچ گنا زیادہ تھی۔ اور وہ شراب پیتے، اور اس کے ساتھ خوش رہتے۔ {تھے...: عبرانی زیادہ پیتا تھا}","1۔ اور اس نے اپنے گھرانے کے منتظم کو حکم دیا، کہا، مردوں کے تھیلوں میں جتنا کھانا ہو سکے بھر دو، اور ہر آدمی کا پیسہ اس کے تھیلے کے منہ میں ڈال دو۔ {اسٹیورڈ...: عبرانی۔ وہ جو اس کے گھر کے اوپر تھا}\n2۔ اور میرا پیالہ، چاندی کا پیالہ، سب سے چھوٹے کے تھیلے کے منہ میں رکھ دو، اور اس کے مکئی کے پیسے۔ اور اس نے یوسف کے الفاظ کے مطابق ایسا کیا۔\n3۔ جیسے ہی صبح ہوئی، مردوں کو بھیج دیا گیا، وہ اور ان کے گدے۔\n4۔ {اور} جب وہ شہر سے باہر نکلے، {اور} ابھی زیادہ دور نہیں تھے، یوسف نے اپنے منتظم سے کہا، اوپر، مردوں کے پیچھے آؤ؛ اور جب تم انہیں پکڑ لو تو انہیں کہیں، تم نے برائی کو اچھائی کے بدلے کیوں بدلا؟\n5. کیا یہ وہ نہیں ہے جس میں میرا رب پیتا ہے، اور جس سے وہ خدا پاتا ہے؟ تم نے ایسا کر کے برائی کی ہے۔ {divineth: or, make trial میں؟}\n6۔ اور اس نے ان پر قبضہ کر لیا، اور وہی الفاظ ان سے کہے۔\n7۔ اور انہوں نے اس سے کہا، میرے رب یہ الفاظ کیوں کہتے ہیں؟ خدا نہ کرے کہ تمہارے خادم اس کے مطابق کریں:\n8۔ دیکھو، جو پیسہ ہم نے اپنے تھیلوں کے منہ میں پایا، وہ ہم نے کنعان کی زمین سے تمہارے پاس دوبارہ لائے: تو پھر ہم تمہارے مالک کے گھر سے چاندی یا سونا کیسے چرا سکتے ہیں؟\n9۔ جس کے ساتھ تمہارے بندوں میں سے یہ ملے گا، دونوں اسے مرنے دو، اور ہم بھی میرے رب کے غلام ہوں گے۔\n10۔ اور اس نے کہا، اب یہ بھی تمہارے الفاظ کے مطابق ہو جائے: جس کے پاس یہ ملے گا وہ میرا خادم ہوگا؛ اور تم بے قصور رہو گے۔\n11۔ پھر انہوں نے جلدی سے ہر آدمی کو اس کا تھیلا زمین پر گرا دیا، اور ہر آدمی کو اس کا تھیلا کھولا۔\n12۔ اور اس نے تلاش کی، {اور} سب سے بڑے سے شروع کیا، اور سب سے چھوٹے پر چھوڑا: اور پیالہ بنیامین کے تھیلے میں ملا۔\n13۔ پھر انہوں نے اپنے کپڑے کرایہ دیے، ہر آدمی کو اس کی پچھواڑے پر بٹھایا، اور شہر واپس چلے گئے۔\n14۔ اور یہوداہ اور اس کے بھائی یوسف کے گھر آئے؛ کیونکہ وہ ابھی وہاں تھا: اور وہ اس کے سامنے زمین پر گر گئے۔\n15۔ اور یوسف نے ان سے کہا، یہ کیا کام ہے جو تم نے کیا؟ کیا تم نہیں جانتے کہ ایسا آدمی جو میں واقعی خدا کے طور پر دیکھ سکتا ہوں؟ {الہی: یا، آزمائش کرو؟}\n16۔ اور یہوداہ نے کہا، ہم میرے رب سے کیا کہیں؟ ہم کیا بات کریں؟ یا ہم خود کو کیسے صاف کریں؟ خدا نے تمہارے بندوں کی بدکاری جان لی ہے: دیکھو، ہم میرے رب کے خادم ہیں، ہم بھی، اور وہ بھی جس کے پاس پیالہ پایا جاتا ہے۔\n17۔ اور اس نے کہا، خدا نہ کرے کہ میں ایسا کروں: {لیکن} جس آدمی کے ہاتھ میں پیالہ ہے، وہ میرا خادم ہوگا؛ اور جہاں تک تمہارا تعلق ہے، تمہیں سکون سے اپنے والد کے پاس لے جاؤ۔\n18۔ پھر یہوداہ اس کے قریب آیا اور کہا، اے میرے خداوند، میں دعا کرتا ہوں کہ اپنے بندے کو میرے آقا کے کانوں میں ایک لفظ کہہ دے، اور اپنے خادم پر غصہ نہ بھڑکے، کیونکہ تو بھی فرعون کی طرح ہو۔\n19۔ میرے آقا نے اپنے خادموں سے پوچھا، کہا، کیا تمہارا باپ ہے یا بھائی؟\n20۔ اور ہم نے میرے آقا سے کہا، ہمارے پاس ایک باپ ہے، ایک بوڑھا آدمی ہے، اور اس کی بوڑھی عمر کا ایک بچہ ہے، ایک چھوٹا؛ اور اس کا بھائی فوت ہو چکا ہے، اور اس کی ماں صرف وہی بچا ہے، اور اس کا باپ اسے چاہتا ہے۔\n21۔ اور تم نے اپنے بندوں سے کہا، اسے میرے پاس لے آؤ، تاکہ میں اس پر نظر ڈال سکوں۔\n22۔ اور ہم نے میرے آقا سے کہا، لڑکا اپنے والد کو چھوڑ نہیں سکتا: کیونکہ {اگر} وہ اپنے والد کو چھوڑ دے، {اس کا باپ} مر جائے گا۔\n23۔ اور تم نے اپنے خادموں سے کہا، جب تک تمہارا سب سے چھوٹا بھائی تمہارے ساتھ نیچے نہ آئے، تم میرا چہرہ نہیں دیکھو گے۔\n24۔ اور جب ہم تیرے خادم میرے والد کے پاس پہنچے تو ہم نے اسے میرے رب کے الفاظ سنائے۔\n25۔ اور ہمارے والد نے کہا، دوبارہ جاؤ، {اور} ہمیں تھوڑا سا کھانا خرید دو۔\n26۔ اور ہم نے کہا، ہم نیچے نہیں جا سکتے: اگر ہمارا سب سے چھوٹا بھائی ہمارے ساتھ ہے، تو ہم نیچے جائیں گے: کیونکہ ہم اس آدمی کا چہرہ نہیں دیکھ سکتے، سوائے اس کے کہ ہمارا سب سے چھوٹا بھائی ہمارے ساتھ ہو۔\n27۔ اور تیرے خادم میرے والد نے ہم سے کہا، تم جانتے ہو کہ میری بیوی نے مجھے دو بیٹے دیے:\n28۔ اور وہ جو مجھ سے نکلا، میں نے کہا، یقینا وہ ٹکڑے ٹکڑے ہو گیا ہے؛ اور میں نے اسے تب سے نہیں دیکھا:\n29۔ اور اگر تم یہ بھی مجھ سے لے لو اور اس پر کوئی مصیبت آئے، تو تم میرے سفید بال غم سے قبر تک لے آؤ گے۔\n30۔ اب جب میں تمہارے بندے کے پاس آتا ہوں، میرے والد اور لڑکا {ہوا} ہمارے ساتھ نہ ہو؛ یہ دیکھ کر کہ اس کی زندگی لڑکے کی زندگی میں جڑی ہوئی ہے؛\n31. یہ ہو جائے گا، جب وہ دیکھے گا کہ لڑکا {ہمارے ساتھ} نہیں ہے، تو وہ مر جائے گا: اور تمہارے خادم تمہارے خادم ہمارے باپ کے سفید بال غم کے ساتھ قبر تک لے جائیں گے۔\n32۔ کیونکہ تمہارا خادم لڑکے کے لیے میرے والد کے لیے ضمانت بن گیا، اور کہا، اگر میں اسے تمہارے پاس نہ لاؤں تو میں ہمیشہ اپنے باپ کا الزام اٹھاؤں گا۔\n33۔ اب میں تم سے درخواست کرتا ہوں کہ تمہارا بندہ میرے رب کا غلام لڑکے کی جگہ رہے؛ اور لڑکے کو اپنے بھائیوں کے ساتھ اوپر جانے دیا۔\n34۔ کیونکہ میں اپنے والد کے پاس کیسے جاؤں، اور لڑکا میرے ساتھ نہ ہو؟ کہیں میں اپنے والد پر آنے والی برائی نہ دیکھ لوں۔ {آؤ...: عبرانی۔ میرے والد کو ڈھونڈو}","1۔ پھر یوسف ان سب کے سامنے خود کو روک نہ سکا جو اس کے ساتھ کھڑے تھے؛ اور وہ رونے لگا، ہر آدمی کو مجھ سے دور کر دو۔ اور اس کے ساتھ کوئی آدمی نہیں تھا، جبکہ یوسف اپنے بھائیوں کو پہچان رہا تھا۔\n2۔ اور وہ زور زور سے رونے لگا: اور مصریوں اور فرعون کے خاندان نے سنا۔ {روتے ہوئے...: عبرانی۔ روتے ہوئے اپنی آواز نکالی}\n3۔ اور یوسف نے اپنے بھائیوں سے کہا، میں یوسف ہوں؛ کیا میرے والد ابھی زندہ ہیں؟ اور اس کے بھائی اسے جواب نہ دے سکے؛ کیونکہ وہ اس کی موجودگی سے پریشان تھے۔ {پریشان: یا، خوفزدہ}\n4۔ اور یوسف نے اپنے بھائیوں سے کہا، میرے قریب آؤ، میں تم سے دعا کرتا ہوں۔ اور وہ قریب آ گئے۔ اور اس نے کہا، میں یوسف ہوں، تمہارا بھائی، جسے تم نے مصر میں بیچ دیا۔\n5۔ اب غم نہ کرو، نہ اپنے آپ پر غصہ ہو، نہ ہی اپنے آپ پر غصہ ہو، کہ تم نے مجھے یہاں بیچ دیا، کیونکہ خدا نے مجھے تمہارے سامنے بھیجا ہے تاکہ زندگی بچا سکوں۔ {نہیں...: عبوری۔ نہ ہی تمہاری آنکھوں میں غصہ ہونے دو}\n6۔ ان دو سالوں سے {قحط} زمین میں {رہا ہے}؛ اور پھر {پانچ سال} ہیں، جن میں {وہاں نہ {کانا} ہوگا اور نہ ہی کٹائی۔\n7۔ اور خدا نے مجھے تمہارے سامنے بھیجا تاکہ تمہیں زمین پر آنے والی نسلوں کی حفاظت کروں، اور تمہاری جانیں عظیم نجات کے ذریعے بچاؤں۔ {محفوظ کرنے کے لیے...: عبرانی تمہارے لیے ایک باقیات رکھنا}\n8۔ تو اب {یہ} تم نے نہیں بھیجا بلکہ خدا نے مجھے بھیجا: اور اس نے مجھے فرعون کا باپ بنایا، اپنے تمام گھرانے کا سردار بنایا، اور پورے مصر کی سرزمین پر حکمران بنایا۔\n9۔ جلدی کرو اور میرے والد کے پاس جاؤ اور اسے کہیں، تمہارا بیٹا یوسف یوں کہتا ہے، خدا نے مجھے پورے مصر کا مالک بنایا ہے: میرے پاس آؤ، دیر نہ کرو:\n10۔ اور تم گوشن کی سرزمین میں رہو گے، اور میرے قریب رہو گے، تم، اور تمہارے بچوں، اور اپنے بچوں کے بچے، اور تمہارے ریوڑ، اپنے ریوڑ، اور جو کچھ بھی تمہارے پاس ہے، اس کے قریب رہو گے:\n11۔ اور وہاں میں تمہیں خوراک دوں گا؛ کیونکہ {ابھی بھی} پانچ سال قحط کے ہیں؛ کہیں تم، تمہارا گھرانہ، اور جو کچھ بھی تمہارے پاس ہے، غربت میں نہ چلے جائیں۔\n12. اور دیکھو، تمہاری آنکھیں دیکھتی ہیں، اور میرے بھائی بنیامین کی آنکھیں، کہ یہ میرا منہ ہے جو تم سے بات کرتا ہے۔\n13۔ اور تم میرے والد کو میری مصر میں میری تمام شان و شوکت اور جو کچھ تم نے دیکھا ہے اس کے بارے میں بتاؤ گے؛ اور تم جلدی کرو گے اور میرے والد کو یہاں لے آؤ گے۔\n14۔ اور وہ اپنے بھائی بنیامین کی گردن پر گر پڑا اور رونے لگا؛ اور بنیامین اس کی گردن پر رو پڑا۔\n15۔ اس کے علاوہ اس نے اپنے تمام بھائیوں کو بوسہ دیا، اور ان پر رویا، اور اس کے بعد اس کے بھائیوں نے اس سے بات کی۔\n16۔ اور اس کی شہرت فرعون کے گھر میں سنی گئی، کہا گیا، یوسف کے بھائی آ گئے ہیں: اور یہ فرعون اور اس کے خادموں کو بہت پسند آیا۔ {خوش...: عبرانی۔ فرعون کی نظر میں اچھا تھا}\n17۔ اور فرعون نے یوسف سے کہا، اپنے بھائیوں سے کہو، یہی کرو؛ اپنے جانور اتارو، اور جاؤ، تمہیں کنعان کی سرزمین لے جاؤ؛\n18۔ اور اپنے والد اور اپنے گھر والوں کو لے کر میرے پاس آؤ، اور میں تمہیں مصر کی سرزمین کی بھلائی دوں گا، اور تم زمین کی چربی کھاؤ گے۔\n19۔ اب تمہیں حکم دیا گیا ہے، یہ کرو؛ اپنے چھوٹے بچوں اور بیویوں کے لیے مصر کی سرزمین سے گاڑیاں لے جاؤ، اور اپنے والد کو لے آؤ، اور آؤ۔\n20. اپنی چیزوں کو بھی نہ دیکھیں؛ پورے مصر کی بھلائی کے لیے، سرزمین تمہارا ہے۔ {مشاہدہ...: عبرانی۔ اپنی آنکھ کو معاف نہ کرو وغیرہ۔}\n21۔ اور بنی اسرائیل نے ایسا ہی کیا: اور یوسف نے انہیں فرعون کے حکم کے مطابق گاڑیاں دیں اور راستے کے لیے سامان دیا۔ {حکم: عبرانی۔ منہ}\n22۔ ان سب کو اس نے ہر آدمی کو لباس میں تبدیلی دی؛ لیکن بینجمن کو تین سو چاندی کے سکے اور پانچ لباس کے سکے دیے۔\n23۔ اور اس نے اپنے والد کو اس {طریقے} کے پیچھے بھیجا؛ دس گدھے مصر کی اچھی چیزوں سے بھرے ہوئے ہیں، اور دس گدھے جو اس کے والد کے لیے اناج اور روٹی اور گوشت سے بھرے ہوئے ہیں۔ {laden...: عبرانی کیرینگ}\n24۔ تو اس نے اپنے بھائیوں کو روانہ کیا، اور وہ روانہ ہو گئے، اور اس نے ان سے کہا، دیکھو کہ راستے میں اختلاف نہ کرنا۔\n25۔ اور وہ مصر سے نکل کر کنعان کی سرزمین میں اپنے والد یعقوب کے پاس پہنچے،\n26۔ اور اسے بتایا، کہ یوسف ابھی زندہ ہے، اور وہ مصر کی تمام سرزمین کا حکمران ہے۔ اور یعقوب کا دل بے ہوش ہو گیا، کیونکہ وہ ان پر یقین نہیں کرتا تھا۔ {یعقوب کا: عبرانی۔ اس کی}\n27۔ اور انہوں نے اسے یوسف کے تمام الفاظ سنائے جو اس نے ان سے کہے تھے: اور جب اس نے وہ گاڑیاں دیکھیں جو یوسف نے اسے لے جانے کے لیے بھیجی تھیں، تو ان کے والد یعقوب کی روح جاگ اٹھی:\n28۔ اور اسرائیل نے کہا، {بس} کافی ہے؛ یوسف میرا بیٹا {ہے} ابھی زندہ ہے: میں مرنے سے پہلے جا کر اسے دیکھوں گا۔","1۔ اور اسرائیل نے اپنی تمام توانائیاں لے کر سفر کیا، اور بیرشبع آیا، اور اپنے باپ اسحاق کے خدا کے لیے قربانیاں پیش کیں۔\n2۔ اور خدا نے رات کے خوابوں میں اسرائیل سے بات کی اور کہا، یعقوب، یعقوب۔ اور اس نے کہا، یہاں {میں} ہوں۔\n3۔ اور اس نے کہا، میں خدا ہوں، تمہارے باپ کا خدا: مصر میں جانے سے نہ ڈرو؛ کیونکہ میں وہاں تمہیں ایک عظیم قوم بناؤں گا:\n4۔ میں تمہارے ساتھ مصر میں جاؤں گا؛ اور میں تمہیں دوبارہ اوپر لاؤں گا: اور یوسف تمہاری آنکھوں پر ہاتھ رکھے گا۔\n5۔ اور یعقوب بیرشبع سے اٹھا: اور اسرائیل کے بیٹوں نے یعقوب کو اپنے باپ، اپنے چھوٹے بچوں اور بیویوں کو ان گاڑیوں میں اٹھایا جو فرعون نے اسے لے جانے کے لیے بھیجی تھیں۔\n6۔ اور انہوں نے اپنے مویشی اور سامان جو انہوں نے کنعان کی سرزمین سے حاصل کیا تھا، لے کر مصر میں آئے، یعقوب اور اس کی تمام نسل اس کے ساتھ:\n7۔ اس کے بیٹے، اور اس کے بیٹوں کے بیٹے اس کے ساتھ، اس کی بیٹیاں، اور اس کے بیٹوں کی بیٹیاں، اور اس کی تمام نسل اسے اپنے ساتھ مصر لے آئی۔\n8۔ اور یہ اسرائیل کے بچوں کے نام ہیں، جو مصر میں آئے، یعقوب اور اس کے بیٹے: روبن، یعقوب کا پہلا بیٹا۔\n9۔ اور روبن کے بیٹے؛ حنوخ، اور فالو، اور ہیزرون، اور کارمی۔\n10۔ اور شمعون کے بیٹے؛ جیموئیل، یمین، اوہاد، یاخین، زہار، اور شاؤل، جو ایک کنعانی عورت کا بیٹا تھا۔ {جیموئل: یا، نیموئل} {جاچن: یا، جریب} {زہار: یا، زراح}\n11۔ اور لاوی کے بیٹے؛ گرشون، کوہاتھ، اور میراری۔ {گرشون: یا، گرشوم}\n12۔ اور یہوداہ کے بیٹے؛ ار، اور اونان، اور شلہ، اور فراز، اور زراح: لیکن ار اور اونان کنعان کی سرزمین میں مر گئے۔ اور فراز کے بیٹے حزرون اور ہمول تھے۔\n13۔ اور اساکر کے بیٹے؛ تولا، اور پھواہ، اور ایوب، اور شمرون۔ {پھواہ، اور ایوب: یا، پواہ، اور یعقوب}\n14۔ اور زبولون کے بیٹے؛ سیرڈ، ایلون، اور جہلیل۔\n15۔ یہ لیہ کے بیٹے ہیں، جو اس نے یعقوب کو پڈانارم میں اس کی بیٹی دینا کے ساتھ جنم دیا: اس کے بیٹوں اور بیٹیوں کی تمام روحیں تیس اور تین سال کی تھیں۔\n16۔ اور گاد کے بیٹے؛ زیفیون، اور ہاگی، شونی، اور ایزبون، ایری، اور ارودی، اور اریلی۔ {زیفیون: یا، زیفون} {ایزبون: یا، اوزنی} {آرودی: یا، آرود}\n17۔ اور آشر کے بیٹے؛ جمنا، اور اشواح، اور اسوئی، اور بریہ، اور ان کی بہن سیراح؛ اور بریاہ کے بیٹے؛ ہیبر، اور مالکیئل۔\n18۔ یہ زلپا کے بیٹے ہیں، جنہیں لابان نے اپنی بیٹی لیا کو دیے، اور یہ اس نے یعقوب کو جنم دیا، {حتیٰ کہ} سولہ روحیں۔\n19۔ ریچل جیکب کی بیوی کے بیٹے؛ جوزف، اور بینجمن۔\n20۔ اور مصر کی سرزمین میں یوسف کے ہاں منسی اور افرائیم پیدا ہوئے، جنہیں اسینات، پوٹیفیرا کے کاہن آف اون کی بیٹی نے اسے جنم دیا۔ {پادری: یا، شہزادہ}\n21۔ اور بنیامین کے بیٹے تھے: بلح، بیخر، اشبل، جیرا، نعمان، ایحی، روش، مپیم، ہپیم اور ارد۔ {ایہی: یا، اہیرم} {مپیم: یا، شفہم یا، شوپم} {ہپم: یا، ہپھام}\n22۔ یہ {ہیں} ریحیل کے بیٹے، جو یعقوب کے ہاں پیدا ہوئے: تمام روحیں {چودہ} تھیں۔\n23۔ اور دان کے بیٹے؛ ہشم۔ {ہشیم: یا، شوہام}\n24۔ اور نفتالی کے بیٹے؛ جہزیل، اور گونی، اور جیزر، اور شلم۔\n25۔ یہ بلحا کے بیٹے ہیں، جنہیں لابان نے اپنی بیٹی راحیل کو دیے، اور وہ یہ یعقوب کو دیتی ہے: تمام روحیں سات تھیں۔\n26۔ وہ تمام روحیں جو یعقوب کے ساتھ مصر آئیں، جو اس کی کمر سے نکلیں، یعقوب کے بیٹوں کی بیویوں کے علاوہ، تمام روحیں 300 اور 6 سال کی تھیں؛ {لوئنز: عبرانی۔ ران}\n27۔ اور یوسف کے بیٹے، جو مصر میں پیدا ہوئے، دو روحیں تھے: یعقوب خاندان کی تمام روحیں جو مصر میں آئیں، تین سو اور دس تھیں۔\n28۔ اور اس نے یہوداہ کو اپنے سامنے یوسف کے پاس بھیجا، تاکہ اس کا چہرہ گوشن کی طرف رخ کرے؛ اور وہ گوشن کی سرزمین میں آئے۔\n29۔ اور یوسف نے اپنی رتھ تیار کی، اور اپنے باپ اسرائیل سے ملنے کے لیے گوشن گیا اور اس کے سامنے پیش ہوا؛ اور وہ اپنی گردن کے بل گر گیا، اور کافی دیر تک اس کی گردن پر روتا رہا۔\n30۔ اور اسرائیل نے یوسف سے کہا، اب مجھے مرنے دو، کیونکہ میں نے تمہارا چہرہ دیکھ لیا ہے، کیونکہ تم ابھی زندہ ہو۔\n31۔ اور یوسف نے اپنے بھائیوں اور اپنے باپ کے گھر سے کہا، میں اوپر جاؤں گا، فرعون کو دکھاؤں گا، اور اسے کہوں گا، میرے بھائی اور میرے والد کا گھر، جو کنعان کی سرزمین میں تھے، میرے پاس آ گئے ہیں؛\n32۔ اور مرد چرواہے ہیں، کیونکہ ان کا کام مویشیوں کو کھلانا رہا ہے؛ اور انہوں نے اپنے ریوڑ، اپنے ریوڑ اور جو کچھ بھی ان کے پاس ہے، سب کچھ ساتھ لایا ہے۔ {ان کا کاروبار...: عبرانی۔ وہ مویشیوں کے آدمی ہیں}\n33۔ اور یہ تب ہوگا جب فرعون تمہیں پکار گا اور کہے گا، تمہارا پیشہ کیا ہے؟\n34۔ کہ تم کہو گے، تمہارے بندوں کا کاروبار ہماری جوانی سے لے کر اب تک مویشیوں کے بارے میں رہا ہے، ہم بھی، {اور} ہمارے آباؤ اجداد بھی، تاکہ تم گوشن کی سرزمین میں رہ سکو؛ کیونکہ ہر چرواہا مصریوں کے لیے مکروہ ہے۔","1۔ پھر یوسف آیا اور فرعون کو بتایا اور کہا، میرے والد اور میرے بھائی، ان کے ریوڑ، ان کے ریوڑ اور جو کچھ ان کے پاس ہے، وہ کنعان کی زمین سے نکلے ہیں؛ اور دیکھو، وہ گوشن کی سرزمین میں ہیں۔\n2۔ اور اس نے اپنے کچھ بھائیوں میں سے، {حتیٰ کہ} پانچ آدمیوں کو لے کر فرعون کے سامنے پیش کیا۔\n3۔ اور فرعون نے اپنے بھائیوں سے کہا، آپ کا کام کیا ہے؟ اور انہوں نے فرعون سے کہا، تیرے خادم چرواہے ہیں، ہم بھی، اور ہمارے باپ دادا بھی۔\n4۔ انہوں نے فرعون سے کہا، کیونکہ ہم زمین میں قیام کے لیے آئے ہیں؛ کیونکہ تمہارے بندوں کے پاس اپنے ریوڑ کے لیے کوئی چراگاہ نہیں؛ کیونکہ قحط کنعان کی سرزمین میں شدید ہے: اب ہم دعا کرتے ہیں کہ تمہارے بندے گوشن کی سرزمین میں رہیں۔\n5۔ اور فرعون نے یوسف سے کہا، کہ تمہارا باپ اور تمہارے بھائی تمہارے پاس آ گئے ہیں:\n6۔ مصر کی سرزمین {ہے} تمہارے سامنے؛ زمین کے بہترین حصے میں اپنے والد اور بھائیوں کو آباد کرو؛ گوشن کی سرزمین میں انہیں رہنے دو: اور اگر تم ان میں سے کسی سرگرم آدمی کو جانتے ہو تو انہیں میرے مویشیوں کے حکمران بنا دو۔\n7۔ اور یوسف نے اپنے والد یعقوب کو بلایا اور فرعون کے سامنے رکھا، اور یعقوب نے فرعون کو برکت دی۔\n8۔ اور فرعون نے یعقوب سے کہا، تمہاری عمر کیا ہے؟ {کیسے...: عبرانی تمہاری زندگی کے کتنے دن گزرے ہیں؟}\n9۔ اور یعقوب نے فرعون سے کہا، میری زیارت کے سالوں کے دن ایک سو تیس سال ہیں: میری زندگی کے سالوں کے دن بہت کم اور برے رہے ہیں، اور میرے آباؤ اجداد کی زندگی کے دنوں کے دنوں تک نہیں پہنچے ہیں۔\n10۔ اور یعقوب نے فرعون کو برکت دی، اور فرعون کے سامنے سے باہر نکل گیا۔\n11۔ اور یوسف نے اپنے والد اور اپنے بھائیوں کو آباد کیا، اور انہیں مصر کی سرزمین میں، بہترین زمین میں، رامسیس کی سرزمین میں، جیسا کہ فرعون نے حکم دیا تھا۔\n12۔ اور یوسف نے اپنے باپ، اپنے بھائیوں کو، اور اپنے والد کے گھرانے کے تمام گھرانے کو ان کے خاندانوں کے مطابق روٹی سے خوراک دی۔ {مطابق...: یا، جیسے ایک چھوٹا بچہ خوراک پاتا ہے: عبرانی۔ چھوٹے بچوں کے مطابق}\n13۔ اور {تمام زمین میں} روٹی نہیں تھی؛ کیونکہ قحط بہت شدید تھا، یہاں تک کہ مصر کی زمین اور کنعان کی تمام زمین قحط کی وجہ سے بے ہوش ہو گئی۔\n14۔ اور یوسف نے مصر کی زمین اور کنعان کی زمین سے ملنے والی تمام دولت جمع کی، ان اناج کے لیے جو انہوں نے خریدا تھا: اور یوسف نے وہ رقم فرعون کے گھر لے آئی۔\n15۔ اور جب مصر کی سرزمین اور کنعان میں پیسہ ختم ہو گیا، تو تمام مصری یوسف کے پاس آئے اور کہا، ہمیں روٹی دو، کیونکہ ہم تیرے سامنے کیوں مریں؟ کیونکہ پیسہ ناکام ہو جاتا ہے۔\n16۔ اور یوسف نے کہا، اپنے مویشیوں کو دے دو؛ اور اگر پیسے ناکام ہو گئے تو میں تمہیں تمہارے مویشیوں کے بدلے دوں گا۔\n17۔ اور انہوں نے اپنے مویشی یوسف کے پاس لائے اور یوسف نے انہیں گھوڑوں، ریوڑوں، ریوڑوں کے مویشیوں اور گدھوں کے بدلے روٹی دی، اور اس نے انہیں اس سال کے لیے ان کے تمام مویشیوں کے لیے روٹی دی۔ {فیڈر...: عبرانی ان کی قیادت کی}\n18۔ جب وہ سال ختم ہوا، تو دوسرے سال وہ اس کے پاس آئے اور کہا، ہم اپنے آقا سے یہ نہیں چھپائیں گے کہ ہمارا پیسہ کیسے خرچ ہوتا ہے؛ میرے رب کے پاس ہمارے مویشیوں کے ریوڑ بھی ہیں؛ میرے رب کی نظر میں صرف ہمارے جسم اور ہماری زمینیں باقی ہیں:\n19. ہم تمہاری آنکھوں کے سامنے کیوں مریں گے، ہم اور اپنی زمین دونوں؟ ہمیں اور ہماری زمین کو روٹی کے طور پر خریدو، اور ہم اور ہماری زمین فرعون کے خادم بنیں گے: اور ہمیں بیج دیں گے، تاکہ ہم زندہ رہیں، نہ مریں، تاکہ زمین ویران نہ ہو۔\n20۔ اور یوسف نے فرعون کے لیے مصر کی ساری زمین خرید لی؛ کیونکہ مصریوں نے ہر آدمی کو اس کا کھیت بیچ دیا، کیونکہ قحط ان پر چھا گیا: یوں زمین فرعون کی بن گئی۔\n21۔ اور جہاں تک لوگوں کا تعلق ہے، اس نے انہیں مصر کی سرحدوں کے {ایک} سرے سے یہاں تک شہروں میں منتقل کر دیا، یہاں تک کہ اس کے {دوسرے} سرے تک۔\n22۔ صرف پادریوں کی زمین نے نہیں خریدی؛ کیونکہ کاہنوں کو فرعون کا حصہ دیا گیا تھا، اور انہوں نے اپنا حصہ کھا لیا جو فرعون نے دیا تھا، اس لیے انہوں نے اپنی زمینیں فروخت نہیں کیں۔ {پادری: یا، شہزادے}\n23۔ پھر یوسف نے لوگوں سے کہا، دیکھو، میں نے آج تمہیں اور تمہاری زمین فرعون کے لیے خرید لی ہے: دیکھو، یہ تمہارے لیے بیج ہے، اور تم زمین بوؤ گے۔\n24۔ اور یہ بڑھتے ہوئے ہوگا کہ تم پانچواں حصہ فرعون کو دو گے، اور چار حصے تمہارے ہوں گے، کھیت کے بیج، تمہارے کھانے کے لیے، اپنے گھرانوں کے لیے، اور اپنے چھوٹے بچوں کے کھانے کے لیے۔\n25۔ اور انہوں نے کہا، تو نے ہماری جانیں بچائی ہیں: آؤ ہم میرے رب کی نظر میں فضل پائیں اور ہم فرعون کے خادم بنیں گے۔\n26۔ اور یوسف نے آج تک مصر کی سرزمین پر قانون بنایا کہ فرعون کو پانچواں حصہ ملے؛ سوائے صرف پجاریوں کی زمین کے، {جو} فرعون کی نہیں بنی۔ {پادری: یا، شہزادے}\n27۔ اور اسرائیل مصر کی سرزمین گوشن میں آباد تھا؛ اور وہاں ان کے پاس جائیدادیں تھیں، جو بڑھتے اور بے حد بڑھتے گئے۔\n28۔ اور یعقوب مصر کی سرزمین میں سترہ سال رہا: یوں یعقوب کی پوری عمر ایک سو سینتالیس سال تھی۔ {پورا...: عبرانی۔ اس کی زندگی کے سالوں کے دن}\n29۔ اور وہ وقت قریب آیا جب اسرائیل کو مرنا تھا: اور اس نے اپنے بیٹے یوسف کو بلایا اور کہا، اگر اب میں نے تمہاری نظر میں فضل پایا ہے، تو میں دعا کرتا ہوں کہ اپنا ہاتھ میری ران کے نیچے رکھ کر میرے ساتھ مہربانی اور سچائی سے پیش آؤ؛ مجھے مصر میں دفن نہ کرنا، میں دعا کرتا ہوں:\n30۔ لیکن میں اپنے باپ اجداد کے ساتھ لیٹوں گا، اور تو مجھے مصر سے نکال کر ان کی قبرستان میں دفن کرو گے۔ اور اس نے کہا، میں وہی کروں گا جو تم نے کہا ہے۔\n31۔ اور اس نے کہا، مجھ سے قسم کھاؤ۔ اور وہ اس سے قسم کھاتا ہے۔ اور اسرائیل نے بستر کے سر پر جھک کر سلام کیا۔","1۔ اور ان واقعات کے بعد ہوا کہ {ایک} نے یوسف کو بتایا، دیکھو، تمہارا باپ بیمار ہے، اور اس نے اپنے دو بیٹوں، مناسی اور افرائیم کو ساتھ لے لیا۔\n2۔ اور {ایک} نے یعقوب سے کہا اور کہا، دیکھو، تمہارا بیٹا یوسف تمہارے پاس آتا ہے، اور اسرائیل نے خود کو مضبوط کیا اور بستر پر بیٹھ گیا۔\n3۔ اور یعقوب نے یوسف سے کہا، خدا قادر مطلق نے مجھے کنعان کی سرزمین لوز میں ظاہر کیا اور مجھے برکت دی،\n4۔ اور مجھ سے کہا، دیکھو، میں تمہیں پھلدار اور بڑھاؤں گا، اور تم سے لوگوں کی تعداد بناؤں گا؛ اور یہ زمین تمہارے بعد تمہاری نسل کو دے دوں گا {ہمیشہ کے لیے} ایک دائمی ملکیت کے لیے۔\n5۔ اور اب تمہارے دو بیٹے، افرائیم اور منسیہ، جو میرے مصر آنے سے پہلے مصر کی سرزمین میں پیدا ہوئے، میرے ہیں؛ روبن اور شمعون کی طرح، وہ میرے ہوں گے۔\n6۔ اور تمہاری اولاد، جو تم ان کے بعد پیدا کرو گی، وہ تمہارا ہوگا، {اور} ان کے بھائیوں کے نام پر ان کی وراثت میں پکارا جائے گا۔\n7۔ اور جہاں تک میرا تعلق ہے، جب میں پادان سے آیا، راحیل میرے ہاتھوں کنعان کی سرزمین میں اس راستے میں مر گئی، جب افراتھ تک پہنچنے کے لیے ابھی تھوڑا سا راستہ باقی تھا: اور میں نے اسے وہاں افرات کے راستے میں دفن کیا؛ وہی بیت لحم ہے۔\n8۔ اور اسرائیل نے یوسف کے بیٹوں کو دیکھا اور کہا، یہ کون ہیں؟\n9۔ اور یوسف نے اپنے باپ سے کہا، یہ میرے بیٹے ہیں، جنہیں خدا نے مجھے اس جگہ پر دیا ہے۔ اور اس نے کہا، میں تم سے دعا کرتا ہوں کہ انہیں میرے پاس لے آؤ، اور میں انہیں برکت دوں گا۔\n10. اب اسرائیل کی آنکھیں عمر کے لیے مدھم ہو گئی تھیں، {یہاں تک کہ} وہ دیکھ نہ سکے۔ اور اس نے انہیں اپنے قریب لایا؛ اور اس نے انہیں چوما، اور گلے لگا لیا۔ {مدھم: عبوری۔ ہیوی}\n11۔ اور اسرائیل نے یوسف سے کہا، میں نے تمہارا چہرہ دیکھنے کا سوچا ہی نہیں، اور دیکھو، خدا نے مجھے تمہاری نسل بھی دکھائی ہے۔\n12۔ اور یوسف نے انہیں گھٹنوں کے درمیان سے نکالا، اور زمین کے سامنے اپنا چہرہ جھکا لیا۔\n13۔ اور یوسف نے دونوں کو پکڑا، افرائیم اپنے دائیں ہاتھ میں اسرائیل کے بائیں ہاتھ کی طرف، اور منسی اپنے بائیں ہاتھ سے اسرائیل کے دائیں ہاتھ کی طرف، اور انہیں اپنے قریب لے آیا۔\n14۔ اور اسرائیل نے اپنا دایاں ہاتھ بڑھایا، اور افرایم کے سر پر رکھ دیا، جو {تھا} چھوٹا تھا، اور اپنا بایاں ہاتھ منسی کے سر پر رکھا، اپنے ہاتھوں کی رہنمائی کرتے ہوئے؛ کیونکہ مناسی سب سے بڑا تھا۔\n15۔ اور اس نے یوسف کو برکت دی اور کہا، خدا، جس کے سامنے میرے باپ و اجداد ابراہیم اور اسحاق چلے، وہ خدا جس نے مجھے ساری زندگی آج تک کھلایا ہے،\n16۔ وہ فرشتہ جس نے مجھے ہر برائی سے نجات دی، لڑکوں کو برکت دے؛ اور میرا نام ان پر لکھا جائے، اور میرے باپ و اجداد ابراہیم اور اسحاق کا نام بھی؛ اور انہیں زمین کے بیچ ایک ہجوم میں تبدیل ہونے دو۔ {بڑھو: عبوری۔ جیسے جیسے مچھلیاں بڑھتی ہیں}\n17۔ اور جب یوسف نے دیکھا کہ اس کے والد نے اپنا دایاں ہاتھ افرائیم کے سر پر رکھا ہے، تو وہ ناراض ہوا: اور اس نے اپنے والد کا ہاتھ اٹھا کر اسے افرایم کے سر سے ہٹا کر منسی کے سر تک پہنچایا۔ {ناراض...: اس کی نظر میں برائی تھی}\n18۔ اور یوسف نے اپنے باپ سے کہا، ایسا نہیں، میرے باپ، کیونکہ یہ سب سے بڑا ہے؛ اپنا دایاں ہاتھ اس کے سر پر رکھو۔\n19۔ اور اس کے والد نے انکار کر دیا، اور کہا، میں جانتا ہوں، میرے بیٹے، میں جانتا ہوں: وہ بھی ایک قوم بنے گا، اور وہ بھی عظیم ہوگا، لیکن حقیقت میں اس کا چھوٹا بھائی اس سے بڑا ہوگا، اور اس کی نسل کئی قومیں بن جائے گی۔ {کثیر: عبرانی۔ مکمل پن}\n20۔ اور اس دن انہوں نے انہیں برکت دی، کہا، اسرائیل تم میں برکت دے گا، کہہ رہا ہے، خدا تمہیں افرایم اور منشا بنائے: اور اس نے افرایم کو منسی کے سامنے رکھا۔\n21۔ اور اسرائیل نے یوسف سے کہا، دیکھو، میں مر جاؤں گا، لیکن خدا تمہارے ساتھ ہوگا، اور تمہیں تمہارے آباؤ اجداد کی سرزمین میں واپس لے آئے گا۔\n22۔ مزید برآں، میں نے تمہیں تمہارے بھائیوں سے ایک حصہ دیا ہے، جو میں نے اپنی تلوار اور کمان سے اموری کے ہاتھ سے لیا ہے۔","1۔ اور یعقوب نے اپنے بیٹوں کو بلایا اور کہا، سب اکٹھے ہو جاؤ، تاکہ میں تمہیں بتا سکوں کہ تم پر آخری دنوں میں کیا ہوگا۔\n2۔ سب اکٹھے ہو جاؤ، اور سنو، اے یعقوب کے بیٹو؛ اور اپنے باپ اسرائیل کی بات سنو۔\n3۔ روبن، تو میرے سب سے بڑے بیٹے ہو، میری طاقت ہو، اور میری طاقت، وقار کی برتری اور طاقت کی برتری کی ابتدا ہو:\n4۔ پانی کی طرح غیر مستحکم ہو، تم کامیاب نہیں ہو سکتے؛ کیونکہ تم اپنے والد کے بستر تک گئے تھے؛ پھر تم نے اسے ناپاک کیا: وہ میرے صوفے پر آ گیا۔ {تم چاہو گے...: عبرانی۔ کیا تم کمال نہیں کرتے} {وہ گیا...: ورنہ میرا صوفہ چلا گیا}\n5۔ شمعون اور لاوی بھائی ہیں؛ ظلم کے آلات ان کے گھروں میں ہیں۔ {آلات...: یا، ان کی تلواریں تشدد کے ہتھیار ہیں}\n6۔ اے میری جان، ان کے راز میں نہ آؤ؛ ان کے اجتماع سے، میری عزت، متحد نہ ہو: کیونکہ غصے میں انہوں نے ایک آدمی کو قتل کیا، اور اپنی مرضی سے دیوار کھود دی۔ {کھودنا...: یا، پھنسے ہوئے بیل}\n7۔ ان کے غصے پر لعنت ہوئی، کیونکہ وہ شدید تھا؛ اور ان کا غصہ، کیونکہ وہ ظالمانہ تھا: میں انہیں یعقوب میں تقسیم کر دوں گا، اور اسرائیل میں بکھیر دوں گا۔\n8۔ یہودا، تو وہ ہو جس کی تمہارے بھائی تعریف کریں گے: تمہارا ہاتھ تمہارے دشمنوں کی گردن میں ہوگا؛ تمہارے والد کے بچے تمہارے سامنے جھکیں گے۔\n9. یہوداہ شیر کا بچہ: شکار سے، میرے بیٹے، تو چڑھ گیا ہے: وہ جھک گیا، شیر کی طرح اور بوڑھے شیر کی طرح لیٹا؛ کون اسے جگائے؟\n10۔ عصا یہوداہ سے نہیں جائے گا، اور نہ ہی کوئی قانون ساز اس کے قدموں کے درمیان سے، جب تک کہ شیلوہ نہ آئے؛ اور اس کے لیے لوگوں کا اجتماع {ہوگا}۔\n11۔ اپنے گھوڑے کو بیل سے باندھنا، اور اپنے گدھے کے بچے کو منتخب بیل سے باندھنا؛ اس نے اپنے کپڑے شراب میں دھوئے، اور اپنے کپڑے انگور کے خون میں:\n12۔ اس کی آنکھیں شراب سے سرخ ہوں گی، اور اس کے دانت دودھ سے سفید ہوں گے۔\n13۔ زبولون سمندر کے پناہ گاہ میں رہے گا؛ اور وہ جہازوں کے پناہ گاہ کے لیے ہوگا؛ اور اس کی سرحد زیدون تک ہوگی۔\n14. اساکر ایک مضبوط پچھواڑا ہے جو دو بوجھوں کے درمیان چھپا ہوا ہے:\n15۔ اور اس نے دیکھا کہ آرام {تھا} اچھا تھا، اور زمین جو {وہ} خوشگوار تھی؛ اور کندھا جھکا کر خراج دینے کے لیے خادم بن گیا۔\n16۔ دان اپنے لوگوں کا فیصلہ کرے گا، اسرائیل کے قبائل میں سے ایک کے طور پر۔\n17۔ ویسے دان ایک سانپ ہوگا، راستے میں ایک ایڈر، جو گھوڑے کی ایڑیوں کو کاٹتا ہے، جس سے اس کا سوار پیچھے گر جائے گا۔ {ایک ایڈر: عبوری۔ ایک تیر-سانپ}\n18. اے خداوند، میں تیرے نجات کا انتظار کر رہا ہوں۔\n19۔ گاد، ایک فوج اسے شکست دے گی، لیکن وہ آخر میں شکست دے گا۔\n20۔ آشر سے اس کی روٹی {موٹی} ہو جائے گی، اور وہ شاہی لذیذ کپڑے پیدا کرے گا۔\n21. نفتالی ایک آزاد ہرن ہے: وہ نیک الفاظ دیتا ہے۔\n22۔ یوسف ایک زرخیز شاخ ہے، یہاں تک کہ کنویں کے پاس ایک زرخیز شاخ؛ {جس کی شاخیں} دیوار پر چلتی ہیں: {شاخیں: عبرانی۔ بیٹیاں}\n23۔ تیر اندازوں نے اس کا شدید غم منایا، اس پر گولیاں چلائیں اور اس سے نفرت کی:\n24۔ لیکن اس کا کمان مضبوط رہا، اور اس کے ہاتھوں کے بازو یعقوب کے طاقتور {خدا} کے ہاتھوں سے مضبوط ہوئے؛ (وہاں سے چرواہا، اسرائیل کا پتھر ہے:)\n25۔ {حتیٰ} اپنے باپ کے خدا کی قسم، جو تمہاری مدد کرے گا؛ اور قادر مطلق کی قسم، جو تمہیں اوپر آسمان کی برکتوں سے برکت دے گا، گہرائی کی برکتیں جو نیچے ہے، سینوں اور رحم کی برکتیں:\n26۔ تیرے باپ کی برکتیں میرے آباؤ اجداد کی برکتوں سے بڑھ کر ہمیشہ کے پہاڑوں کی انتہا تک غالب آ گئی ہیں: وہ یوسف کے سر پر ہوں گی، اور اس کے سر کے تاج پر جو اس کے بھائیوں سے الگ تھا۔\n27۔ بنیامین بھیڑیے کی طرح شیگو کرے گا: صبح شکار کو کھا جائے گا، اور رات کو مال تقسیم کرے گا۔\n28. یہ سب اسرائیل کے بارہ قبیلے ہیں: اور یہی ان کے والد نے ان سے بات کی اور انہیں برکت دی؛ ہر ایک نے اپنی برکت کے مطابق انہیں برکت دی۔\n29۔ اور اس نے انہیں حکم دیا، اور کہا، مجھے اپنے لوگوں کے پاس جمع کیا جائے گا: مجھے میرے آباؤ اجداد کے ساتھ اس غار میں دفن کر دو جو ایفرون دی ہٹی کے میدان میں ہے،\n30۔ اس غار میں جو {ہے} مکپیلہ کے میدان میں، جو {ہے} مامر کے سامنے، کنعان کی زمین میں، جسے ابراہیم نے افرون دی ہٹی کے کھیت سے قبرستان کے قبضے کے لیے خریدا تھا۔\n31۔ وہاں انہوں نے ابراہیم اور اس کی بیوی سارہ کو دفن کیا؛ وہاں انہوں نے اسحاق اور اس کی بیوی ربیکا کو دفن کیا؛ اور وہاں میں نے لیا کو دفن کیا۔\n32۔ اس میدان اور غار کی خریداری جو {ہے} ہیتھ کے بچوں سے حاصل کی گئی۔\n33۔ اور جب یعقوب نے اپنے بیٹوں کو حکم دینا ختم کر دیا، تو اس نے بستر میں اپنے پاؤں جمع کیے، بھوت کو حوالے کر دیا، اور اپنے لوگوں کے سامنے جمع ہو گیا۔","1۔ اور یوسف اپنے والد کے چہرے پر گر پڑا، اس پر رویا، اور اسے بوسہ دیا۔\n2۔ اور یوسف نے اپنے خادموں کو حکم دیا کہ وہ اس کے والد کو حنوط کریں: اور طبیبوں نے اسرائیل کو حنوط کر دیا۔\n3۔ اور اس کے لیے چالیس دن پورے ہوئے؛ کیونکہ ایسے ہی وہ دن پورے ہوتے ہیں جو حنوط کیے جاتے ہیں: اور مصریوں نے اس کے لیے تیس اور دس دن کا سوگ منایا۔ {سوگ مناتے ہوئے: عبرانی۔ رو پڑا}\n4۔ اور جب اس کے سوگ کے دن گزر گئے، یوسف نے فرعون کے گھرانے سے کہا، \"اگر اب میں نے تمہاری آنکھوں میں فضل پایا ہے، تو فرعون کے کانوں میں کہو، میں دعا کرتا ہوں، کہو،\n5۔ میرے والد نے مجھ سے قسم کھائی کہ میں مر جاؤں گا: اپنی قبر میں جو میں نے کنعان کی سرزمین میں اپنے لیے کھودی ہے، وہیں مجھے دفن کرو گے۔ اب اس لیے مجھے اوپر جانے دو، میں دعا کرتا ہوں، اور اپنے باپ کو دفن کرنے دو، اور میں دوبارہ آؤں گا۔\n6۔ اور فرعون نے کہا، اوپر جاؤ، اور اپنے باپ کو دفن کرو، جیسا کہ اس نے تم سے قسم لی تھی۔\n7۔ اور یوسف اپنے والد کو دفنانے کے لیے اوپر گیا، اور اس کے ساتھ فرعون کے تمام خادم، اس کے خاندان کے بزرگ، اور مصر کی سرزمین کے تمام بزرگ چلے گئے،\n8۔ اور یوسف کے تمام گھر، اس کے بھائیوں اور اس کے والد کے گھر، صرف ان کے چھوٹے، ان کے ریوڑ اور ان کے ریوڑ، جو انہوں نے گوشن کی سرزمین میں چھوڑ دیے۔\n9۔ اور اس کے ساتھ دونوں رتھ اور گھڑ سوار گئے: اور یہ بہت بڑی جماعت تھی۔\n10۔ اور وہ آتاد کے تھریشنگ فلور پر پہنچے، جو اردن کے پار ہے، اور وہاں انہوں نے بڑی اور بہت تکلیف دہ ماتم کی: اور اس نے اپنے والد کے لیے سات دن کا سوگ منایا۔\n11۔ اور جب اس سرزمین کے باشندے، کنعانیوں نے، اتاد کے فرش میں سوگ دیکھا، تو انہوں نے کہا، یہ مصریوں کے لیے ایک غمگین سوگ ہے: اسی لیے اس کا نام ابیلمزرائیم رکھا گیا، جو اردن کے پار ہے۔ {ابیلمزرائیم: یعنی، مصریوں کا سوگ}\n12۔ اور اس کے بیٹوں نے اس کے ساتھ ویسا ہی کیا جیسا اس نے انہیں حکم دیا:\n13۔ کیونکہ اس کے بیٹوں نے اسے کنعان کی سرزمین میں لے جا کر مکپیلہ کے کھیت کی غار میں دفن کیا، جو ابراہیم نے ایفرون دی ہٹی کی قبرستان کے لیے زمین کے ساتھ خریدا تھا، مامرے کے سامنے۔\n14۔ اور یوسف مصر واپس آیا، وہ اور اس کے بھائی، اور وہ سب جو اس کے ساتھ اپنے والد کو دفنانے کے لیے گیا تھا، جب اس نے اپنے والد کو دفن کر دیا تھا۔\n15۔ اور جب یوسف کے بھائیوں نے دیکھا کہ ان کا باپ مر چکا ہے، تو انہوں نے کہا، \"یوسف ہم سے نفرت کرے گا، اور یقینا ہمیں اس کے ساتھ کیے گئے تمام ظلم کا بدلہ دے گا۔\n16۔ اور انہوں نے یوسف کے پاس ایک پیغام بھیجا کہ تمہارے والد نے مرنے سے پہلے حکم دیا تھا، اور کہا، {بھیجا: عبرانی۔ چارجڈ}\n17. تو تم یوسف سے کہو کہو، میں اب تم سے دعا کرتا ہوں کہ اپنے بھائیوں کی گناہ اور ان کے گناہ کو معاف کر دو؛ کیونکہ انہوں نے تمہارے ساتھ برا کیا: اور اب، ہم تم سے دعا کرتے ہیں کہ اپنے باپ کے خدا کے بندوں کی غلطی کو معاف کر دو۔ اور جب وہ اس سے بات کرتے تو یوسف رو پڑا۔\n18۔ اور اس کے بھائی بھی اس کے سامنے گر گئے؛ اور انہوں نے کہا، دیکھو، ہم تمہارے بندے ہیں۔\n19۔ اور یوسف نے ان سے کہا، خوف نہ کرو: کیا میں خدا کی جگہ ہوں؟\n20۔ لیکن تم نے میرے خلاف برا سوچا؛ {لیکن} خدا نے اسے بھلائی کے لیے ارادہ کیا تھا، جیسا کہ آج ہے، تاکہ بہت سے لوگوں کو زندہ بچایا جا سکے۔\n21. اب خوف نہ کرو: میں تمہیں اور تمہارے بچوں کو غذا دوں گا۔ اور اس نے انہیں تسلی دی، اور مہربانی سے بات کی۔ {مہربانی سے...: عبرانی۔ ان کے دلوں کے لیے}\n22۔ اور یوسف مصر میں رہتا تھا، وہ اور اس کے والد کے گھر، اور یوسف ایک سو دس سال زندہ رہا۔\n23۔ اور یوسف نے افرائیم کے تیسری نسل کے بچوں کو دیکھا: مخر، منسی کے بیٹے کے بچے بھی یوسف کے گھٹنوں کے بل پرورش پائے گئے۔ {لایا...: عبوری۔ پیدائش}\n24۔ اور یوسف نے اپنے بھائیوں سے کہا، میں مر جاؤں گا: اور خدا ضرور تم سے آئے گا، اور تمہیں اس زمین سے نکال کر اس زمین میں لے آئے گا جس کی قسم اس نے ابراہیم، اسحاق اور یعقوب سے کی تھی۔\n25۔ اور یوسف نے بنی اسرائیل کی قسم کھائی، کہا کہ خدا تم سے ضرور آئے گا، اور تم میری ہڈیاں یہاں سے اٹھاؤ گے۔\n26۔ یوں یوسف فوت ہوا، {100 سالہ} عمر میں: اور اسے مونا کر دیا گیا، اور اسے مصر میں تابوت میں رکھا گیا۔"];
